// SAA シナリオ判断ドリル v2（新規80問・本番フル構成）
// 各問: id, cat, scenario, ask, options[4], answer(0-3 または [配列で複数選択]), keypoint, explain, elim, deep, (任意)confusion, terms, multi
//
// 【選択肢の鉄則】
//  1. 4択すべて「AWSサービスを使った技術的に正しい方法」にする。手作業・現状維持・オンプレ放置・明らかな間違いは入れない。
//  2. 正解と誤答の差は「要件への適合度・コスト・制約の一致度」だけ。知識ゼロで消せるゴミ選択肢を作らない。
//  3. 選択肢の長さは本番にならって不揃いでよい。長い組み合わせ＋設定型もあれば、戦略名・サービス名・コンポーネント名だけの短い選択肢（例:「ウォームスタンバイ」「仮想プライベートゲートウェイ」）もありうる。無理に全部を同じ長さに揃えない。
//  4. 正解位置はA/B/C/Dに散らす。
//
// 【本番再現スタイル（2026-06-19・井内さん指定）】本物のSAA日本語版に寄せる。
//  A. 問題文(scenario)はわざと周りくどく・くどく書く。同じ主語を繰り返す（「同社は…。同社は…。」）、
//     要件を1文ずつ細切れに足す、機械翻訳調のやや不自然な言い回しにする。「読みにくさ・要点の埋もれ」を読み解くのも訓練のうち。
//  B. 略語は「日本語フル (英略)」で初出展開する：目標復旧時間 (RTO)、目標復旧時点 (RPO)、災害対策 (DR) など。
//  C. 主語/行為者は「ある企業」「同社」「ソリューションアーキテクト」を使う。締めは ask に
//     「これらの要件を満たす〜はどれですか。」「最も〜なのはどれですか。」等の定型文を置く。
//  D. 頻出の要件フレーズをそのまま使う：運用上のオーバーヘッドを最小限に抑える／最もコスト効率に優れた／
//     最小限の労力で／可用性を最大化する／実行インスタンス容量を最小限にする。
//  E. 選択肢がサービス名・概念名だけの短文になる問題タイプ（DR戦略、必要なコンポーネントを2つ選べ 等）も作る。
//     その場合 explain/elim/deep に意味を厚く書き、選択肢自体は本番同様そっけなくする。
//  ※ explain/elim/deep の「A=」「B=」等の記号は options の並び順(0=A,1=B,2=C,3=D)と必ず一致させる（並び替え時は追従）。
//
// index.html の <script src="questions.js"> をこのファイルに差し替えれば既存アプリがそのまま動く。

const QUESTIONS = [
{
  id:1, cat:"セキュリティ",
  scenario:"ある企業は、本番環境のワークロードを単一の AWS アカウントおよび 1 つの VPC で運用しています。同社では複数のチームメンバーがこの環境を利用しています。最近になって、同社は、通常は使用していない海外のリージョンで Amazon EC2 インスタンスが起動されていた、発行した記録のない IAM アクセスキーが使用されていた、といった不審なアクティビティが疑われる事象を複数回確認しました。同社のセキュリティチームは少人数で構成されており、脅威を監視するための基盤を自前で構築および運用するための工数を確保することができません。同社は、不正な API 呼び出し、侵害された可能性のある認証情報、マルウェアに感染したインスタンスからの通信といった脅威を、AWS アカウント全体にわたって継続的に検出する必要があります。このソリューションでは、運用上のオーバーヘッドを最小限に抑える必要があります。また、脅威が検出された際には通知を受け取れる必要があります。",
  ask:'これらの要件を満たすソリューションはどれですか。',
  options:[
    "AWS Configでリソースの構成変更をすべて記録し、設定ルールから逸脱したリソースを検出して、コンプライアンス状態の変化をEventBridge経由で通知する。",
    "AWS WAFをALBに関連付けてSQLインジェクションや不正なIPからのリクエストをブロックし、遮断したアクセスのログをCloudWatch Logsに送って監視する。",
    "Amazon InspectorでEC2とコンテナイメージを継続スキャンし、既知の脆弱性（CVE）を検出して、結果をSecurity Hubに集約してリスクの高いものから通知する。",
    "Amazon GuardDutyを有効化し、CloudTrail・VPCフローログ・DNSログを自動分析して脅威を検知させ、検出結果をEventBridge経由でSNSに連携して通知する。"
  ],
  answer:3,
  keypoint:'問われているのは「アカウント全体の<b>脅威検知</b>（不審なAPI・侵害された認証情報・不正通信）を運用負荷少なく」。4つとも本物のセキュリティサービスだが、<b>検知する対象</b>がそれぞれ違う。要件に合うのはどれか。',
  explain:'D＝GuardDutyはCloudTrail・VPCフローログ・DNSログをAWS側が自動で分析し、まさに「不正なAPI呼び出し・侵害された認証情報・不正な通信」を継続検知するマネージドサービス。自前のログ基盤構築が要らず運用上のオーバーヘッドが最小。検出結果はEventBridge経由でSNSに流して通知できる。',
  elim:'A=Configは「構成が決めたルールから外れていないか」を見る（設定逸脱の監視）であって脅威の検知ではない。B=WAFは「アプリ層への攻撃リクエストをブロック」する門番で、アカウント全体の不審な挙動は見ない。C=Inspectorは「脆弱性（パッチ未適用・CVE）」のスキャンで、不正アクセスの検知ではない。すべて正しいサービスだが守備範囲が要件とずれている。',
  confusion:'セキュリティ検知系の役割分担：<b>GuardDuty</b>＝脅威検知（不審な挙動・侵害の兆候）／<b>Inspector</b>＝脆弱性スキャン（CVE・パッチ）／<b>Macie</b>＝S3内の個人情報の発見／<b>Config</b>＝構成が基準から逸脱していないか／<b>Security Hub</b>＝それらの結果を集約するダッシュボード。',
  deep:`
  <div class="dh">🏷 出てきたものの「あだ名」</div>
  <div class="nick"><b>GuardDuty</b>＝アカウントに住み込みの探偵。ログ（誰が何のAPIを叩いた・どこへ通信した）を勝手に読んで「この動き、怪しいですよ」と教える。自分でカメラを設置しなくていい（基盤構築不要）。</div>
  <div class="nick"><b>Inspector</b>＝健康診断。建物の「鍵が古い・窓が壊れている（＝脆弱性）」を点検する。泥棒が入ったかは見ない。</div>
  <div class="nick"><b>Config</b>＝間取りの監査役。「ドアはこの位置と決めたよね？勝手に動かした人いる？」と構成のズレを見る。</div>
  <div class="dh">💡 なぜこれが正解か</div>
  キーワードは「不正なAPI・侵害された認証情報・不正通信」＝<b>侵入や悪用の兆候</b>そのもの。これを継続的に見張るのがGuardDutyの専門。しかもログを自動で読むので少人数チームでも回せる（運用負荷が最小）。
  <div class="dh">⚠️ つまずきやすい言葉</div>
  4つとも「セキュリティを高める正しいサービス」なので消去法が効かない。本番はこう作る。だから「何を検知/防御したいのか」を一語で押さえる＝<b>脅威の検知ならGuardDuty</b>／脆弱性ならInspector／攻撃の遮断ならWAF／構成のズレならConfig。`
},
{
  id:2, cat:"高性能",
  scenario:"ある企業は、モバイルゲームアプリケーションを運用しており、プレイヤーのプロフィールおよびランキングの情報を Amazon DynamoDB テーブルに保存しています。このテーブルに対する読み取りリクエストは 1 日を通して非常に多く発生します。同社は、特にゲーム内イベントの開催中に、同じ人気プレイヤーやトップランキングといった特定の項目へ読み取りが集中することを確認しました。同社は、アプリケーションの応答性能をさらに向上させる必要があります。しかし、現時点でも DynamoDB の読み取りキャパシティーに対するコストが高いため、同社は読み取りキャパシティーを単純に増やすことは避けたいと考えています。同じ項目が繰り返し読み取られることから、同社は、マイクロ秒単位の応答を実現しつつ、DynamoDB テーブルへの読み取りリクエストとそのコストを削減する必要があります。また、同社は、アプリケーションコードの変更を最小限に抑える必要があります。",
  ask:'これらの要件を満たすソリューションはどれですか。',
  options:[
    "DynamoDB Accelerator（DAX）クラスタをテーブルの前段に配置し、読み取りをインメモリキャッシュで返してDynamoDB本体への読み取りとコストを削減する。",
    "DynamoDBのプロビジョニングされた読み取りキャパシティを大幅に引き上げ、Auto Scalingでイベント時のピークに合わせて自動で読み取り能力を増やす。",
    "テーブルにグローバルセカンダリインデックス（GSI）を追加し、人気プレイヤーのデータへのクエリを専用インデックス経由に分散させて読み取りを高速化する。",
    "Amazon ElastiCache（Redis）を別途構築し、アプリ側で読み取り時にキャッシュを確認・更新するロジックを実装してDynamoDBへのアクセスを減らす。"
  ],
  answer:0,
  keypoint:'「DynamoDBの読み取り」「マイクロ秒級」「本体の負荷・コストも下げる」「コード変更最小」。4つとも性能を上げる正しい手だが、<b>DynamoDB専用で・キャッシュ層として・コード変更が最小</b>の条件まで全部満たすのはどれか。',
  explain:'A＝DAXはDynamoDB専用のインメモリキャッシュ。テーブルの前に置くだけで読み取りをマイクロ秒で返し、本体への読み取りリクエストとコストを下げる。DynamoDB APIと互換なのでアプリの改修が最小で済む。',
  elim:'B=キャパシティ増強は速くなるが「コストを下げたい」要件と逆（むしろ増える）。C=GSIは別の検索条件で引くための索引で、同じデータの繰り返し読み取りを速くするキャッシュではない。D=ElastiCacheでも高速化はできるが、キャッシュ確認・更新のロジックを自前で実装する必要があり「コード変更最小」に反する。すべて正しい手段だが、要件適合度でAが最も高い。',
  confusion:'キャッシュの使い分け：<b>DAX</b>＝DynamoDB専用・API互換でコード変更ほぼ不要・マイクロ秒。<b>ElastiCache</b>＝汎用（RDS等どんなデータ源でも前に置けるが、キャッシュ制御を自分で書く）。「DynamoDBだけ」を最小工数で速くするならDAX。',
  deep:`
  <div class="dh">🏷 出てきたものの「あだ名」</div>
  <div class="nick"><b>DAX</b>＝DynamoDB専属の早出し係。よく注文されるメニュー（人気プレイヤーのデータ）を手元に持っていて即出しする。DynamoDBと同じ言葉で話せる（API互換）から、店員（アプリ）はやり方をほぼ変えなくていい。</div>
  <div class="nick"><b>ElastiCache</b>＝どの店にも雇える汎用の早出し係。優秀だが「何を手元に置くか・いつ捨てるか」を店員が指示しないと動かない（＝自前のキャッシュ制御コードが要る）。</div>
  <div class="nick"><b>GSI</b>＝索引の付け替え。「名前で引く」を「スコアで引く」に変える道具で、速さのためのキャッシュではない。</div>
  <div class="dh">💡 なぜこれが正解か</div>
  「同じデータが何度も読まれる」「マイクロ秒」「DynamoDB本体のコストを下げる」「改修は最小」。この4つを一度に満たすのはDynamoDB専用キャッシュのDAXだけ。ElastiCacheでも速くはなるが自前実装が増える分、要件の「コード変更最小」で一歩負ける。
  <div class="dh">⚠️ つまずきやすい言葉</div>
  「キャッシュ＝とりあえずElastiCache」と反射しないこと。<b>対象がDynamoDBに限定＋改修を増やしたくない</b>と書いてあったらDAXを疑う。逆にRDSやその他いろんなデータ源をまとめてキャッシュしたい/細かく制御したいならElastiCache。`
},
{
  id:3, cat:"コスト最適化",
  scenario:"ある企業は、プライベートサブネット内に多数の Amazon EC2 インスタンスを配置し、データ処理基盤を運用しています。これらの EC2 インスタンスは、処理結果を同じリージョンの Amazon S3 バケットに大量に書き込み、別の処理では Amazon DynamoDB にも頻繁にアクセスします。現在、プライベートサブネットから S3 および DynamoDB への通信は、すべて NAT ゲートウェイを経由してインターネットを通って到達しています。同社が月次のコストを確認したところ、NAT ゲートウェイのデータ処理量に対する課金が想定を上回って増加していることが判明しました。S3 および DynamoDB への通信量は今後さらに増加する見込みです。また、同社のセキュリティ要件では、これらの通信をインターネット経由にしないことが求められています。同社は、通信コストを削減し、かつ AWS 内部のプライベートな経路で通信を完結させる必要があります。",
  ask:'これらの要件を満たすソリューションはどれですか。',
  options:[
    "NATゲートウェイを各AZに増設して帯域を分散させ、S3・DynamoDBへの通信が1つのNATに集中しないようにしてデータ処理コストを平準化する。",
    "プライベートサブネットのEC2にパブリックIPを割り当ててインターネットゲートウェイ経由で直接S3・DynamoDBにアクセスさせ、NATゲートウェイを経由しないようにする。",
    "S3とDynamoDB向けにVPCゲートウェイエンドポイントを作成し、ルートテーブルでこれらの宛先をエンドポイント経由にして、NATゲートウェイを通らずAWS内部で完結させる。",
    "S3とDynamoDB向けにAWS PrivateLink（インターフェイスエンドポイント）を作成し、ENI経由でプライベートにアクセスして、時間課金とデータ処理課金を支払う。"
  ],
  answer:2,
  keypoint:'「NATのデータ処理コストを下げる」「S3・DynamoDBへの通信」「インターネットを経由させない」「AWS内部で完結」。S3とDynamoDBに対して<b>追加料金なしでNATを迂回</b>できる正しい手段はどれか。',
  explain:'C＝S3とDynamoDBは「ゲートウェイ型」VPCエンドポイントに対応。ルートテーブルに宛先を追加するだけでNATを通らずAWS内部の経路で到達でき、<b>ゲートウェイエンドポイント自体は追加料金がかからない</b>。NATのデータ処理課金がまるごと消える。',
  elim:'A=NATを増設しても通信量課金は減らない（むしろ基本料金が増える）。B=パブリックIP＋IGWは技術的には通るが「インターネットを経由させたくない」セキュリティ要件に反する。D=PrivateLink（インターフェイス型）でもプライベート到達はできるが、時間課金＋データ処理課金が発生し、無料のゲートウェイ型が使えるS3/DynamoDBではコスト面で不利。すべて正しいが、要件（コスト最小＋内部経路）に最も合うのがC。',
  confusion:'VPCエンドポイント2種：<b>ゲートウェイ型</b>＝S3とDynamoDB専用・<b>追加料金なし</b>・ルートテーブルに足すだけ。<b>インターフェイス型（PrivateLink）</b>＝多くのサービスに対応するがENIの時間課金＋データ処理課金あり。S3/DynamoDBなら無料のゲートウェイ型が定石。',
  terms:[
    {t:"NATゲートウェイ", d:"プライベートサブネットの中→外（インターネット）への通信を取り次ぐ窓口。データ処理量に応じて課金されるので、S3等への大量通信が全部ここを通ると高くつく。"},
    {t:"VPCゲートウェイエンドポイント", d:"VPC内からS3・DynamoDBへ、インターネットを通らずAWS内部の経路で直接つなぐ出入口。利用は無料。ルートテーブルに宛先を追加して使う。"}
  ],
  deep:`
  <div class="dh">🏷 出てきたものの「あだ名」</div>
  <div class="nick"><b>NATゲートウェイ</b>＝表通りに面した取次窓口。中の人が外（インターネット）に用事があるとき必ずここを通る。通った荷物の量だけ料金を取られる（データ処理課金）。S3への大量書き込みが全部ここを通ると高い。</div>
  <div class="nick"><b>ゲートウェイ型エンドポイント</b>＝S3・DynamoDB行きの「敷地内専用の裏口」。表通り（インターネット）に出ずにAWS内部で直結。しかも通行料タダ。</div>
  <div class="nick"><b>インターフェイス型（PrivateLink）</b>＝いろんな部屋に通じる汎用の専用扉。便利だが扉の設置費（時間課金）と通行料（データ処理課金）がかかる。</div>
  <div class="dh">💡 なぜこれが正解か</div>
  「NATコストを消したい」＋「インターネットを通したくない」＝S3/DynamoDBへの専用裏口（ゲートウェイ型エンドポイント）がドンピシャ。内部経路で完結するのでセキュリティ要件も満たし、しかも無料なのでNATのデータ処理課金がまるごと浮く。
  <div class="dh">⚠️ つまずきやすい言葉</div>
  「プライベートに繋ぐ＝PrivateLink（インターフェイス型）」と反射するとDを選んで課金で損する。<b>相手がS3かDynamoDBなら、まず無料のゲートウェイ型を思い出す</b>。インターフェイス型が要るのはそれ以外の多くのサービス（KMS・SQS・各種API等）に内部接続したいとき。`
},
{
  id:4, cat:"セキュリティ",
  scenario:"ある企業は、プライベートサブネットに配置された多数の Amazon EC2 インスタンスを運用しており、運用チームが保守作業のために日常的にこれらのインスタンスへログインしています。現在、同社はパブリックサブネットに踏み台 (bastion) サーバーを配置しており、運用担当者は SSH キーでその踏み台サーバーに接続したうえで、各 EC2 インスタンスへ多段の SSH 接続を行っています。運用の規模が拡大するにつれて、同社では SSH キーペアの配布およびローテーションの管理が負担となっています。さらに、同社は、ポート 22 を開放していることについてセキュリティ上の指摘を受けています。加えて、同社は、誰がいつどのインスタンスでどのような操作を行ったかの記録を残すことを求められるようになりました。同社は、踏み台サーバーと SSH キーの管理を不要にし、ポートを開放せずにインスタンスへアクセスでき、かつ操作ログを保持できる仕組みを必要としています。",
  ask:'これらの要件を満たすソリューションはどれですか。',
  options:[
    "各EC2のセキュリティグループで運用担当者の固定IPからのSSH(22番)のみを許可し、SSHキーペアを定期的にローテーションしながら、パブリックサブネットの踏み台サーバーを経由してアクセスする運用を続ける。",
    "EC2 Instance Connectを使って接続のたびに一時的なSSH公開鍵をインスタンスにプッシュし、開けた22番ポート経由でアクセスして、誰がいつ接続したかをCloudTrailで記録する運用にする。",
    "AWS Client VPNを構築して運用担当者を社内ネットワークに接続し、プライベートIP経由で各EC2へSSHアクセスさせ、踏み台はなくすもののSSHポートと鍵は残したままVPNの接続ログを記録する。",
    "AWS Systems Manager Session Managerを使い、SSMエージェント経由でポート開放もSSHキーも不要なシェルアクセスを行い、操作ログをS3とCloudWatch Logsに記録する。"
  ],
  answer:3,
  keypoint:'「踏み台とSSHキーをなくす」「ポートを開けない」「操作ログを残す」の3条件。4つともAWSの正しいアクセス手段だが、<b>3つ全部を同時に満たす</b>のはどれか。',
  explain:'D＝Session ManagerはSSMエージェント経由でアクセスするため22番ポートを開ける必要がなく、SSHキーも踏み台も不要。操作内容をS3/CloudWatch Logsに記録でき、3条件をすべて満たす。',
  elim:'A=踏み台もSSHキーも22番開放も全部残る（要件と真逆）。B=Instance Connectは一時キーで管理は楽になるが、SSH/22番ポート経由なのでポート開放が残る。C=Client VPNでネットワークには到達できるが、その先のSSHキーと22番開放は残る。すべて正しい接続手段だが、要件適合度でDが突出。',
  confusion:'EC2への接続手段：<b>Session Manager</b>＝ポートレス・キーレス・踏み台レス＋操作ログ（要件全部満たす本命）。<b>Instance Connect</b>＝一時キーだがSSH/22番経由。<b>Client VPN</b>＝ネットワーク接続（その先のSSHは別）。<b>踏み台</b>＝従来型でキー・ポート管理が残る。',
  deep:`
  <div class="dh">🏷 出てきたものの「あだ名」</div>
  <div class="nick"><b>Session Manager</b>＝各EC2に住み込みの内線係（SSMエージェント）。AWSの管理画面から内線で呼べば繋がる。玄関（22番ポート）を開ける必要も、合鍵（SSHキー）を配る必要もない。会話の記録（操作ログ）も自動で残る。</div>
  <div class="nick"><b>踏み台サーバー</b>＝表玄関の受付。外から一度ここに入ってから各部屋へ。受付の鍵管理と玄関の開けっ放しが負担。</div>
  <div class="nick"><b>Instance Connect</b>＝その場限りの合鍵を発行してくれる係。鍵の使い回しは減るが、結局玄関（22番）から入る。</div>
  <div class="dh">💡 なぜこれが正解か</div>
  「キーも踏み台もポート開放もなくしたい＋ログ」を一度に満たすのはSession Managerだけ。他は「キーは一時化したがポートは開く」「ネットワークは繋いだがSSHは残る」と、必ず1つ条件が外れる。
  <div class="dh">⚠️ つまずきやすい言葉</div>
  「キーレスっぽい」Instance Connectに引っかからない。<b>22番ポートを開けるか</b>で線を引く＝Session Managerはポートを一切開けない（ここが他と決定的に違う）。`
},
{
  id:5, cat:"可用性",
  scenario:"ある企業は、東京リージョンで稼働している重要な業務アプリケーションの災害対策 (DR) アーキテクチャを設計しています。同社は、大規模な災害によって東京リージョンが利用できなくなった場合に、大阪リージョンでアプリケーションを復旧できる体制を必要としています。同社は、このアプリケーションの目標復旧時間 (RTO) を数分以内、目標復旧時点 (RPO) をほぼゼロにすることを決定しました。同時に、同社は DR アーキテクチャにかかるコストを最小限に抑える必要があります。同社は、平常時から本番環境とまったく同じ規模のシステムを大阪リージョンで常時稼働させることは避けたいと考えています。",
  ask:'これらの要件を満たす DR 戦略はどれですか。',
  options:[
    "バックアップと復元",
    "パイロットライト",
    "ウォームスタンバイ",
    "マルチサイトアクティブ/アクティブ"
  ],
  answer:2,
  keypoint:'4つともAWSの正しいDR戦略。差は<b>RTO/RPOの速さとコストのトレードオフ</b>。要件（RTO数分・RPOほぼゼロ・ただしフル二重投資は避ける）に一番合う段を選ぶ。',
  explain:'C＝ウォームスタンバイは縮小版を常時動かしデータを継続レプリケーションするのでRPOはほぼゼロ、災害時はスケールアップするだけなのでRTOは数分。フル同規模ではないのでマルチサイトより安く、予算制約も満たす。',
  elim:'A=最安だが災害時に新規構築するためRTOが長い（数分は無理）。B=パイロットライトはコアDBは継続レプリだがアプリ層は災害時に起動するためウォームスタンバイよりRTOが長い。D=マルチサイトはRTO/RPO最良だが同規模を常時2つ動かす＝コスト最大で「フル二重投資は避ける」に反する。RTO/RPOとコストの折り合いでCが要件に最適。',
  terms:[
    {t:"RTO（目標復旧時間）", d:"障害発生から復旧までにかけてよい時間。短いほど高コストな構成が要る。"},
    {t:"RPO（目標復旧時点）", d:"どこまでのデータ損失を許容するか。ほぼゼロ＝継続的なレプリケーションが必要。"},
    {t:"4つのDR戦略", d:"安い順／RTO遅い順に バックアップ&リストア → パイロットライト → ウォームスタンバイ → マルチサイト。"}
  ],
  deep:`
  <div class="dh">🏷 たとえ</div>
  <div class="nick"><b>バックアップ&リストア</b>＝設計図だけ大阪に置く。災害時に一から建てる（安いが遅い）。</div>
  <div class="nick"><b>パイロットライト</b>＝種火だけ灯しておく（コアDBは生きている）。災害時に火を大きくする。</div>
  <div class="nick"><b>ウォームスタンバイ</b>＝小さい店を実際に営業しておく。災害時に即増床（RTO数分・RPOほぼゼロを安く）。</div>
  <div class="nick"><b>マルチサイト</b>＝同じ店を2軒フル営業。最強だが家賃2倍。</div>
  <div class="dh">💡 なぜこれが正解か</div>
  「RTO数分＋RPOほぼゼロ」だけならマルチサイトでも満たすが、「フル二重投資は避ける」が効いてDが脱落。継続レプリ（RPOほぼゼロ）＋スケールアップ（RTO数分）を縮小構成で実現するウォームスタンバイがちょうど真ん中。
  <div class="dh">⚠️ つまずきやすい言葉</div>
  RTO/RPOが「厳しい」ほど右（高コスト）の戦略、「緩い」ほど左（安い）。問題文の数値とコスト制約の<b>両方</b>を見て段を決める。片方だけ見るとDかAに振れて外す。`
},
{
  id:6, cat:"高性能",
  scenario:"ある企業は、世界中のプレイヤーに向けて、リアルタイム対戦型のオンラインゲームのサーバーを運用しています。クライアントとサーバー間の通信は、HTTP ではなく、TCP および UDP を使用する独自のプロトコルで行われます。同社は、サーバーから地理的に離れた場所にいるプレイヤーほど、遅延とパケットロスが大きくなり、対戦の体験が低下することを確認しました。さらに、同社では、クライアント側のファイアウォールの許可リストに登録する必要があるため、接続先が変化しない固定の IP アドレスであることが求められています。このゲームのトラフィックは動的であり、キャッシュすることはできません。同社は、世界中から発生する非 HTTP のトラフィックの遅延を改善し、かつ固定の IP アドレスで受信する必要があります。",
  ask:'これらの要件を満たすソリューションはどれですか。',
  options:[
    "Amazon CloudFrontを前段に置き、世界中のエッジロケーションでコンテンツをキャッシュして遅延を下げ、オリジンサーバーの負荷を減らす。",
    "Amazon Route 53のレイテンシーベースルーティングで、各プレイヤーを最も近いリージョンのエンドポイントにDNSで振り分けて遅延を下げる。",
    "各リージョンにApplication Load Balancerを配置し、CloudFrontのオリジンフェイルオーバーで最寄りのALBを選ばせて遅延を改善する。",
    "AWS Global Acceleratorを使い、AWSのグローバルネットワーク経由で最寄りエッジから最適経路にルーティングし、静的なAnycast IPで受ける。"
  ],
  answer:3,
  keypoint:'「非HTTP（TCP/UDP）」「動的でキャッシュ不可」「固定IP」「グローバルの遅延・パケットロス改善」。4つともグローバル配信/振り分けの正しい手段だが、<b>この4条件を全部満たす</b>のはどれか。',
  explain:'D＝Global AcceleratorはL4でTCP/UDPを扱え（非HTTP対応）、AWS網経由で経路を最適化して遅延・ロスを下げ、変わらないAnycast IP（固定IP）を提供する。動的トラフィック向けで、ゲームに最適。',
  elim:'A=CloudFrontはHTTP/Sのキャッシュ配信向けで、非HTTP・動的・固定IPのどれも満たさない。B=Route53はDNSレベルの振り分けで、AWS網の経路最適化や固定IPは提供しない。C=ALB+CloudFrontはHTTP前提＋固定IPでない。4条件を同時に満たすのはGlobal Acceleratorだけ。',
  confusion:'<b>CloudFront</b>＝HTTP/Sのキャッシュ配信（静的・動的Webコンテンツ）。<b>Global Accelerator</b>＝L4（TCP/UDP含む）の経路最適化＋固定Anycast IP（ゲーム・非HTTP・固定IP要件）。<b>Route53</b>＝DNSでの振り分け（経路最適化も固定IPもしない）。',
  deep:`
  <div class="dh">🏷 たとえ</div>
  <div class="nick"><b>CloudFront</b>＝各国の支店に商品の在庫（キャッシュ）を置いて即配る。動的でキャッシュできないゲーム通信には在庫を置けない。</div>
  <div class="nick"><b>Global Accelerator</b>＝AWS専用の高速道路の入口。プレイヤーは最寄りの入口（エッジ）から渋滞しない専用道（AWS網）で目的地へ。入口の住所（IP）は変わらない。</div>
  <div class="dh">💡 なぜこれが正解か</div>
  ゲームのリアルタイム通信は「キャッシュできない＋HTTPでない＋固定IPが要る」。CloudFront（キャッシュ前提・HTTP）では3つとも外れる。経路そのものを速くし固定IPを出すGlobal Acceleratorが唯一合致。
  <div class="dh">⚠️ つまずきやすい言葉</div>
  「グローバル配信＝とりあえずCloudFront」と反射しない。<b>非HTTP・動的・固定IP</b>のどれかが出たらGlobal Acceleratorを疑う。静的/動的でもHTTPのWeb配信ならCloudFront。`
},
{
  id:7, cat:"コスト最適化",
  scenario:"ある企業は、画像変換やデータ集計などのバッチ処理をコンテナ化し、Amazon ECS の AWS Fargate 起動タイプで実行しています。これらの処理は冪等に設計されており、途中で中断された場合でも、もう一度実行すれば問題なく完了します（中断耐性があります）。処理量の増加に伴い、同社ではコンテナの実行コストが増大しており、同社はこのコストを大幅に削減する必要があります。一方で、同社は、サーバー (Amazon EC2) の運用やパッチ管理を行いたくないと考えています。同社は、中断されても問題のないコンテナのバッチ処理を、サーバーの管理なしで、可能な限り低コストで実行する必要があります。",
  ask:'これらの要件を満たすソリューションはどれですか。',
  options:[
    "ECS on EC2でReserved Instances（1年コミット）を購入して割引を受け、EC2クラスタ上でバッチを実行する。",
    "ECS Fargateのオンデマンドで実行し、Compute Optimizerの推奨に従ってタスクのCPU/メモリを適正化してコストを下げる。",
    "AWS Batchでジョブをマネージドにスケジューリングし、オンデマンドのコンピューティング環境で順番に処理する。",
    "ECS Fargate Spotでバッチを実行し、容量が回収されて中断された場合はタスクを再実行する設計にして、大幅な割引を受ける。"
  ],
  answer:3,
  keypoint:'「中断されてもよい」「サーバー管理なし」「最安」。4つともコンテナを動かす正しい手段だが、<b>中断耐性を活かして最安＋サーバーレス</b>を両立するのはどれか。',
  explain:'D＝Fargate Spotは中断耐性のあるワークロード向けで、Fargateなのでサーバー管理が不要、かつSpot割引で最も安い。中断時に再実行する設計があれば冪等なバッチに最適。',
  elim:'A=ECS on EC2はEC2クラスタの運用・パッチが発生し「サーバー管理したくない」に反する＋中断耐性を活かせない。B=Fargateオンデマンドは管理不要だがSpotより高く、中断耐性を割引に変えていない。C=AWS Batchは管理は楽だがオンデマンド前提でSpotほど安くない。すべて動くが、中断耐性を最安に変換できるのはD。',
  deep:`
  <div class="dh">🏷 たとえ</div>
  <div class="nick"><b>Fargate</b>＝サーバーを自分で持たずにコンテナを動かす（建物の管理を委託）。</div>
  <div class="nick"><b>Spot</b>＝空席を激安で使う代わり、満席になったら席を立たされる（中断）。立ち退いてもやり直せる仕事（冪等バッチ）なら一番得。</div>
  <div class="dh">💡 なぜこれが正解か</div>
  「中断OK」と書いてある＝Spotを使える合図。さらに「サーバー管理なし」でEC2系が消え、Fargate Spotに絞られる。中断耐性をそのまま割引に変える。
  <div class="dh">⚠️ つまずきやすい言葉</div>
  「中断されても再実行すればよい」は<b>Spotを選ばせるキーワード</b>。逆に「中断が許されない常時処理」ならSpotは選ばない（Savings Plans/オンデマンド）。`
},
{
  id:8, cat:"データベース",
  scenario:"ある企業は、E ラーニングの Web アプリケーションを運用しており、そのバックエンドに Amazon Aurora (MySQL 互換) を使用しています。受講生の増加に伴い、同社は、教材一覧やランキングなどの参照系のクエリ (読み取り) が時間帯によって大きく変動し、ピーク時に読み取りの遅延が発生するようになったことを確認しました。一方で、受講ログの記録などの書き込みの負荷には余裕があります。同社は、読み取りの負荷を分散する必要があります。また、同社は、アクセスの増減に応じて処理能力を自動的に調整する必要があります。",
  ask:'これらの要件を満たすソリューションはどれですか。',
  options:[
    "Auroraリードレプリカを構成してリーダーエンドポイント経由で読み取りを分散し、レプリカAuto ScalingでCPU使用率などに応じてレプリカ数を自動増減させる。",
    "AuroraをMulti-AZ配置にして別AZのスタンバイインスタンスにも読み取りクエリを振り分け、可用性を確保しながら読み取りも分散させて、負荷の増減に対応する。",
    "Amazon ElastiCacheをAuroraの前段に置き、頻出する参照クエリの結果をキャッシュして、多様な読み取りクエリをすべてキャッシュ層で肩代わりさせて負荷を下げる。",
    "Aurora Serverless v2に移行し、書き込みも読み取りも単一インスタンスの容量(ACU)自動スケールに任せて、読み取りの分散はせず負荷変動に対応する。"
  ],
  answer:0,
  keypoint:'「読み取りの分散」「変動への自動追従」。4つともAuroraの正しい性能関連手段だが、<b>読み取りを複数に分散しつつ台数を自動増減</b>するのはどれか。',
  explain:'A＝リードレプリカで読み取りを複数インスタンスに分散し、レプリカAuto Scalingで負荷に応じてレプリカ数を自動増減できる。「分散＋自動追従」の両方を満たす。',
  elim:'B=Multi-AZのスタンバイは通常クエリを受けず可用性のための待機（読み取り分散にはならない＝頻出の誤解）。C=ElastiCacheはキャッシュ可能なクエリには効くが多様な参照クエリを「すべて肩代わり」はできず、設問の読み取りスケールそのものの解ではない。D=Serverless v2は容量はスケールするが単一インスタンスで、読み取りを複数に「分散」するわけではない。要件適合でA。',
  confusion:'<b>リードレプリカ</b>＝読み取りを複数台に分散（読み取りスケール）。<b>Multi-AZスタンバイ</b>＝可用性のための待機系（普段クエリを受けない）。混同しやすい最頻出ペア。',
  deep:`
  <div class="dh">🏷 たとえ</div>
  <div class="nick"><b>リードレプリカ</b>＝同じ台帳の「読み取り専用コピー」を何冊も用意し、読む人を分散させる。混んだら自動でコピーを増やす（Auto Scaling）。</div>
  <div class="nick"><b>Multi-AZスタンバイ</b>＝別の建物の控え台帳。普段は使わず、本番が倒れた時だけ昇格する（＝可用性。読み取り分散ではない）。</div>
  <div class="dh">💡 なぜこれが正解か</div>
  欲しいのは「読み取りを分けて捌く＋増減に自動で追従」。コピーを増やして分散するリードレプリカ＋Auto Scalingがそのもの。
  <div class="dh">⚠️ つまずきやすい言葉</div>
  「Multi-AZにすれば読み取りも分散される」は誤り（スタンバイは普段クエリを受けない）。<b>可用性＝Multi-AZ／読み取りスケール＝リードレプリカ</b>を必ず分けて考える。`
},
{
  id:9, cat:"ストレージ",
  scenario:"ある企業は、動画制作を行っており、世界各地の支社から東京リージョンの Amazon S3 バケットへ、1 ファイルあたり数十 GB の動画素材を頻繁にアップロードしています。同社は、東京リージョンから地理的に離れた支社ほど、アップロードに時間がかかり、業務が滞っていることを確認しました。アップロードは毎日発生し、その都度大容量のファイルが送信されます。同社は、アプリケーション側の改修を最小限に抑える必要があります。同社は、遠隔地から S3 バケットへのアップロードを高速化する必要があります。",
  ask:'これらの要件を満たすソリューションはどれですか。',
  options:[
    "各支社の近くのリージョンに中継用のバケットを作り、いったんそこへアップロードしてからクロスリージョンレプリケーションで東京バケットへ非同期に集約して速くする。",
    "CloudFrontのエッジロケーションを経由してS3にアップロードさせ、配信用のエッジキャッシュの仕組みを使ってアップロードのレイテンシまで高速化する。",
    "対象バケットでS3 Transfer Accelerationを有効化し、最寄りのエッジロケーションからAWSのグローバルネットワーク経由で東京バケットへ高速転送する。",
    "各支社にAWS DataSyncのエージェントを立て、スケジュールで東京のS3へ定期的に同期させて、アプリからのアップロードのスループットを底上げする。"
  ],
  answer:2,
  keypoint:'「遠距離アップロードの高速化」「都度の大容量」「最小改修」。4つとも転送/配信の正しい手段だが、<b>S3アップロードを最小改修で高速化</b>するのはどれか。',
  explain:'C＝Transfer Accelerationはバケットで有効化しエンドポイントを変えるだけ（最小改修）で、最寄りエッジからAWS網経由で遠距離アップロードを高速化する。まさにこの用途のための機能。',
  elim:'A=CRRは非同期レプリで「アップロードの高速化」ではない＋構成が複雑。B=CloudFrontは配信（ダウンロード）向けで、アップロード高速化の役割ではない。D=DataSyncはオンプレからの大量データ移行・定期同期向けで、各支社にエージェント運用が必要＝最小改修に反する。要件適合でC。',
  confusion:'<b>Transfer Acceleration</b>＝遠距離のS3アップロードをエッジ経由で高速化（最小改修）。<b>CloudFront</b>＝配信/ダウンロード。<b>DataSync</b>＝大量データの移行・同期（エージェント運用）。<b>CRR</b>＝リージョン間レプリケーション。',
  deep:`
  <div class="dh">🏷 たとえ</div>
  <div class="nick"><b>Transfer Acceleration</b>＝近所の集荷所（エッジ）に出せば、あとはAWS専用便（グローバル網）で東京まで速く運んでくれる。出し方（API）はほぼ同じ＝最小改修。</div>
  <div class="nick"><b>CloudFront</b>＝配る方向（ダウンロード）の宅配網。送る（アップロード）のが主目的ではない。</div>
  <div class="nick"><b>DataSync</b>＝引っ越し業者。大量の荷物をまとめて移すのは得意だが、各拠点に作業員（エージェント）を置く必要がある。</div>
  <div class="dh">💡 なぜこれが正解か</div>
  「都度の遠距離アップロードを、改修少なく速く」＝Transfer Acceleration一択。バケットで有効化＋エンドポイント変更だけで効く。
  <div class="dh">⚠️ つまずきやすい言葉</div>
  CloudFrontは「配信（下り）」、Transfer Accelerationは「アップロード（上り）」の高速化。<b>方向</b>で取り違えない。`
},
{
  id:10, cat:"疎結合",
  scenario:"ある企業は、IoT プラットフォームを運用しており、大量のセンサーデータがリアルタイムで流入しています。同社は、このデータを、リアルタイムの異常検知、ダッシュボード向けの集計、Amazon S3 への長期保管という 3 つの異なる処理系が、それぞれ独立して処理する必要があります。さらに、同社は、いずれかの処理系に障害が発生した場合に、過去数時間分のデータをもう一度読み直して再処理 (リプレイ) する必要があります。加えて、同社は、データの順序を維持する必要があります。",
  ask:'これらの要件を満たすソリューションはどれですか。',
  options:[
    "Amazon SQS標準キューにデータを投入し、複数のコンシューマがそれぞれポーリングして並列に処理し、取り出したメッセージは順次削除していく方式にする。",
    "Amazon SNSトピックにパブリッシュして複数のSQSキューにファンアウトし、各処理系がそれぞれのキューから取り出して独立に処理する構成にする。",
    "Amazon Kinesis Data Streamsに送り、各処理系が独立に同じシャードを読み、保持期間内のデータを順序通りに必要に応じて再処理する。",
    "Amazon SQS FIFOキューを使い、メッセージグループ単位の順序保証と重複排除を効かせて、複数のコンシューマで取りこぼしなく処理させる構成にする。"
  ],
  answer:2,
  keypoint:'「複数の処理系が独立に同じデータを処理」「過去分のリプレイ」「順序保持」。4つとも正しいメッセージング手段だが、<b>3つ全部</b>を満たすのはどれか。',
  explain:'C＝Kinesis Data Streamsはストリームにデータを保持し、複数のコンシューマが独立に同じデータを読め、保持期間内なら何度でも順序通りに読み直せる（リプレイ）。3条件を満たす。',
  elim:'A=SQS標準は順序保証なし＋取得したメッセージは消える（リプレイ不可・複数独立処理に不向き）。B=SNS+SQSファンアウトは複数配信はできるが、配信後にメッセージは消え過去分の読み直し（リプレイ）ができない。D=SQS FIFOは順序はOKだが取得後に消えるためリプレイ不可、複数の独立コンシューマにも向かない。要件適合でC。',
  confusion:'<b>Kinesis</b>＝ストリーム。データを一定期間保持し、複数コンシューマが独立に・順序通り・何度でも読める（リプレイ可）。<b>SQS</b>＝キュー。1回取り出すと消える（リプレイ不可・1処理系向け）。<b>SNS</b>＝配信（fanout）。届けたら終わり。',
  deep:`
  <div class="dh">🏷 たとえ</div>
  <div class="nick"><b>Kinesis</b>＝録画してある番組（データの川）。何人でも好きな所から見られ、巻き戻し（リプレイ）も順番もそのまま。</div>
  <div class="nick"><b>SQS</b>＝受付の伝票スタンド。1人が取ったら無くなる（再生不可・順番は標準だと保証なし）。</div>
  <div class="nick"><b>SNS</b>＝一斉放送。流したらそれっきり（録画は残らない）。</div>
  <div class="dh">💡 なぜこれが正解か</div>
  「複数が独立に読む」「巻き戻して再処理」「順序」＝録画・複数視聴・巻き戻しができるKinesisだけ。キュー（取ったら消える）系では全部は無理。
  <div class="dh">⚠️ つまずきやすい言葉</div>
  「複数の処理系」「リプレイ」「ストリーム」のどれかが出たらKinesisを疑う。1回処理して消えてよいならSQS。`
},
{
  id:11, cat:"セキュリティ",
  scenario:"ある企業は、Amazon RDS (MySQL) のデータベース認証情報と、複数のサードパーティ API のキーを使用してアプリケーションを運用しています。セキュリティ要件として、同社は、これらの認証情報を定期的に自動でローテーション (更新) する必要があります。特に RDS の認証情報については、同社は、データベースと統合された形でローテーションを行う必要があります。同社は、コストよりも、認証情報に関する運用を可能な限り自動化することを優先しています。",
  ask:'これらの要件を満たすソリューションはどれですか。',
  options:[
    "SSM Parameter StoreのSecureStringに認証情報を保存してKMSで暗号化し、Lambdaを自前で定期実行してローテーション処理を実装する。",
    "IAMデータベース認証に切り替え、IAM認証トークンでRDSに接続して認証情報そのものを保持しないようにする。",
    "認証情報をKMSで暗号化してS3に保存し、バージョニングで世代管理しながら定期的に更新する。",
    "AWS Secrets Managerに認証情報を保存し、RDSと統合したマネージドの自動ローテーションを有効化して、アプリはSecrets Manager APIで取得する。"
  ],
  answer:3,
  keypoint:'「自動ローテーション」「RDSと統合」「運用の自動化を優先」。4つとも正しい秘密管理の手段だが、<b>RDS統合の自動ローテーションを標準機能で</b>持つのはどれか。',
  explain:'D＝Secrets ManagerはRDSと統合した自動ローテーションを標準機能として持ち、Lambdaを自作せずにローテーションが回る。運用自動化の要件に最も合う。',
  elim:'A=Parameter Storeは保存・暗号化はできるがローテーションを全部Lambdaで自作する必要があり自動化の手間が大きい。B=IAMデータベース認証は有効な手だがサードパーティAPIキーには使えず、設問の「認証情報のローテーション」とは別アプローチ。C=S3保存は世代管理はできても自動ローテーション機能がない。要件適合でD。',
  confusion:'<b>Secrets Manager</b>＝自動ローテーション・RDS統合あり（やや高コストだが運用自動化）。<b>Parameter Store</b>＝安価だがローテーションは自作。要件に「自動ローテーション」「RDS統合」が出たらSecrets Manager。',
  deep:`
  <div class="dh">🏷 たとえ</div>
  <div class="nick"><b>Secrets Manager</b>＝合鍵を定期的に勝手に作り替えてくれる管理人。RDSとは連携済みで、鍵替えの手続きを全部やってくれる。</div>
  <div class="nick"><b>Parameter Store</b>＝鍵を預かる金庫。預かりと暗号化はするが、鍵替えは自分でスケジュールを組んで実行する（自作）。</div>
  <div class="dh">💡 なぜこれが正解か</div>
  「自動でローテーション＋RDS統合」を箱から出してすぐ使えるのはSecrets Manager。Parameter Storeでも実現できるが自作Lambdaが要る分、運用自動化の要件で一歩負ける。
  <div class="dh">⚠️ つまずきやすい言葉</div>
  「ただ秘密を安全に置きたい」だけならParameter Storeで十分。<b>自動ローテーション・RDS統合</b>が要件に出たらSecrets Managerに上げる、が判断軸。`
},
{
  id:12, cat:"データベース",
  scenario:"ある企業は、グローバルに展開する SaaS を運用しており、本番環境の Amazon Aurora (MySQL 互換) を東京リージョンで稼働させています。データの書き込みは東京リージョンで行われます。同社は、欧州および米国のユーザーから、読み取りが遅いという不満を受けています。これらの地域では、主に参照 (読み取り) が中心です。あわせて、同社は、東京リージョンが災害によって停止した場合に別のリージョンへ切り替える災害対策 (DR) も兼ねたいと考えています。同社は、地域ごとの読み取りのレイテンシーを下げつつ、リージョンの災害への備えを持つ必要があります。",
  ask:'これらの要件を満たすソリューションはどれですか。',
  options:[
    "東京リージョン内にAuroraリードレプリカを複数追加し、リーダーエンドポイント経由で読み取りを分散して、海外を含む各地域からのアクセスを速くする。",
    "CloudFrontでデータベースのクエリ結果を各地のエッジロケーションにキャッシュし、動的に変わるデータも含めて地域ごとの読み取りレイテンシを下げる。",
    "DynamoDBグローバルテーブルに移行し、リレーショナルなデータを各リージョンで読み書きできるマルチリージョン構成に作り替えて、地域レイテンシとDRに対応する。",
    "Auroraグローバルデータベースを構成し、東京をプライマリ、欧州・米国にセカンダリリージョンを置いて、ローカルでの低レイテンシ読み取りと災害時のセカンダリ昇格（DR）を両立する。"
  ],
  answer:3,
  keypoint:'「Aurora前提」「海外の読み取りレイテンシ改善」「リージョン災害のDR」。4つとも低レイテンシ/可用性の手段だが、<b>Auroraのまま地域読み取りとDRを両立</b>するのはどれか。',
  explain:'D＝Auroraグローバルデータベースは他リージョンにセカンダリを置き、その地域でローカルに低レイテンシ読み取りができ、プライマリ障害時はセカンダリを昇格してDRになる。Aurora前提のまま両立する。',
  elim:'A=同一リージョン内のレプリカでは海外からの距離は縮まらない（レイテンシ改善せず）。B=CloudFrontはDBクエリ結果のキャッシュ用途には適さず（動的データ）、DRにもならない。C=DynamoDBグローバルテーブルは有効だがRDB前提のアプリをNoSQLへ作り替える大改修で、設問はAurora。要件適合でD。',
  confusion:'<b>Auroraグローバルデータベース</b>＝RDBのまま複数リージョン読み取り＋DR。<b>DynamoDBグローバルテーブル</b>＝NoSQLのマルチリージョン読み書き（アプリがNoSQL前提なら）。<b>リードレプリカ</b>＝同一リージョン内の読み取り分散（海外レイテンシは縮まない）。',
  deep:`
  <div class="dh">🏷 たとえ</div>
  <div class="nick"><b>Auroraグローバルデータベース</b>＝東京の本店の写しを欧州・米国にも置く。現地の人は近くの写しを読めて速い。本店が倒れたら写しを本店に昇格（DR）。</div>
  <div class="nick"><b>同一リージョンのリードレプリカ</b>＝東京の中でコピーを増やすだけ。欧州から東京までの距離は縮まらない。</div>
  <div class="dh">💡 なぜこれが正解か</div>
  「Aurora」「海外の読み取りを速く」「リージョンDR」の3つを、データベースを作り替えずに満たすのはAuroraグローバルデータベース。同一リージョンのレプリカでは海外距離が縮まらず外す。
  <div class="dh">⚠️ つまずきやすい言葉</div>
  「リードレプリカで読み取り改善」は<b>同一リージョン内</b>の話。<b>地域（リージョン）をまたぐ</b>低レイテンシ＋DRが要件ならグローバルデータベース。`
},
{
  id:13, cat:"コスト最適化",
  scenario:"ある企業は、多数の Amazon EC2 インスタンスで汎用 SSD (gp2) の Amazon EBS ボリュームを使用しています。コストの見直しを進める中で、同社は、gp2 ではボリュームのサイズに比例して IOPS が決まる仕組みであるため、必要な IOPS を確保する目的で、実際の使用量よりも大きな容量を割り当てている例が多いことを確認しました。同社は、ストレージの性能を低下させることなく (必要な性能は確保しつつ)、EBS のコストを削減する必要があります。",
  ask:'これらの要件を満たすソリューションはどれですか。',
  options:[
    "ボリュームをgp2からgp3に変更し、容量とIOPS/スループットを独立して設定することで、必要な性能を確保しつつ単価の安いgp3でコストを下げる。",
    "gp2のまま運用を続け、不要なボリュームのスナップショットを取得して削除し、Storage Lensでコストを可視化して無駄を洗い出す。",
    "ボリュームをio2 Block Expressに変更し、高いプロビジョンドIOPSで性能を保証して安定させる。",
    "ボリュームをスループット最適化HDD（st1）に変更し、ストレージ単価の安いHDD系にしてコストを下げる。"
  ],
  answer:0,
  keypoint:'「性能は落とさない（むしろ確保）」「コストを下げる」。4つとも正しいEBS関連の手だが、<b>性能維持とコスト削減を同時に</b>満たすのはどれか。',
  explain:'A＝gp3は容量とIOPS/スループットを独立して設定でき、必要な性能を保ちながら容量を増やす必要がなく、gp2より単価が安い。性能維持＋コスト減を両立する。',
  elim:'B=可視化や整理はできるがボリューム単価そのものは下がらない。C=io2 Block Expressは高性能だが高コストで、コスト削減の要件と逆。D=st1（HDD）は単価は安いがランダムIOの性能が大きく落ち、汎用ワークロードの性能要件に反する。要件適合でA。',
  terms:[
    {t:"gp2", d:"汎用SSD。容量に比例してIOPSが決まるため、性能のために容量を盛りがち。"},
    {t:"gp3", d:"次世代の汎用SSD。容量とIOPS/スループットを独立設定でき、gp2より約2割安い。多くの汎用用途でgp2からの移行が定石。"}
  ],
  deep:`
  <div class="dh">🏷 たとえ</div>
  <div class="nick"><b>gp2</b>＝「広い部屋を借りるほど速くなる」プラン。速さが欲しいだけなのに広い部屋（大容量）を借りて余分に払っている。</div>
  <div class="nick"><b>gp3</b>＝「部屋の広さ」と「速さ」を別々に選べるプラン。必要な速さだけ買えて、しかも基本料が安い。</div>
  <div class="dh">💡 なぜこれが正解か</div>
  「性能は確保＋コスト減」の王道がgp2→gp3。性能と容量を切り離せるので、速さのために容量を盛る無駄が消え、単価も下がる。
  <div class="dh">⚠️ つまずきやすい言葉</div>
  io2は「もっと速く・止められない」用途（高コスト）、HDD（st1/sc1）は「大量を安く・速度二の次」用途。<b>汎用で性能維持しつつ安く＝gp3</b>がほぼ定番。`
},
{
  id:14, cat:"サーバーレス",
  scenario:"ある企業は、注文処理のワークフローを構築しています。この処理は、在庫確認、決済、配送手配、通知という複数のステップを順番に実行します。同社は、途中のステップで失敗した場合にはリトライを行い、条件によっては分岐する必要があります。現在、同社は 1 つの巨大な AWS Lambda 関数の中に、すべてのステップと分岐およびリトライのロジックを詰め込んでいます。そのため、同社では、どのステップで失敗したかを追跡することができず、保守も困難になっています。同社は、各ステップの状態管理、リトライ、分岐を、コードに埋め込むのではなく、可視化された形で管理する必要があります。",
  ask:'これらの要件を満たすソリューションはどれですか。',
  options:[
    "各ステップを個別のLambdaに分割し、前のLambdaが次のLambdaを直接呼び出すチェーンにして、各関数内でリトライ処理を実装する。",
    "Amazon EventBridgeのルールで各ステップの完了イベントを次のステップに連携し、イベント駆動で順番に処理を進める。",
    "Amazon SQSキューを各ステップの間に挟み、ステップごとのLambdaがキューを介して順番に処理を引き継いでいく構成にする。",
    "AWS Step Functionsでステートマシンを定義し、各ステップ・リトライ・分岐をワークフローとして宣言的に管理し、実行状況を可視化する。"
  ],
  answer:3,
  keypoint:'「複数ステップの順序・リトライ・分岐」「コードに埋め込まず可視化して管理」。4つとも連携の正しい手段だが、<b>ワークフローのオーケストレーションを宣言的に可視化</b>するのはどれか。',
  explain:'D＝Step Functionsはステップ・リトライ・分岐・エラー処理をステートマシンとして宣言的に定義し、実行状況を視覚的に追える。まさに「状態管理を可視化して管理」する用途。',
  elim:'A=Lambda直接チェーンは状態・リトライ・分岐がコードに散らばり、可視化されず保守も困難（今と同じ問題）。B=EventBridgeはイベント連携は得意だが、複雑な順序・分岐・リトライを持つワークフローの一元管理・可視化には向かない。C=SQSで繋ぐと疎結合にはなるが分岐や全体の状態管理・可視化は自前。要件適合でD。',
  confusion:'<b>Step Functions</b>＝順序・分岐・リトライを持つワークフローのオーケストレーション（可視化）。<b>SQS/EventBridge</b>＝コンポーネント間の疎結合な連携（全体の状態管理はしない）。「複数ステップ・分岐・リトライ・可視化」が出たらStep Functions。',
  deep:`
  <div class="dh">🏷 たとえ</div>
  <div class="nick"><b>Step Functions</b>＝料理の手順表（レシピ）を見える形で持つ司令塔。「この工程が失敗したら3回やり直す」「条件でこっちの工程へ」を表に書いておき、今どの工程かも一目でわかる。</div>
  <div class="nick"><b>Lambdaチェーン</b>＝各担当が次の担当を口頭で呼ぶ方式。誰がどこで止まったか全体が見えない。</div>
  <div class="dh">💡 なぜこれが正解か</div>
  「順序＋分岐＋リトライ＋可視化」を、コードでなく定義で持てるのがStep Functions。失敗箇所が一目でわかり保守が楽になる。
  <div class="dh">⚠️ つまずきやすい言葉</div>
  SQS/EventBridgeは「つなぐ」のは得意でも「全体の段取りを管理・可視化」はしない。<b>ワークフロー（順序・分岐・リトライ）の管理</b>が主題ならStep Functions。`
},
{
  id:15, cat:"高性能",
  scenario:"ある企業は、ニュースメディアの Web サイトを運用しています。このサイトは、記事ページを表示するたびに、Amazon RDS (MySQL) に対して同じ人気記事のクエリを大量に発行しています。同社は、アクセスのほとんどが少数の人気記事に集中しており、同じ結果が何度も読み出されていることを確認しました。RDS の読み取り負荷が高く、応答性能が低下しています。一方で、記事の内容が更新される頻度は低く、多少古い内容が一時的に表示されても問題ありません。同社は、RDS への繰り返しの読み取りを減らし、応答性能を改善する必要があります。",
  ask:'これらの要件を満たすソリューションはどれですか。',
  options:[
    "RDSをMulti-AZ配置にして別AZのスタンバイにも読み取りクエリを振り分け、読み取り負荷を分散して全体のレスポンスを改善する。",
    "RDSのインスタンスクラスをより上位のタイプへスケールアップしてCPUとメモリを増やし、同じクエリの集中による読み取りをそのまま捌いて高速化する。",
    "Amazon ElastiCache（Redis）をRDSの前段に置き、人気記事のクエリ結果をキャッシュして、繰り返しの読み取りをRDSではなくキャッシュから返す。",
    "RDSリードレプリカを複数追加して読み取りクエリをレプリカへ分散し、プライマリの負荷を下げることで繰り返しの参照にも対応する。"
  ],
  answer:2,
  keypoint:'「同じ結果の繰り返し読み取り」「更新頻度低・多少古くてOK」「RDS負荷を減らす」。4つとも性能改善の正しい手だが、<b>繰り返し読み取りをキャッシュで肩代わり</b>するのが一番効くのはどれか。',
  explain:'C＝ElastiCacheに人気記事の結果をキャッシュすれば、繰り返しの読み取りがRDSに届かずキャッシュから即返る。更新頻度が低く多少の陳腐化が許される本ケースはキャッシュの典型的な好適ケース。',
  elim:'A=Multi-AZスタンバイは普段読み取りを受けない（可用性用・誤解頻出）。B=スケールアップは効くが繰り返し同一クエリの無駄は残りコスト効率が悪い。D=リードレプリカは読み取り分散には有効だが、同じ結果を何度も読む無駄はRDS群で発生し続ける。キャッシュ向きの特性（同一・低更新）にはCが最適。',
  confusion:'<b>ElastiCache</b>＝同じ結果の繰り返し読み取りをキャッシュで肩代わり（更新少・同一クエリ多に最適）。<b>リードレプリカ</b>＝多様な読み取りを複数台に分散。<b>Multi-AZ</b>＝可用性（読み取り分散ではない）。',
  deep:`
  <div class="dh">🏷 たとえ</div>
  <div class="nick"><b>ElastiCache</b>＝よく聞かれる質問の答えを手元のメモ（インメモリ）に貼っておく受付。同じ質問は奥（RDS）に取りに行かず即答する。</div>
  <div class="nick"><b>リードレプリカ</b>＝受付の人数を増やす。質問の総量は変わらないが手分けできる。</div>
  <div class="dh">💡 なぜこれが正解か</div>
  「同じ結果を何度も」「古くてもOK」＝キャッシュがドンピシャ。RDSに届く前に返すので負荷が根本から減る。
  <div class="dh">⚠️ つまずきやすい言葉</div>
  リードレプリカは「分散」、ElastiCacheは「そもそもDBに行かせない」。<b>同一クエリの繰り返し＋陳腐化許容</b>ならキャッシュを優先。`
},
{
  id:16, cat:"可用性",
  scenario:"ある企業は、Application Load Balancer、Auto Scaling グループ内の Amazon EC2 インスタンス、Amazon RDS で構成される 3 層構成の Web アプリケーションを運用しています。あるとき、同社では、一部の EC2 インスタンスが OS レベルでハングし、アプリケーションが応答しないにもかかわらず、インスタンス自体は起動中のままという状態が発生しました。Application Load Balancer はそのインスタンスにもリクエストを送り続け、一部のユーザーがエラーになりました。同社は、異常なインスタンスを自動的に検知して切り離し、健全な新しいインスタンスに置き換える必要があります。",
  ask:'これらの要件を満たすソリューションはどれですか。',
  options:[
    "CloudWatchアラームでEC2のCPU使用率を監視し、閾値を超えたら管理者にSNSで通知して、担当者が状況を確認してから手動で再起動や切り離しの対応をできるようにする。",
    "Auto Scalingグループの希望台数を常にピークより多めに設定して冗長性を持たせ、一部のインスタンスが異常になっても全体としては応答を返せるようにする。",
    "RDSをMulti-AZにしてデータベース層の可用性を高め、EC2側で障害が起きてもデータ層は継続するようにして、全体の耐障害性を上げる。",
    "ALBのヘルスチェックでアプリ層（HTTP応答）を確認し、異常なインスタンスへの振り分けを停止したうえで、Auto ScalingグループのヘルスチェックタイプをELBにして異常インスタンスを終了・置換させる。"
  ],
  answer:3,
  keypoint:'「アプリは応答しないがインスタンスは起動中」「異常を検知して切り離し＋置換」。4つとも可用性に関わる正しい設定だが、<b>アプリ層の異常を検知して自動で置き換える</b>のはどれか。',
  explain:'D＝ALBのヘルスチェックでHTTP応答（アプリ層）の異常を検知して振り分けを止め、Auto ScalingのヘルスチェックをELB連動にすると異常インスタンスが終了・自動置換される。「自動で切り離し＋置換」を満たす。',
  elim:'A=CPU監視＋通知では手動対応になり「自動置換」にならない＋アプリのハングはCPUに出ないことがある。B=台数を増やしても異常インスタンスは残りエラーを返し続ける（切り離し・置換がない）。C=RDS Multi-AZはデータ層の話でEC2のハングは解決しない。要件適合でD。',
  confusion:'Auto Scalingのヘルスチェック：<b>EC2タイプ</b>＝インスタンスの状態だけ見る（OSハングでも起動中なら健全扱い）。<b>ELBタイプ</b>＝ALBのヘルスチェック（アプリ応答）を見て異常なら置換。アプリ層の異常を拾うにはELBタイプにする。',
  deep:`
  <div class="dh">🏷 たとえ</div>
  <div class="nick"><b>ALBヘルスチェック</b>＝案内係が各レジに「ちゃんと営業してる？」と声をかけ、返事のないレジ（アプリ無応答）には客を回さない。</div>
  <div class="nick"><b>Auto ScalingのELBヘルスチェック連動</b>＝「返事がないレジは閉めて新しいレジを開ける」を自動でやる店長。</div>
  <div class="dh">💡 なぜこれが正解か</div>
  問題は「インスタンスは生きているがアプリが死んでいる」。EC2の生死だけ見るEC2タイプでは見逃す。ALBのアプリ応答チェック＋ASのELB連動で、検知→切り離し→置換が自動で回る。
  <div class="dh">⚠️ つまずきやすい言葉</div>
  「Auto Scalingにしてるから自動回復するはず」だけでは不十分。<b>ヘルスチェックタイプがEC2のままだとアプリのハングを拾えない</b>。ELBタイプにして初めてアプリ層の異常で置換される。`
},
{
  id:17, cat:"セキュリティ",
  scenario:"ある企業は、Amazon S3 バケットに大量の顧客データを保存しています。同社は、データ分析チームのメンバーにはバケットの内容を読み取らせたいと考えていますが、誤った操作や認証情報の漏洩によってオブジェクトが削除または改ざんされることは絶対に避ける必要があります。さらに、コンプライアンス上の理由から、同社は、保存したオブジェクトを、一定期間は管理者を含む誰もが削除または上書きできない状態で保持する必要があります。同社は、データの読み取りは許可しつつ、改ざんおよび削除を技術的に防止する必要があります。",
  ask:'これらの要件を満たすソリューションはどれですか。',
  options:[
    "バケットポリシーとIAMポリシーで分析チームには読み取り専用の権限のみを付与し、削除や上書きの権限を与えないことで、運用上の誤操作によるデータ消失を防ぐ。",
    "S3バージョニングを有効化し、オブジェクトが削除・上書きされても以前のバージョンから復元できるようにして、実質的にデータを保護できるものとして運用する。",
    "S3 Object Lock（コンプライアンスモード）をバージョニング済みバケットで有効化し、保持期間中は管理者を含む誰もがオブジェクトを削除・上書きできないようにする。",
    "オブジェクトをS3 Glacier Deep Archiveに移して取り出しに時間がかかる状態にすることで、頻繁には触れず簡単には変更・削除されない状態で長期保管する。"
  ],
  answer:2,
  keypoint:'「読み取りは許可」「一定期間は管理者すら削除・改ざん不可」。4つとも保護の手段だが、<b>権限ではなく技術的に不変（WORM）を強制</b>するのはどれか。',
  explain:'C＝Object Lockのコンプライアンスモードは、保持期間中はルートユーザー/管理者を含め誰もオブジェクトを削除・上書きできない（WORM）。「管理者すら不可」という要件を技術的に満たす唯一の選択肢。',
  elim:'A=IAMで削除権限を与えなくても、権限を持つ管理者や設定変更で削除可能になり得る（「管理者すら不可」を保証しない）。B=バージョニングは復元できるが、削除・上書き自体は起こる（不変ではない）。D=Glacier Deep Archiveは取り出しが遅いだけで削除・改ざんは可能。技術的な不変性を満たすのはCのみ。',
  confusion:'<b>Object Lock（コンプライアンスモード）</b>＝保持期間中は管理者含め削除・上書き不可（WORM・規制対応）。<b>ガバナンスモード</b>＝特権ユーザーは解除可。<b>バージョニング</b>＝復元はできるが不変ではない。「管理者すら不可」が出たらコンプライアンスモード。',
  terms:[
    {t:"WORM", d:"Write Once Read Many。一度書いたら期間中は変更・削除できず読み取りのみ可能な保護方式。規制対応で求められる。"},
    {t:"Object Lockのモード", d:"コンプライアンスモード＝誰も(管理者も)解除不可／ガバナンスモード＝特権権限で解除可。"}
  ],
  deep:`
  <div class="dh">🏷 たとえ</div>
  <div class="nick"><b>IAMで削除権限を与えない</b>＝「削除しないでね」とルールで頼む。管理者は鍵を持っているので破れる。</div>
  <div class="nick"><b>Object Lockコンプライアンスモード</b>＝金庫に時限ロックをかける。期間が来るまで社長でも開けられない（技術的に不変）。</div>
  <div class="dh">💡 なぜこれが正解か</div>
  「管理者すら削除できない」は権限設計では保証できない（権限はいつでも変えられる）。期間中の物理的な不変性を強制するObject Lockだけが要件を満たす。
  <div class="dh">⚠️ つまずきやすい言葉</div>
  「読み取り専用にすれば守れる」はIAMの話で、特権者には穴がある。<b>改ざん・削除を"誰であっても"防ぐ</b>＝Object Lock（WORM）。`
},
{
  id:18, cat:"コスト最適化",
  scenario:"ある企業は、メディアサービスを運用しており、ユーザーが投稿した画像、サムネイル、元データを大量に Amazon S3 に保存しています。これらのオブジェクトはアクセスパターンがばらばらで、急に人気が出て頻繁にアクセスされたり、しばらく誰もアクセスしなかったりと、予測することができません。同社が手動でライフサイクルポリシーを設定しても、どのオブジェクトがいつアクセスされるかを読めないため、最適なストレージクラスを当てることができません。同社は、アクセス頻度が予測できないデータの保管コストを、運用の手間をかけずに自動で最適化する必要があります。",
  ask:'これらの要件を満たすソリューションはどれですか。',
  options:[
    "作成から30日でStandard-IAへ、90日でGlacier Flexible Retrievalへ移行するライフサイクルポリシーを固定で設定する。",
    "すべてをS3 One Zone-IAに保存し、単一AZにすることでストレージ単価を下げてコストを最適化する。",
    "すべてS3 Standardに置き、Storage Lensでアクセス傾向を分析して、人間が定期的に適切なストレージクラスへ手動で移す。",
    "S3 Intelligent-Tieringに保存し、アクセスパターンの監視と階層間の移動をAWSに自動判定させて、頻繁・低頻度・アーカイブを自動で振り分ける。"
  ],
  answer:3,
  keypoint:'「アクセスパターンが予測不能」「手動ライフサイクルが当てられない」「手間なく自動最適化」。4つとも保管コストの手段だが、<b>予測不能なデータを自動で階層移動</b>するのはどれか。',
  explain:'D＝Intelligent-TieringはアクセスパターンをAWSが監視して頻繁/低頻度/アーカイブ階層へ自動移動する。アクセスが読めないデータに対し、手動設定なしでコストを最適化できる。',
  elim:'A=固定ライフサイクルはアクセスが予測できる場合は有効だが、本ケースは予測不能なので最適階層を外す。B=One Zone-IAは単価は下がるが可用性が落ち、かつアクセス予測不能への自動最適化ではない（頻繁アクセスだと取り出し課金で割高にも）。C=人手で移すのは「手間なく」に反する。要件適合でD。',
  confusion:'<b>Intelligent-Tiering</b>＝アクセス予測不能なデータを自動で階層移動（手間なし）。<b>固定ライフサイクル</b>＝アクセス傾向が読める時に有効（予測前提）。アクセスパターンが読めない＝Intelligent-Tiering。',
  deep:`
  <div class="dh">🏷 たとえ</div>
  <div class="nick"><b>固定ライフサイクル</b>＝「30日たったら倉庫の奥へ」と決め打ち。よく出る商品も問答無用で奥に送ってしまう。</div>
  <div class="nick"><b>Intelligent-Tiering</b>＝出入りを見ている倉庫番。よく出る物は手前、出ない物は奥へ自動で動かす。人は何もしない。</div>
  <div class="dh">💡 なぜこれが正解か</div>
  「いつアクセスされるか読めない」と書いてある＝決め打ちの固定ライフサイクルが外れる合図。監視して自動で動かすIntelligent-Tieringが適任。
  <div class="dh">⚠️ つまずきやすい言葉</div>
  「直近30日はよく見て以降は見ない」のように<b>パターンが読める</b>なら固定ライフサイクル（安い）。<b>読めない</b>ならIntelligent-Tiering。問題文の"予測できる/できない"で切る。`
},
{
  id:19, cat:"疎結合",
  scenario:"ある企業は、E コマースサイトを運用しています。注文が確定すると、在庫システムの在庫を減らす、会計システムに売上を計上する、メール送信サービスで確認メールを送る、という 3 つの異なるシステムが、それぞれ独立に同じ「注文確定」イベントを受け取って処理する必要があります。同社は、将来さらに処理を追加する可能性があると考えています。同社は、注文確定の発生元 (プロデューサー) が、受け手の数や種類を意識せずにイベントを送信できる、疎結合な構成にする必要があります。",
  ask:'これらの要件を満たすソリューションはどれですか。',
  options:[
    "注文サービスが在庫・会計・メールの各サービスのAPIを順番に直接呼び出して3つの処理を連携させ、どれかが遅延・失敗したら呼び出し元でリトライする構成にする。",
    "1つのSQSキューに注文確定メッセージを入れ、在庫・会計・メールの3システムが同じキューを共有して、それぞれがメッセージを取り出して処理する構成にする。",
    "Amazon SNSトピックに『注文確定』をパブリッシュし、在庫・会計・メール用にそれぞれサブスクライブしたSQSキューへファンアウトして各システムが独立に処理する。",
    "Amazon Kinesis Data Streamsに注文確定イベントを流し、在庫・会計・メールの3システムが同じストリームをコンシューマとしてそれぞれ独立に読み取って処理する構成にする。"
  ],
  answer:2,
  keypoint:'「1つのイベントを複数システムが各自処理」「発生元は受け手を意識しない」「将来追加もある」。4つとも連携の手段だが、<b>1対多の配信＋各受け手が確実に自分のコピーを得る</b>のはどれか。',
  explain:'C＝SNS（fanout）＋SQSは、1つのイベントを複数のキューに同報し、各システムが自分のキューから独立に処理できる。受け手の追加もサブスクライブを足すだけで、発生元は影響を受けない（疎結合）。',
  elim:'A=直接API呼び出しは発生元が受け手を全部知る必要があり密結合＋1つ落ちると連鎖失敗。B=単一SQSを共有すると1メッセージは1コンシューマしか取れず「3システムが各自処理」できない。D=Kinesisでも複数読み取りは可能だが、本ケースは「1対多のイベント通知＋各自バッファ」が要件でSNS+SQSが定石（リプレイや順序が主題ならKinesis）。要件適合でC。',
  confusion:'<b>SNS+SQS（fanout）</b>＝1イベントを複数の受け手へ同報し各自バッファ（1対多通知の定番）。<b>単一SQS</b>＝1メッセージ1コンシューマ（1対多にならない）。<b>Kinesis</b>＝ストリーム保持・リプレイ・順序が要る時。',
  deep:`
  <div class="dh">🏷 たとえ</div>
  <div class="nick"><b>SNS</b>＝一斉放送（拡声器）。「注文が入りました」を関係部署全部に同時に流す。</div>
  <div class="nick"><b>各部署のSQS</b>＝放送を各部署が自分の受信箱に貯めて、自分のペースで処理する。</div>
  <div class="nick"><b>単一SQSの共有</b>＝1枚の伝票を取り合う。誰か1部署が取ったら他は処理できない（1対多にならない）。</div>
  <div class="dh">💡 なぜこれが正解か</div>
  「1つのイベントを3システムが各自処理」＝拡声器（SNS）で同報し、各自の受信箱（SQS）に貯める形。受け手を足すのも放送の購読者を増やすだけ＝発生元は無関係（疎結合）。
  <div class="dh">⚠️ つまずきやすい言葉</div>
  単一SQSは「1対1」（取ったら消える）。<b>1つを複数に届けたい＝SNSでfanout</b>。リプレイや順序が要件に出たらKinesisに寄せる。`
},
{
  id:20, cat:"高性能",
  scenario:"ある企業は、ハイパフォーマンスコンピューティング (HPC) の数値シミュレーションを、多数の Amazon EC2 インスタンスを使用して実行しています。計算ノード間では大量のデータを頻繁にやり取りするため、同社は、ノード間のネットワーク遅延がジョブ全体の完了時間に直結することを確認しました。同社は、インスタンス同士の通信を可能な限り低遅延かつ高スループットにして、密結合な並列計算の性能を最大化する必要があります。",
  ask:'これらの要件を満たすソリューションはどれですか。',
  options:[
    "複数AZにEC2を分散配置してAuto Scalingで台数を増やし、可用性を確保しながら計算リソースを水平に拡張して、HPCの処理能力を上げる。",
    "各EC2に高いプロビジョンドIOPSのEBS（io2）を付けてストレージI/Oを高速化し、ディスク待ちを減らすことで計算ジョブ全体のスループットを上げる。",
    "EC2をクラスタープレイスメントグループに配置し、同一AZ内で物理的に近接させて、Elastic Fabric Adapter（EFA）で低遅延・高帯域のノード間通信を実現する。",
    "計算ノードの前段にApplication Load Balancerを置いてジョブを各ノードへ分散し、ノード間の負荷を均等化することでHPCの性能を引き出す。"
  ],
  answer:2,
  keypoint:'「HPCで密結合」「ノード間通信の遅延がボトルネック」「低遅延・高スループットにしたい」。4つとも性能関連だが、<b>ノード間ネットワークを最速化</b>するのはどれか。',
  explain:'C＝クラスタープレイスメントグループは同一AZ内でインスタンスを物理的に近接配置し、EFAと組み合わせるとノード間が極めて低遅延・高帯域になる。密結合HPCの性能最大化の定石。',
  elim:'A=複数AZ分散はむしろAZ間でノード間遅延が増えHPCに逆効果＋可用性の話で論点違い。B=EBS io2はストレージI/Oであってノード間ネットワーク遅延は改善しない。D=ALBはHTTP系のリクエスト分散で、HPCのノード間通信の最適化ではない。要件適合でC。',
  confusion:'プレイスメントグループ：<b>クラスター</b>＝同一AZで近接配置・低遅延高帯域（HPC・密結合）。<b>スプレッド</b>＝物理ハードを分けて可用性。<b>パーティション</b>＝大規模分散（HDFS等）。ノード間低遅延＝クラスター＋EFA。',
  deep:`
  <div class="dh">🏷 たとえ</div>
  <div class="nick"><b>クラスタープレイスメントグループ</b>＝計算担当者を同じ部屋の隣同士に座らせる。声をかければ即届く（低遅延）。</div>
  <div class="nick"><b>EFA</b>＝隣同士をつなぐ専用の太いパイプ（高帯域・低遅延の特殊ネットワーク）。</div>
  <div class="nick"><b>複数AZ分散</b>＝担当者を別々のビルに置く。可用性は上がるが会話（ノード間通信）に時間がかかりHPCには逆効果。</div>
  <div class="dh">💡 なぜこれが正解か</div>
  HPCの密結合計算は「ノード間の会話の速さ」が命。近接配置（クラスター）＋専用パイプ（EFA）が直球。可用性のための分散はここでは害になる。
  <div class="dh">⚠️ つまずきやすい言葉</div>
  「可用性＝複数AZ分散」は正しいが、HPCの<b>ノード間低遅延</b>とは目的が逆（分散すると遅くなる）。要件が「通信を速く」ならクラスター＋EFA。`
},
{
  id:21, cat:"ストレージ",
  scenario:"ある企業は、製造業を営んでおり、オンプレミスの NAS に数十 TB の設計データを保持しています。同社は、これを AWS へ移行したいと考えていますが、移行後もしばらくはオンプレミスの既存アプリケーションから頻繁にアクセスします。そのため、同社は、よく使うデータは低遅延でローカルに置きつつ、データの実体はクラウド (Amazon S3) に保管して、オンプレミスのストレージ容量を削減する必要があります。また、既存のアプリケーションから NFS/SMB を使用して従来どおりアクセスできることが必須です。",
  ask:'これらの要件を満たすソリューションはどれですか。',
  options:[
    "AWS Storage Gateway（ファイルゲートウェイ）をオンプレに置き、NFS/SMBで従来通りアクセスさせつつ実体をS3に保存し、頻繁に使うデータをローカルにキャッシュする。",
    "AWS DataSyncでNASのデータを一括でS3へ転送し、移行が完了したらオンプレのアプリの参照先をS3 APIに切り替えて、従来のファイル共有はやめる方式にする。",
    "オンプレに大容量のストレージを増設してそこにデータを置き、定期的にS3へスナップショットをバックアップして保護し、容量不足はその都度増設で対応する。",
    "Amazon EFSをオンプレの各サーバーからマウントして共有ファイルストレージとして使い、容量を気にせずデータを置けるようにして、NASを置き換える。"
  ],
  answer:0,
  keypoint:'「NFS/SMBで従来通り」「実体はS3」「よく使う分はローカルキャッシュ」「オンプレ容量削減」。4つとも移行/共有の手段だが、<b>4条件を満たすハイブリッド</b>はどれか。',
  explain:'A＝Storage Gateway（ファイルゲートウェイ）はオンプレにNFS/SMBインターフェースを提供しつつ実体をS3に保存し、頻繁アクセス分をローカルにキャッシュする。まさにこのハイブリッド要件のためのサービス。',
  elim:'B=DataSyncは一括移行向けで、移行後にアプリをS3 APIへ改修する必要があり「NFS/SMBで従来通り」に反する。C=EBS増設はオンプレ容量削減に逆行（容量を使う）。D=EFSはAWS内のLinux向け共有FSで、オンプレNASの実体をS3に逃がしてローカルキャッシュする用途ではない。要件適合でA。',
  confusion:'<b>Storage Gateway（ファイルゲートウェイ）</b>＝オンプレにNFS/SMB窓口＋実体S3＋ローカルキャッシュ（ハイブリッド）。<b>DataSync</b>＝一括移行・同期（移行ツール）。<b>EFS</b>＝AWS内のNFS共有。混同しやすい。',
  deep:`
  <div class="dh">🏷 たとえ</div>
  <div class="nick"><b>ファイルゲートウェイ</b>＝手元の小さな受け取り棚（ローカルキャッシュ）。よく使う物は棚にあるが、本体倉庫はクラウド（S3）。棚への出し入れの作法（NFS/SMB）は今まで通り。</div>
  <div class="nick"><b>DataSync</b>＝引っ越しトラック。荷物を運び終えたら役目は終わり（その後も今まで通り使う窓口にはならない）。</div>
  <div class="dh">💡 なぜこれが正解か</div>
  「今まで通りNFS/SMBで使う＋実体はS3＋よく使う分は手元」＝ハイブリッドのファイルゲートウェイがそのもの。DataSyncは運ぶだけで日常アクセスの窓口にならない。
  <div class="dh">⚠️ つまずきやすい言葉</div>
  DataSyncは「移行・同期」、Storage Gatewayは「移行後も使い続けるハイブリッドの窓口」。<b>従来のプロトコルで使い続ける</b>が要件ならStorage Gateway。`
},
{
  id:22, cat:"セキュリティ",
  scenario:"ある企業は、Amazon EC2 上で動作するアプリケーションから、Amazon S3 バケットおよび Amazon DynamoDB にアクセスしています。現在、同社はアプリケーションの設定ファイルに IAM ユーザーのアクセスキー (長期認証情報) を書き込んで認証しています。セキュリティ監査において、同社は、長期的なアクセスキーがコードや設定ファイルに存在すること、およびその漏洩やローテーション管理の負担を問題視されました。同社は、EC2 上のアプリケーションが AWS サービスへアクセスする際の認証を、長期認証情報を持たせずに行う必要があります。",
  ask:'これらの要件を満たすソリューションはどれですか。',
  options:[
    "EC2インスタンスにIAMロールをアタッチし、アプリは自動で発行・ローテーションされる一時的な認証情報でS3・DynamoDBにアクセスする。",
    "アクセスキーをSSM Parameter StoreのSecureStringに移して暗号化保存し、アプリ起動時に取得して使うことでコードからキーを除く。",
    "アクセスキーをSecrets Managerに保存して定期的に自動ローテーションし、アプリはSecrets Manager経由でキーを取得する。",
    "アプリ用のIAMユーザーを作り直してアクセスキーを定期的に再発行し、古いキーを無効化するローテーション運用を組む。"
  ],
  answer:0,
  keypoint:'「EC2上のアプリ」「長期認証情報を持たせない」。4つとも認証情報の扱いを改善する手だが、<b>そもそも長期キーを使わない</b>のはどれか。',
  explain:'A＝EC2にIAMロールをアタッチすると、アプリは自動で発行・ローテーションされる一時認証情報（数時間で失効）でアクセスでき、長期アクセスキーをどこにも持たない。EC2上のアプリの認証の正解パターン。',
  elim:'B=Parameter Storeに移しても保存しているのは長期キーのままで「持たせない」を満たさない。C=Secrets Managerでローテーションしても長期キーを使い続けている点は同じ。D=IAMユーザー＋再発行は長期キー運用そのもので最も負担が大きい。すべて改善ではあるが、長期キーを排除するのはIAMロールのAのみ。',
  confusion:'<b>IAMロール（EC2にアタッチ）</b>＝長期キー不要・一時認証情報を自動ローテーション（EC2/Lambda等のアプリ認証の正解）。<b>アクセスキー＋Parameter Store/Secrets Manager</b>＝長期キーを安全に置くだけで「持たない」ではない。',
  deep:`
  <div class="dh">🏷 たとえ</div>
  <div class="nick"><b>アクセスキー</b>＝ずっと使える合鍵。どこに置いても「置いた時点で漏洩リスク」が残る。</div>
  <div class="nick"><b>IAMロール</b>＝その場で発行され数時間で失効する使い捨ての入館バッジ。EC2に「君はこのロールね」と付けるだけで、アプリはバッジを自動で受け取る。合鍵を持ち歩く必要がない。</div>
  <div class="dh">💡 なぜこれが正解か</div>
  要件は「長期認証情報を持たせない」。Parameter StoreやSecrets Managerは"安全に置く"だけで長期キー自体は存在する。EC2にロールを付ければキーそのものが消える。
  <div class="dh">⚠️ つまずきやすい言葉</div>
  「キーを暗号化して保管」は対策に見えるが、漏洩・ローテーションの根本は残る。<b>EC2/Lambdaのアプリ認証は、まずIAMロールで長期キーをゼロにする</b>のが原則。`
},
{
  id:23, cat:"可用性",
  scenario:"ある企業は、静的な Web サイト (HTML、CSS、JavaScript、画像) を運用しています。同社は、可用性が高く、サーバーの管理が不要で、トラフィックの増減に自動的に耐えられる構成を必要としています。さらに、同社は、世界中のユーザーに低レイテンシーで配信し、独自ドメインで HTTPS による配信を行う必要があります。同社は、サーバー (Amazon EC2) の運用やスケーリングの手間をかけたくないと考えています。",
  ask:'これらの要件を満たすソリューションはどれですか。',
  options:[
    "ALBとAuto ScalingのEC2にWebサーバーを立てて静的ファイルを配信し、複数AZに分散して可用性を確保しつつ、サーバーのパッチやスケールも自分で運用する。",
    "Amazon Lightsailの仮想サーバーにWebサーバーを構築して静的ファイルを配信し、固定料金で運用しつつ、グローバルな低遅延配信やスケールも自分で手当てする。",
    "静的ファイルをS3に置いて静的ウェブホスティングし、前段にCloudFrontを配置してグローバルに低遅延配信、ACMの証明書で独自ドメインのHTTPSを提供する。",
    "Amazon EFSに静的ファイルを保存し、複数のEC2からマウントして配信することで可用性とスケールを確保し、その前段の配信やHTTPSも自分で構成する。"
  ],
  answer:2,
  keypoint:'「静的サイト」「サーバー管理不要」「高可用・自動スケール」「グローバル低遅延」「独自ドメインHTTPS」。4つとも配信できるが、<b>サーバーレスで全条件を満たす</b>のはどれか。',
  explain:'C＝S3静的ホスティング＋CloudFront＋ACMは、サーバー管理ゼロ、S3/CloudFrontが高可用かつ自動スケール、エッジでグローバル低遅延、ACMで独自ドメインのHTTPSを実現する。静的サイト配信の定石。',
  elim:'A=EC2＋Auto Scalingは動くがサーバー管理が残り「サーバーレス・手間なし」に反する。B=Lightsailも仮想サーバーの管理が残り自動スケール・グローバル低遅延が弱い。D=EFS＋EC2もサーバー管理が残り、静的配信にはオーバースペックで低遅延グローバル配信も別途必要。要件適合でC。',
  confusion:'静的サイト配信の鉄板＝<b>S3（ホスティング）＋CloudFront（グローバル低遅延・HTTPS）＋ACM（証明書）</b>。EC2/Lightsailはサーバー管理が残るので「サーバーレス・手間なし」要件では選ばない。',
  deep:`
  <div class="dh">🏷 たとえ</div>
  <div class="nick"><b>S3静的ホスティング</b>＝ファイルを置くだけで公開できる棚。サーバーを建てる必要がない。</div>
  <div class="nick"><b>CloudFront</b>＝世界中の支店からコピーを配る配送網。遠い人にも速い＋HTTPSの窓口になる。</div>
  <div class="nick"><b>ACM</b>＝独自ドメインのHTTPS証明書を無料で発行・自動更新してくれる係。</div>
  <div class="dh">💡 なぜこれが正解か</div>
  静的ファイルにEC2は要らない。S3に置いてCloudFrontで配ればサーバー管理ゼロで高可用・自動スケール・グローバル低遅延・HTTPSが全部揃う。
  <div class="dh">⚠️ つまずきやすい言葉</div>
  「Webサイト＝EC2にWebサーバー」と反射しない。<b>中身が静的（HTML/CSS/JS/画像）</b>なら、まずS3＋CloudFrontのサーバーレス配信を考える。`
},
{
  id:24, cat:"データベース",
  scenario:"ある企業は、モバイルゲームのバックエンドを構築しています。保存するデータはプレイヤーのプロフィールやセッション状態であり、アクセスは単純なキー単位が中心で、JOIN や複雑なトランザクションは必要ありません。一方で、同社はユーザー数を予測できず、リリース後に急増する可能性も、伸び悩む可能性もあると考えています。同社は、サーバーの容量設計やパッチ管理に手をかけることを避けたいと考えています。同社は、トラフィックの増減に自動的に追従し、使用した分だけ課金される構成を必要としています。",
  ask:'これらの要件を満たすソリューションはどれですか。',
  options:[
    "Amazon DynamoDB（オンデマンドキャパシティ）を使い、キーバリュー型でリクエスト量に応じて自動スケールさせ、使った分だけ課金されるようにする。",
    "Amazon RDS for MySQLをMulti-AZで構築し、負荷の増減に合わせてインスタンスクラスを適宜スケールアップして対応し、容量設計やパッチも引き受けて運用する。",
    "Amazon Auroraのプロビジョンドクラスタを構築し、リードレプリカを複数足して読み取りスケールを確保し、書き込みや容量の管理はクラスタ側で引き受けて運用する。",
    "EC2上に自前でRedisを構築してキーバリューストアとして使い、必要に応じてインスタンスを増やしてスケールさせ、その運用やパッチも自分たちで担う。"
  ],
  answer:0,
  keypoint:'「キー単位アクセス中心・JOIN不要」「容量設計とパッチ管理をしたくない」「読めない増減に自動追従」「従量課金」。4つともデータを保存できるが、<b>サーバーレスで自動スケール＋従量課金のNoSQL</b>はどれか。',
  explain:'A＝DynamoDB（オンデマンド）はキーバリュー型でサーバー管理不要、容量を事前設計せず需要に自動追従し、使った分だけ課金。「キーアクセス中心・読めない増減・運用レス・従量」の要件すべてに合う。',
  elim:'B=RDS MySQLはスケールアップに手動操作とダウンタイムが絡み、容量設計・パッチ管理も残る。C=Auroraは高機能だがクラスタ管理が残り、単純なキーアクセスにはオーバースペック。D=EC2上Redisはサーバー管理が全部残り「運用レス」に反する。すべて保存はできるが、要件適合でA。',
  confusion:'<b>DynamoDB（オンデマンド）</b>＝キーバリュー・サーバーレス・自動スケール・従量（読めない増減＋運用レスの定番）。<b>RDS/Aurora</b>＝リレーショナル（JOIN・複雑トランザクション向け、容量/パッチ管理あり）。アクセスが単純なキー単位＋運用レスならDynamoDB。',
  deep:`
  <div class="dh">🏷 たとえ</div>
  <div class="nick"><b>DynamoDB（オンデマンド）</b>＝鍵番号を言えば即その箱を出すコインロッカー。客が増えたら勝手にロッカーが増え、使った扉の分だけ課金。管理人いらず。</div>
  <div class="nick"><b>RDS/Aurora</b>＝表と表を突き合わせる帳簿システム（JOIN）。高機能だが管理が要る。単純な鍵引きには大げさ。</div>
  <div class="dh">💡 なぜこれが正解か</div>
  「キーで引くだけ・JOIN不要・増減読めない・運用したくない・従量」＝NoSQLのDynamoDBオンデマンドが全部に刺さる。RDBは機能過剰＋運用が残り、自前Redisは運用そのものが残る。
  <div class="dh">⚠️ つまずきやすい言葉</div>
  「DB＝とりあえずRDS」と反射しない。<b>アクセスが単純なキー単位＋容量設計したくない＋従量</b>が揃ったらDynamoDBを疑う。JOINや複雑な集計が要るならRDS/Aurora。`
},
{
  id:25, cat:"コスト最適化",
  scenario:"ある企業は、本番環境で 1 年以上にわたって同じ Amazon EC2 インスタンスを常時稼働させており、今後も少なくとも 1 年は同じ規模で使用し続けることが確実に分かっています。同社が途中でインスタンスタイプを変更する可能性は低く、安定して稼働し続ける見込みです。現在、同社はすべてオンデマンド料金で支払っています。同社は、確実に使用し続ける分のコストを最大限に削減する必要があります。",
  ask:'これらの要件を満たすソリューションはどれですか。',
  options:[
    "1年または3年のコンピュートSavings Plansを購入し、確実に使う使用量分を割引料金にコミットして、常時稼働のコストを下げる。",
    "EC2 Spotインスタンスに切り替えて大幅な割引を受け、容量回収で中断された場合は別のインスタンスで起動し直して常時稼働を保つ。",
    "Auto Scalingで需要に応じて台数を自動で増減させ、アイドル時間を減らすことで、オンデマンド単価のままコストを抑える。",
    "オンデマンドのまま運用し、Compute Optimizerの推奨に従ってインスタンスタイプを適正化することで、単価はそのままにコストを下げる。"
  ],
  answer:0,
  keypoint:'「1年以上確実に常時稼働」「途中変更の可能性低い」「使い続ける分を最大限安く」。4つともコスト削減の正しい手だが、<b>長期コミットで常時稼働を最安</b>にするのはどれか。',
  explain:'A＝Savings Plans（またはRI）は1年/3年のコミットで常時稼働分を大幅割引にする。使い続けることが確実なワークロードのコスト最適化の王道。',
  elim:'B=Spotは安いが中断されるため「本番の常時稼働」には不向き（停止できない）。C=Auto Scalingは需要が変動する場合に効くが、本ケースは「常時同規模で稼働」なのでスケールの余地が小さい。D=タイプ適正化は有効だがオンデマンド単価のままで、長期コミットの割引には及ばない。確実な常時稼働を最安にするのはコミット型のA。',
  confusion:'<b>Savings Plans/RI</b>＝1年/3年コミットで常時稼働を最大割引（使い続けるのが確実な時）。<b>Spot</b>＝中断OKなバッチ向け（本番常時稼働には不可）。<b>Auto Scaling</b>＝需要変動がある時。「確実に常時稼働」ならコミット型。',
  deep:`
  <div class="dh">🏷 たとえ</div>
  <div class="nick"><b>オンデマンド</b>＝その都度払いの正規料金。いつでもやめられるが割高。</div>
  <div class="nick"><b>Savings Plans / RI</b>＝1年/3年の定期券。「確実に毎日乗る」なら定期が一番安い。</div>
  <div class="nick"><b>Spot</b>＝空席の格安券。安いが満席なら降ろされる（本番の常時稼働には使えない）。</div>
  <div class="dh">💡 なぜこれが正解か</div>
  「1年以上・確実に・常時・同規模」＝定期券（コミット）が最安。中断されるSpotは本番に不可、需要変動前提のAuto Scalingは効きどころが違う。
  <div class="dh">⚠️ つまずきやすい言葉</div>
  「確実に使い続ける／常時稼働／長期」＝Savings Plans/RIの合図。「中断されてもよいバッチ」ならSpot、と問題文のワークロード特性で切り分ける。`
},
{
  id:26, cat:"セキュリティ",
  scenario:"ある企業は、複数の AWS アカウントを使い始めました。同社は、今後アカウントが増えても、組織全体で、特定の高コストなリージョンや禁止されたサービスは誰も使用できないようにすること、およびルートユーザーの特定の操作を禁止することといったガードレールを、一括で適用したいと考えています。各アカウントの IAM で個別にポリシーを設定して回る運用は、アカウントの増加に伴って破綻します。同社は、組織レベルで、利用可能なアクションの上限を一元的に強制する必要があります。",
  ask:'これらの要件を満たすソリューションはどれですか。',
  options:[
    "AWS Organizationsでアカウントを管理し、サービスコントロールポリシー（SCP）で組織やOU単位に利用可能なアクションの上限を一元的に強制する。",
    "各アカウントでIAMポリシーを統一的に作成し、禁止したいアクションをDenyするポリシーをすべてのユーザーやロールに付与して回り、新規作成時にも漏れなく設定し続ける。",
    "AWS Configのルールで禁止サービスの使用を検知し、違反を見つけたらEventBridge経由で担当者へ通知して、事後に是正を促す運用にする。",
    "IAM Identity Center（SSO）で各アカウントへのアクセスを集中管理し、ユーザーに割り当てる許可セットで操作範囲を制御して、組織全体の利用を制限する。"
  ],
  answer:0,
  keypoint:'「複数アカウント」「組織全体に上限を一括強制」「個別IAM設定は破綻」。4つとも統制に関わるが、<b>組織/OU単位でアクションの上限を強制</b>するのはどれか。',
  explain:'A＝OrganizationsのSCPは組織・OU単位で「これ以上の権限は誰も持てない」という上限（ガードレール）を一元的に強制する。アカウントが増えてもOUに入れれば自動適用される。',
  elim:'B=各アカウントでIAMを個別設定するのは「運用が破綻する」と書かれた当の問題。C=Configは違反の検知・通知であって強制的なブロックではない（事後）。D=Identity Centerはアクセスの割り当て管理で、組織全体の上限を強制する仕組みではない。組織レベルの上限強制はSCPのA。',
  confusion:'<b>SCP（Organizations）</b>＝組織/OU単位で権限の上限を強制（ガードレール・予防的）。<b>IAMポリシー</b>＝アカウント内の個別許可。<b>Config</b>＝違反の検知（事後）。<b>Identity Center</b>＝アクセス割り当て。組織横断の一括強制＝SCP。',
  terms:[
    {t:"SCP（サービスコントロールポリシー）", d:"Organizationsで組織・OU単位に適用する権限の上限。SCPで禁止したアクションは、アカウント内でIAMが許可しても実行できない（ガードレール）。"},
    {t:"OU（組織単位）", d:"複数アカウントをまとめるフォルダのような単位。OUにSCPを当てると配下のアカウント全部に効く。"}
  ],
  deep:`
  <div class="dh">🏷 たとえ</div>
  <div class="nick"><b>IAMポリシー</b>＝各部屋の中で「ここまでやっていい」を決める鍵。部屋が増えるたびに全部屋へ配って回るのは無理。</div>
  <div class="nick"><b>SCP</b>＝建物全体の「立入禁止区域」の張り紙。どの部屋の住人（管理者すら）も超えられない上限。新しい部屋もこの建物に属せば自動で従う。</div>
  <div class="dh">💡 なぜこれが正解か</div>
  「組織全体に・一括で・超えられない上限を強制」＝SCP。IAMの個別配布は破綻、Configは検知止まり、Identity Centerはアクセス割り当てで上限強制ではない。
  <div class="dh">⚠️ つまずきやすい言葉</div>
  SCPは「許可を与える」ものではなく「上限を決める（これ以上はダメ）」もの。実際の許可はアカウント内のIAMで出す。<b>組織横断のガードレール＝SCP</b>。`
},
{
  id:27, cat:"高性能",
  scenario:"ある企業は、ニュースアプリのバックエンドを Amazon API Gateway、AWS Lambda、Amazon RDS (MySQL) で運用しています。アクセスが急増すると Lambda の同時実行数が一気に増加し、各 Lambda 関数がそれぞれ新しいデータベース接続を確立するため、RDS の最大接続数を超えてエラーが多発しました。同社は、Lambda の同時実行に対してデータベース接続を効率的に再利用し、接続数の枯渇を防いで RDS の負荷を安定させる必要があります。",
  ask:'これらの要件を満たすソリューションはどれですか。',
  options:[
    "RDSのインスタンスクラスをより上位のタイプへスケールアップして許容できる最大接続数を増やし、Lambdaの同時実行が増えても枯渇しないようにする。",
    "RDS Proxyを導入してLambdaとRDSの間でコネクションをプールし、多数の同時実行が少数のDB接続を効率的に共有するようにする。",
    "RDSリードレプリカを複数追加して接続先を分散し、1台あたりの接続数の負荷を下げることで、コネクションの枯渇を緩和する。",
    "ElastiCacheをRDSの前段に置き、読み取りをキャッシュで返すことでRDSへの接続そのものを減らし、コネクションの枯渇を避ける。"
  ],
  answer:1,
  keypoint:'「Lambdaの同時実行が急増」「各Lambdaが新規コネクションを張ってRDS接続数が枯渇」。4つとも性能/負荷の手だが、<b>コネクションをプールして使い回す</b>のはどれか。',
  explain:'B＝RDS ProxyはLambdaとRDSの間でコネクションをプールし、多数の同時実行に対して少数のDB接続を共有・再利用する。Lambda×RDSのコネクション枯渇問題の専用解。',
  elim:'A=スケールアップで最大接続数は増えるが、Lambdaがさらに増えれば再び枯渇する（根本解決でない）。C=リードレプリカは読み取り分散には効くが書き込みの接続枯渇やコネクション管理そのものは解決しない。D=ElastiCacheは読み取りを減らせるが、書き込みやキャッシュミス時の接続枯渇は残る。コネクション枯渇の直接解はRDS ProxyのB。',
  confusion:'<b>RDS Proxy</b>＝Lambda等の大量同時実行とRDSの間でコネクションをプール・再利用（接続枯渇の専用解）。<b>スケールアップ</b>＝接続上限を増やすだけ（また枯渇しうる）。<b>リードレプリカ/ElastiCache</b>＝読み取り負荷側の対策。',
  deep:`
  <div class="dh">🏷 たとえ</div>
  <div class="nick"><b>RDS Proxy</b>＝受付の取次係。客（Lambda）が大勢来ても、奥の窓口（DB接続）は限られた数を順に使い回す。客が増えても窓口がパンクしない。</div>
  <div class="nick"><b>スケールアップ</b>＝窓口の数を増やす。一時しのぎにはなるが、客がもっと増えればまた足りなくなる。</div>
  <div class="dh">💡 なぜこれが正解か</div>
  Lambdaは同時実行ごとに接続を張るので、急増すると接続数が即枯渇する。これを根本から解くのは「接続を使い回す」RDS Proxy。スケールアップは上限を上げるだけで再発しうる。
  <div class="dh">⚠️ つまずきやすい言葉</div>
  「Lambda＋RDSで接続数が枯渇」はRDS Proxyを選ばせる典型キーワード。読み取り遅延ならElastiCache/レプリカ、<b>接続枯渇ならRDS Proxy</b>と症状で切り分ける。`
},
{
  id:28, cat:"可用性",
  scenario:"ある企業は、本番環境の Web アプリケーションをドメイン名で公開しています。同社は東京リージョンをメインで運用しており、万一そのリージョン全体が障害となった場合に、自動的にスタンバイ環境 (別リージョン) へ切り替えてサービスを継続する必要があります。利用者は同じドメイン名でアクセスし続けられる必要があります。同社は、リージョン障害を検知して、ドメインの向き先を自動的にフェイルオーバーさせる必要があります。",
  ask:'これらの要件を満たすソリューションはどれですか。',
  options:[
    "Application Load Balancerのヘルスチェックで異常を検知し、同じALBに登録した別リージョンのターゲットへ自動的にリクエストを転送して切り替える。",
    "Auto Scalingを複数リージョンにまたがって構成し、東京リージョンが落ちたら別リージョンでインスタンスを自動起動して、サービスを継続させる。",
    "Amazon Route 53のフェイルオーバールーティングとヘルスチェックを設定し、メインの異常を検知したら同じドメインをスタンバイリージョンのエンドポイントへ自動で切り替える。",
    "CloudFrontのオリジンフェイルオーバーを設定し、プライマリオリジンが失敗したらセカンダリオリジンへ自動で切り替えて、配信層でリージョン障害に備える。"
  ],
  answer:2,
  keypoint:'「リージョン全体の障害」「同じドメイン名で継続」「自動フェイルオーバー」。4つとも可用性の手だが、<b>DNSレベルでリージョン障害を検知し向き先を切り替える</b>のはどれか。',
  explain:'C＝Route 53のフェイルオーバールーティング＋ヘルスチェックは、メインのエンドポイント異常を検知し、同じドメイン名の解決先をスタンバイリージョンへ自動で切り替える。リージョン跨ぎのDR切り替えの定石。',
  elim:'A=ALBはリージョン内のロードバランサーで、リージョン全体障害時の別リージョンへの切り替えはできない。B=Auto Scalingは台数調整でDNSの向き先切り替えはしない。D=CloudFrontのオリジンフェイルオーバーはオリジン単位の切り替えで、HTTP配信前提＋リージョン障害時のDNSフェイルオーバーの一般解ではない。リージョン跨ぎのドメイン切り替えはRoute 53のC。',
  confusion:'<b>Route 53フェイルオーバー</b>＝DNSレベルでリージョン障害を検知し同じドメインの向き先を切り替え（リージョン跨ぎDRの定番）。<b>ALB</b>＝リージョン内の分散。<b>CloudFrontオリジンフェイルオーバー</b>＝オリジン単位（用途が違う）。',
  deep:`
  <div class="dh">🏷 たとえ</div>
  <div class="nick"><b>Route 53</b>＝電話の交換手（DNS）。「いつもの番号（ドメイン）」にかけると東京につなぐが、東京が不通だと自動で大阪につなぎ直す。客は同じ番号にかけ続けるだけ。</div>
  <div class="nick"><b>ALB</b>＝建物の中の案内係。その建物（リージョン）が丸ごと停電したら案内係も止まる（別の建物へは回せない）。</div>
  <div class="dh">💡 なぜこれが正解か</div>
  「リージョンごと落ちる」「同じドメインで継続」＝建物をまたいで向き先を変える交換手（Route 53）の仕事。ALBは建物内、Auto Scalingは台数、CloudFrontはオリジン単位で、リージョン跨ぎのDNS切り替えはできない。
  <div class="dh">⚠️ つまずきやすい言葉</div>
  「リージョン全体障害＋同じドメインで自動切り替え」はRoute 53フェイルオーバーの合図。リージョン内の振り分けはALB、と<b>跨ぐか跨がないか</b>で切り分ける。`
},
{
  id:29, cat:"サーバーレス",
  scenario:"ある企業は、Amazon S3 バケットにアップロードされる画像について、アップロードのたびに自動でサムネイルを生成する必要があります。アップロードは不定期で、1 日に数件のこともあれば数千件に達することもあります。処理は 1 件あたり数秒で完結する短い処理です。同社は、サーバーを常時起動しておくことを無駄と考えており、アップロードを検知して必要なときだけ処理を実行し、使用した分だけ課金される構成を必要としています。",
  ask:'これらの要件を満たすソリューションはどれですか。',
  options:[
    "S3のイベント通知でLambdaをトリガーし、アップロードのたびにサムネイル生成を実行して、実行時間に応じた従量課金で処理する。",
    "EC2を常時起動してS3を定期的にポーリングし、新しい画像を見つけ次第サムネイルを生成する方式にして、アイドル時間も含めて常時課金で運用する。",
    "ECS（Fargate）でサービスを常時稼働させ、SQS経由でアップロード通知を受けてサムネイルを生成し、処理がない時間帯もタスクを動かし続けて待ち受ける。",
    "AWS Batchでサムネイル生成ジョブをスケジューリングし、EC2のコンピューティング環境を立ち上げて順次バッチ処理する方式にする。"
  ],
  answer:0,
  keypoint:'「S3アップロードを起点」「不定期で量が読めない」「1件数秒の短い処理」「常時起動は無駄・従量」。4つとも処理できるが、<b>イベント駆動・サーバーレス・短時間・従量</b>に最も合うのはどれか。',
  explain:'A＝S3イベント→Lambdaは、アップロードのたびに自動起動し、数秒の短い処理を実行時間ぶんだけ課金する。常時起動が不要で量の増減にも自動追従する。サムネイル生成の典型パターン。',
  elim:'B=EC2常時起動＋ポーリングは常時課金＋イベント駆動でない（無駄）。C=Fargate常時稼働も処理がない時間も課金が発生し「必要なときだけ」に反する。D=AWS Batchは長時間/大規模バッチ向けで、1件数秒のイベント処理にはオーバースペック。要件適合でA。',
  confusion:'<b>S3イベント→Lambda</b>＝アップロード起点の短時間処理を従量・サーバーレスで（典型パターン）。<b>EC2/Fargate常時稼働</b>＝処理がない時も課金。<b>AWS Batch</b>＝長時間・大規模バッチ向け。短いイベント処理はLambda。',
  deep:`
  <div class="dh">🏷 たとえ</div>
  <div class="nick"><b>Lambda</b>＝呼ばれたときだけ来る出張スタッフ。S3に画像が届いた瞬間（イベント）に来て、数秒で仕事して帰る。働いた分だけ報酬（従量）。</div>
  <div class="nick"><b>EC2/Fargate常時稼働</b>＝仕事がなくても出勤している社員。待機時間も給料が出る（無駄）。</div>
  <div class="dh">💡 なぜこれが正解か</div>
  「アップロードのたび」「不定期」「数秒」「常時起動したくない」＝イベント駆動のLambdaがそのもの。常時稼働系は待機コストが無駄、Batchは重い処理向けで大げさ。
  <div class="dh">⚠️ つまずきやすい言葉</div>
  「○○されたら、そのたびに、短い処理」はLambdaを選ばせる合図。長時間・大量並列のバッチならBatch/Fargate、と<b>処理時間と起動契機</b>で切り分ける。`
},
{
  id:30, cat:"ストレージ",
  scenario:"ある法律事務所が、訴訟記録や契約書などのデータレコードを最低 7 年間保持する必要があります。このデータは、保存後にアクセスされることはほとんどありません。まれに監査や訴訟対応で参照が必要になった場合でも、データは翌営業日までに利用できれば十分です。ソリューションアーキテクトは、これらのファイルを保存するための Amazon S3 バケットを作成しました。ファイルの取り出しに 12 時間程度かかることは許容されますが、保管コストは可能な限り低く抑える必要があります。",
  ask:'これらの要件を満たす、最もコスト効率に優れたソリューションはどれですか。',
  options:[
    "S3 Standard-IAに保管し、アクセス頻度が低いデータ向けの低い保管単価でコストを抑えつつ、必要なときはすぐ取り出せる状態を保って運用する。",
    "S3 Glacier Deep Archiveに保管し、取り出しに時間がかかることを許容する代わりに、最も安い保管単価で7年保管する。",
    "S3 Glacier Instant Retrievalに保管し、アーカイブ向けの低い保管単価とミリ秒の即時取り出しを両立させて、いつでもすぐ参照できるようにする。",
    "S3 One Zone-IAに保管し、データを単一AZに置くことで標準のIAより安い単価に抑え、即時取り出しもできる状態で保管する。"
  ],
  answer:1,
  keypoint:'「7年の長期保管」「ほぼアクセスしない」「翌日取り出しでOK（即時不要）」「最安」。4つとも保管クラスだが、<b>取り出しの遅さを許容して保管単価を最安</b>にするのはどれか。',
  explain:'B＝Glacier Deep ArchiveはS3の中で最も保管単価が安く、取り出しに数時間〜半日かかるが「翌日までに取り出せればよい」運用に合致する。長期アーカイブの最安解。',
  elim:'A=Standard-IAはDeep Archiveより保管単価が高い（即時取り出し向けで今回は過剰）。C=Glacier Instant Retrievalは即時取り出しできるぶん保管単価がDeep Archiveより高く、即時不要の本ケースでは割高。D=One Zone-IAは安いが即時取り出し前提のクラスで、Deep Archiveほど保管単価は下がらない。取り出しの遅さを許容できる本ケースの最安はB。',
  confusion:'アーカイブ系の取り出し速度と単価：<b>Glacier Instant</b>＝即時・やや高め／<b>Glacier Flexible</b>＝数分〜数時間／<b>Glacier Deep Archive</b>＝数時間〜半日・<b>最安</b>。「即時不要・とにかく安く」ならDeep Archive。',
  terms:[
    {t:"Glacier Deep Archive", d:"S3で最も保管単価が安い長期アーカイブ階層。取り出しに数時間〜半日かかる。法令保管など滅多に出さないデータ向け。"},
    {t:"取り出し時間と単価のトレードオフ", d:"即時に出せるクラスほど保管単価が高い。即時取り出しが要らないほど安いクラスを選べる。"}
  ],
  deep:`
  <div class="dh">🏷 たとえ</div>
  <div class="nick"><b>Standard-IA</b>＝たまに出す物を入れる手前の物置（出すのは速いが家賃は中くらい）。</div>
  <div class="nick"><b>Glacier Deep Archive</b>＝郊外の超安い倉庫の奥。出すのに半日かかるが家賃は最安。7年寝かせる書類向け。</div>
  <div class="dh">💡 なぜこれが正解か</div>
  「滅多に出さない＋翌日でOK＋最安」＝取り出しの遅さを払う代わりに家賃を最安にするDeep Archive。即時取り出せるクラスはそのぶん保管料が高く、即時不要の今回は払い損。
  <div class="dh">⚠️ つまずきやすい言葉</div>
  「即時に取り出したい」ならGlacier Instant、「数時間〜翌日でいい・とにかく安く」ならDeep Archive。<b>取り出しの速さの要否</b>で階層を選ぶ。`
},
{
  id:31, cat:"AI/ML",
  scenario:"ある企業は、写真共有 SNS を運営しています。同社は、ユーザーが投稿する大量の画像について、不適切なもの (暴力・露出など) が含まれていないかを自動で判定し、さらに写真に写っている物体やシーン (犬、ビーチ、料理など) のタグを自動的に付与する必要があります。同社の社内には機械学習の専門家がおらず、自前でモデルを訓練する時間もありません。同社は、Amazon S3 にアップロードされた画像を起点として、できるだけ早く実装する必要があります。",
  ask:'これらの要件を満たすソリューションはどれですか。',
  options:[
    "S3アップロードをトリガーにLambdaからAmazon Rekognitionを呼び、不適切コンテンツ検出とラベル（物体・シーン）検出の結果を受け取って保存する。",
    "S3アップロードをトリガーにLambdaからAmazon SageMakerで自社の画像分類モデルを訓練・デプロイし、その推論結果を保存して、不適切判定と物体検出に使う。",
    "S3アップロードをトリガーにLambdaからAmazon Textractを呼び、画像内の文字情報をOCRで抽出して不適切な表現が含まれないか判定し、その結果を保存する。",
    "S3アップロードをトリガーにLambdaからAmazon Comprehendを呼び、画像に付随する説明文のテキスト内容を分析して不適切かどうか判定し、その結果を保存する。"
  ],
  answer:0,
  keypoint:'土台は全選択肢同じ（S3→Lambda→AIサービス→保存）。違いは<b>渡す先のAIサービス</b>だけ。「画像の中身を見て不適切判定＋物体タグ」を、専門家なしの既製サービスでやるのはどれか。',
  explain:'A＝Rekognitionは画像の中身を解析し、不適切コンテンツ検出と物体・シーンのラベル検出を既製APIで提供する。モデル訓練不要で、まさにこの用途のためのマネージドAIサービス。',
  elim:'B=SageMakerは自前モデルの訓練・デプロイが必要で「専門家なし・早く」に反する（AI/MLと聞いて反射で選ぶと逆）。C=Textractは画像内の文字（OCR）抽出で、物体やシーン・不適切画像の判定はしない。D=Comprehendはテキスト分析で画像の中身を見ない。画像の中身を見るのはRekognition。',
  confusion:'画像/テキストAIの守備範囲：<b>Rekognition</b>＝画像の中身（物体・シーン・不適切・顔）。<b>Textract</b>＝画像内の文字をOCR。<b>Comprehend</b>＝テキストの意味。<b>SageMaker</b>＝自前モデル訓練。画像の中身を見るならRekognition。',
  deep:`
  <div class="dh">🏷 あだ名</div>
  <div class="nick"><b>Rekognition</b>＝画像を見る目。「これは犬」「露出あり」と中身を見て判定する。学習済みなので専門家いらず。</div>
  <div class="nick"><b>Textract</b>＝書類を読み取るスキャナー（文字専門）。物体は見ない。</div>
  <div class="nick"><b>SageMaker</b>＝モデルを一から作る工房。データと専門家がいる時の選択肢。</div>
  <div class="dh">💡 なぜこれが正解か</div>
  「専門家なし」「画像の中身を判定」＝学習済みの既製サービスRekognition。SageMakerは工房なので「専門家なし・早く」と真逆。
  <div class="dh">⚠️ つまずきやすい言葉</div>
  AI/MLと聞くと反射でSageMakerを選びがちだが逆。<b>ML専門家いない・データない・早く作りたいなら、まずマネージドAIサービス</b>（Rekognition等）を疑う。SageMakerは独自モデルがどうしても要る時だけ。`
},
{
  id:32, cat:"AI/ML",
  scenario:"ある企業は、経理代行業を営んでおり、顧客から送られてくる請求書や申込書を、スキャンした PDF・画像で大量に受け取っています。同社は、これらから金額・日付・項目といった文字情報だけでなく、表組みやフォーム (『氏名：山田』のようなキーと値のペア) を構造化して自動的に抽出し、後工程のシステムへ渡す必要があります。同社の社内には機械学習の専門家がいません。同社は、Amazon S3 にアップロードされた帳票を起点として処理する必要があります。",
  ask:'これらの要件を満たすソリューションはどれですか。',
  options:[
    "S3アップロードをトリガーにLambdaからAmazon Rekognitionを呼び、画像内の物体やシーンを検出して帳票の内容を把握し保存する。",
    "S3アップロードをトリガーにLambdaからAmazon Textractを呼び、文字・表・フォーム（キーと値）を構造化抽出して後工程へ渡す。",
    "S3アップロードをトリガーにLambdaからAmazon Comprehendを呼び、帳票の文章を感情分析・キーフレーズ抽出して保存する。",
    "S3アップロードをトリガーにLambdaからAmazon SageMakerで自社のOCRモデルを訓練・デプロイして抽出する。"
  ],
  answer:1,
  keypoint:'土台は全選択肢同じ（S3→Lambda→AIサービス）。違いは<b>渡す先</b>だけ。「帳票の文字＋表＋フォーム（キー値）を構造化抽出」を専門家なしでやるのはどれか。',
  explain:'B＝Textractは単なるOCRを超えて、表組みやフォームのキーと値のペアまで構造化して抽出する。請求書・申込書の自動処理の専用サービスで、専門家なしで使える。',
  elim:'A=Rekognitionは物体・シーン検出で、帳票の文字や表の構造化抽出はしない（画像つながりで混同させる罠）。C=Comprehendはテキストの意味分析で、帳票からの抽出そのものはしない。D=SageMakerで自前OCRは専門家・データ・時間が必要で「専門家なし」に反する。帳票の構造化抽出はTextract。',
  confusion:'<b>Textract</b>＝帳票の文字＋表＋フォーム（キー値）を構造化抽出（OCRの上位）。<b>Rekognition</b>＝画像の物体・シーン（文字や表は対象外）。画像つながりで混同しやすいので「文字・表・フォームの抽出」ならTextract。',
  deep:`
  <div class="dh">🏷 あだ名</div>
  <div class="nick"><b>Textract</b>＝書類を読み取るスキャナー。ただの文字起こしでなく「氏名：山田」のキーと値、表のセルまで構造で取り出す。</div>
  <div class="nick"><b>Rekognition</b>＝画像を見る目（物体・シーン）。書類の中の文字や表の構造は専門外。</div>
  <div class="dh">💡 なぜこれが正解か</div>
  「請求書・申込書から文字＋表＋フォームを構造化」＝帳票特化のTextract。Rekognitionは「画像」つながりで紛らわしいが、見るのは物体であって帳票の構造ではない。
  <div class="dh">⚠️ つまずきやすい言葉</div>
  画像が出てくると反射でRekognitionを選びがち。<b>中身が「帳票・文書の文字や表」ならTextract</b>、「写真に何が写っているか」ならRekognition、と画像の種類で切り分ける。`
},
{
  id:33, cat:"コスト最適化",
  scenario:"ある企業は、データ分析を行っており、大規模なバッチ処理 (機械学習の前処理やログ集計) を多数の Amazon EC2 インスタンスで並列実行しています。これらの処理は途中で中断されても再実行すれば問題がなく、納期にも余裕があります (多少時間がかかっても許容されます)。多数のインスタンスをまとめて使用するため、コンピューティングコストが大きくなっています。同社は、中断耐性のあるこの大規模並列バッチの EC2 コストを最大限に削減する必要があります。",
  ask:'これらの要件を満たすソリューションはどれですか。',
  options:[
    "1年のSavings Plansを購入してバッチ用EC2の使用量を長期コミットし、その割引料金で中断耐性のある大規模並列バッチを実行する。",
    "オンデマンドインスタンスでバッチを実行し、Compute Optimizerの推奨に従ってインスタンスタイプを適正化することで、単価はそのままにコストを下げる。",
    "Spotインスタンス（Spot Fleet）でバッチを実行し、中断されたら別のプール/インスタンスで再開する設計にして、最大級の割引を受ける。",
    "Auto Scalingでバッチの負荷に応じて台数を自動で増減させ、アイドル時間を減らすことで、オンデマンド単価のままコストを抑える。"
  ],
  answer:2,
  keypoint:'「中断されても再実行でOK」「納期に余裕」「大規模並列バッチ」「コスト最大限削減」。4つとも正しいコスト手段だが、<b>中断耐性を最大の割引に変える</b>のはどれか。',
  explain:'C＝Spot（Spot Fleet）は中断耐性のあるワークロードに対しオンデマンドより大幅に安い。中断時に別プールで再開する設計にすれば、大規模並列バッチのコストを最大限下げられる。',
  elim:'A=Savings Plansは「常時稼働を確実に使う」場合の割引で、断続的なバッチでは使い切れずSpotほど安くならない。B=オンデマンド＋適正化は割引幅が小さい。D=Auto Scalingはアイドル削減には効くが単価はオンデマンドのままでSpotに及ばない。中断耐性を最安に変えるのはSpotのC。',
  confusion:'<b>Spot</b>＝中断OKなバッチを最大割引で（中断耐性×コスト最小の組み合わせ）。<b>Savings Plans</b>＝常時稼働を確実に使う時。<b>オンデマンド</b>＝中断が許されない短期。中断耐性＋納期余裕＝Spot。',
  deep:`
  <div class="dh">🏷 たとえ</div>
  <div class="nick"><b>Spot</b>＝キャンセル空席の激安チケット。満席になったら降ろされる（中断）が、やり直せる用事（再実行OKのバッチ）なら一番得。</div>
  <div class="nick"><b>Savings Plans</b>＝定期券。毎日確実に乗る常時稼働向け。たまにしか動かないバッチでは元が取れない。</div>
  <div class="dh">💡 なぜこれが正解か</div>
  「中断OK」「納期に余裕」と書いてある＝Spotを使える最大の合図。中断耐性をそのまま最大割引に変換できる。常時稼働前提のSavings Plansはバッチでは使い切れない。
  <div class="dh">⚠️ つまずきやすい言葉</div>
  「中断されても再実行すればよい」＝Spot。「中断できない常時稼働を確実に長期」＝Savings Plans/RI。<b>ワークロードが中断を許すか</b>で割引手段が決まる。`
},
{
  id:34, cat:"セキュリティ",
  scenario:"ある企業は、Application Load Balancer (ALB) の背後の Amazon EC2 でアプリケーションを運用しており、このアプリケーションはインターネットに公開されています。最近、同社は、SQL インジェクションやクロスサイトスクリプティング (XSS) を狙うリクエストや、特定の悪意ある IP レンジからの大量アクセスを観測しています。同社は、アプリケーションのコードを大きく改修することなく、これらのアプリケーション層 (HTTP リクエストの中身) への攻撃を Web アプリケーションの手前でブロックする必要があります。",
  ask:'これらの要件を満たすソリューションはどれですか。',
  options:[
    "セキュリティグループとネットワークACLで悪意あるIPレンジを拒否し、許可した送信元だけがALBに到達できるようにして、L3/L4の制御でアプリ層攻撃を防ぐ。",
    "AWS Shield Advancedを有効化してネットワーク/トランスポート層のDDoS攻撃から保護し、大量アクセスによる過負荷を緩和してアプリを守る。",
    "AWS WAFをALBに関連付け、SQLインジェクションやXSSのマネージドルール、レートベースルールでアプリ層への攻撃リクエストをブロックする。",
    "Amazon GuardDutyを有効化して不審な通信やAPI呼び出しを検知し、その検出結果をもとに担当者が事後に対応することでアプリ層攻撃に備える。"
  ],
  answer:2,
  keypoint:'「SQLi/XSS＝HTTPの中身への攻撃」「Webの手前でブロック」「コード改修最小」。4つともセキュリティの正しい手だが、<b>アプリ層（L7）のリクエスト内容を検査してブロック</b>するのはどれか。',
  explain:'C＝WAFはALBに関連付けてHTTPリクエストの中身を検査し、SQLi/XSSのマネージドルールやレートベースルールで攻撃を手前でブロックする。アプリ層攻撃の防御の専用サービス。',
  elim:'A=SG/NACLはIP・ポート（L3/L4）の制御で、リクエストの中身（SQLi/XSS）は見られない。B=Shieldはネットワーク/トランスポート層のDDoS対策で、アプリ層の攻撃パターン検査はしない。D=GuardDutyは脅威の検知であってリクエストのブロックはしない。アプリ層の攻撃をブロックするのはWAF。',
  confusion:'防御層の違い：<b>WAF</b>＝L7（HTTPの中身：SQLi/XSS）をブロック。<b>SG/NACL</b>＝L3/L4（IP・ポート）。<b>Shield</b>＝DDoS（L3/L4の大量攻撃）。<b>GuardDuty</b>＝検知（ブロックしない）。リクエストの中身への攻撃＝WAF。',
  deep:`
  <div class="dh">🏷 たとえ</div>
  <div class="nick"><b>WAF</b>＝持ち物検査をする入口の警備員。「この申込用紙に不正な文字列（SQLi/XSS）が書いてある」と中身を見て弾く。</div>
  <div class="nick"><b>SG/NACL</b>＝建物の門。「どの住所（IP）・どの扉（ポート）から来たか」は見るが、持ち物の中身は見ない。</div>
  <div class="nick"><b>Shield</b>＝大群が押し寄せる（DDoS）のをさばく係。中身の精査はしない。</div>
  <div class="dh">💡 なぜこれが正解か</div>
  SQLi/XSSは「リクエストの中身」への攻撃。中身を見て弾けるのはL7のWAFだけ。門（SG/NACL）は中身を見られず、Shieldは物量、GuardDutyは見張るだけ。
  <div class="dh">⚠️ つまずきやすい言葉</div>
  「IPで拒否」はSG/NACLでもできるが、SQLi/XSSの<b>中身</b>は弾けない。攻撃が「HTTPリクエストの内容」ならWAF、と層で切り分ける。`
},
{
  id:35, cat:"高性能",
  scenario:"ある企業は、IoT プラットフォームを運用しており、全国の数十万台のセンサーから 1 秒間に数十万件のデータを受信しています。同社は、このストリームデータをリアルタイムに取り込み、複数の処理 (リアルタイム集計と Amazon S3 への保存) に流す必要があります。受信のピークは時間帯によって大きく変動し、データの取りこぼしは許容されません。同社は、高スループットなストリームの取り込みを、運用しやすい形で実現する必要があります。",
  ask:'これらの要件を満たすソリューションはどれですか。',
  options:[
    "Amazon SQS標準キューに全データを投入し、複数のコンシューマでポーリングして並列処理する。",
    "Application Load Balancerの背後のEC2群でデータを受信し、Auto Scalingでピークに合わせて受信サーバーを増減する。",
    "RDSに直接書き込み、Multi-AZとリードレプリカで書き込みと読み取りの負荷をさばく。",
    "Amazon Kinesis Data Streamsでストリームを取り込み、複数のコンシューマ（リアルタイム集計とS3保存）がそれぞれ独立に処理する。"
  ],
  answer:3,
  keypoint:'「毎秒数十万件」「リアルタイムストリーム」「複数処理に流す」「取りこぼし不可」。4つともデータを受けられるが、<b>高スループットなストリーム取り込みに特化</b>するのはどれか。',
  explain:'D＝Kinesis Data Streamsは大量のストリームデータをシャードで高スループットに取り込み、複数のコンシューマが同じストリームを独立に処理できる。IoTのリアルタイム取り込みの定番。',
  elim:'A=SQS標準はメッセージキューであり、毎秒数十万件のストリーム取り込み＋複数の独立処理（リプレイ的な並行消費）には向かない。B=EC2受信＋Auto Scalingは受信基盤を自前運用することになり、ストリーム特化のKinesisに比べ運用が重い。C=RDSへ直接毎秒数十万件の書き込みは現実的でなく破綻する。高スループットストリームはKinesis。',
  confusion:'<b>Kinesis Data Streams</b>＝高スループットなストリーム取り込み＋複数コンシューマの独立処理（IoT/ログ）。<b>SQS</b>＝1対1のメッセージキュー（ストリーム取り込みではない）。大量ストリーム＝Kinesis。',
  deep:`
  <div class="dh">🏷 たとえ</div>
  <div class="nick"><b>Kinesis</b>＝大量の水が流れ続ける川（ストリーム）。何人もが同じ川から同時に水をくめる（複数の独立処理）。流量が多くても受け止められる。</div>
  <div class="nick"><b>SQS</b>＝受付の伝票スタンド。1枚ずつ処理する用途で、毎秒数十万件の濁流を流す川ではない。</div>
  <div class="dh">💡 なぜこれが正解か</div>
  「毎秒数十万件・リアルタイム・複数処理に流す」＝ストリーム取り込み特化のKinesis。RDS直書きは破綻、EC2自前受信は運用が重い。
  <div class="dh">⚠️ つまずきやすい言葉</div>
  「大量データをリアルタイムで取り込む・複数の処理系に流す」＝Kinesis。「1件ずつ非同期に処理を渡す」だけならSQS、と<b>ストリームかキューか</b>で切り分ける。`
},
{
  id:36, cat:"可用性",
  scenario:"ある企業は、Auto Scaling グループ内の複数の Amazon EC2 インスタンスから、共有のファイルストレージにアクセスする必要があります。複数のインスタンスが同時に同じファイル群を読み書きし、インスタンスが増減してもすべてのインスタンスから同じデータが見える必要があります。同社は、Linux ベースで、NFS により複数台から同時にマウントすることを求めています。また、容量はデータ量に応じて自動的に伸縮する必要があります。",
  ask:'これらの要件を満たすソリューションはどれですか。',
  options:[
    "各EC2に個別のEBSボリュームをアタッチし、定期的にスクリプトで内容を相互に同期して、全インスタンスで同じデータを持たせる。",
    "Amazon EFSを作成し、複数AZの全EC2からNFSで同時マウントして、容量がデータ量に応じて自動伸縮する共有ストレージとして使う。",
    "S3バケットにファイルを置き、各EC2がアプリ起動時にそれをローカルのEBSへダウンロードしてから作業し、更新分は書き戻す方式にする。",
    "1台のEC2を自前のNFSサーバーに仕立てて他のEC2からマウントさせ、共有ファイルストレージとして提供して、その可用性も自分で管理する。"
  ],
  answer:1,
  keypoint:'「複数EC2から同時に読み書き」「インスタンス増減でも同じデータ」「NFSで同時マウント」「容量自動伸縮」。4つともデータ共有の手だが、<b>複数台同時マウントのマネージド共有FS</b>はどれか。',
  explain:'B＝EFSは複数AZの多数のEC2からNFSで同時マウントでき、容量がデータ量に応じて自動伸縮するフルマネージドの共有ファイルシステム。要件をすべて満たす。',
  elim:'A=EBSは原則1インスタンスにのみアタッチ（共有FSにならない・同期も手間）。C=S3＋各自ダウンロードは同時読み書きの共有ファイルシステムではない（オブジェクトストレージ）。D=自前NFSサーバーは単一障害点＋運用負担＋自動伸縮しない。複数台同時マウント＋自動伸縮はEFS。',
  confusion:'<b>EFS</b>＝複数EC2から同時マウントできる共有NFS・自動伸縮（共有ファイルストレージの定番）。<b>EBS</b>＝原則1台にアタッチのブロックストレージ（共有不可）。<b>S3</b>＝オブジェクトストレージ（ファイルシステムではない）。',
  deep:`
  <div class="dh">🏷 たとえ</div>
  <div class="nick"><b>EFS</b>＝みんなで使う共有の本棚。何人（複数EC2）でも同時に出し入れでき、棚は中身が増えれば勝手に広がる（自動伸縮）。</div>
  <div class="nick"><b>EBS</b>＝1人用の外付けHDD。基本1台にしか挿せない（共有できない）。</div>
  <div class="dh">💡 なぜこれが正解か</div>
  「複数台から同時に・NFSで・自動伸縮」＝共有ファイルシステムのEFSがそのもの。EBSは1台専用で共有にならず、自前NFSは単一障害点。
  <div class="dh">⚠️ つまずきやすい言葉</div>
  「複数EC2から同時マウント・NFS・共有」が出たらEFS。1台専用の高速ディスクならEBS、と<b>共有するかどうか</b>で切り分ける。`
},
{
  id:37, cat:"データベース",
  scenario:"ある企業は、オンプレミスの Oracle データベースを AWS へ移行する必要があります。スキーマやストアドプロシージャが Oracle 固有の書き方になっており、そのままでは移行先のオープンソース系データベースで動作しない部分があります。同社は、ダウンタイムをできるだけ抑えて移行する必要があります。同社は、Oracle 固有要素の変換と、稼働中データベースのデータ移行 (継続的レプリケーション) の両方を行う必要があります。",
  ask:'これらの要件を満たすソリューションはどれですか。',
  options:[
    "AWS Schema Conversion Tool（SCT）でスキーマ・ストアド等のOracle固有要素を変換し、AWS Database Migration Service（DMS）で稼働中DBから継続レプリケーションして低ダウンタイムで移行する。",
    "オンプレのOracleのデータをダンプにエクスポートしてS3にアップロードし、移行先DBへ手動でインポートして固有要素も書き換え、業務を止めて一括で切り替え、移行後は全件を突き合わせて検証する方式にする。",
    "AWS DataSyncでデータベースのファイルをそのままコピーし、移行先のEC2上にOracleをインストールしてリストアするだけでDBを移行し、エンジンはOracleのまま使い続けてライセンスやストアドもそのまま引き継ぐ。",
    "RDS for Oracleを作成してオンプレからそこへ継続レプリケーションし、エンジンをOracleのまま移行することでスキーマ変換を不要にして、固有のストアドも動かしたまま低ダウンタイムでの切り替えを狙う。"
  ],
  answer:0,
  keypoint:'「Oracle固有要素の変換が必要」「稼働中DBを低ダウンタイムで移行」。4つとも移行に関わるが、<b>スキーマ変換＋継続レプリケーション</b>の両方を担うのはどれか。',
  explain:'A＝SCTがOracle固有のスキーマ・ストアドを移行先（PostgreSQL等）向けに変換し、DMSが稼働中DBから継続的にレプリケーションすることでダウンタイムを最小化する。異種DB移行の王道の組み合わせ。',
  elim:'B=ダンプ→手動インポートは移行中に止める必要があり低ダウンタイムにならない＋Oracle固有要素の変換もしない。C=DataSyncはファイル転送ツールでDBの論理移行・スキーマ変換には使わない。D=RDS for Oracleで「Oracleのまま」だと設問の「オープンソース系へ移したい（固有要素の変換）」前提と異なり、低ダウンタイム移行の手段も別途必要。要件適合でA。',
  confusion:'<b>SCT</b>＝異種DB間のスキーマ・コード変換。<b>DMS</b>＝稼働中DBの継続レプリケーションで低ダウンタイム移行。異種DB（Oracle→PostgreSQL等）＝SCT＋DMSのセット。<b>DataSync</b>＝ファイル転送（DB論理移行には使わない）。',
  deep:`
  <div class="dh">🏷 たとえ</div>
  <div class="nick"><b>SCT</b>＝翻訳家。Oracle語で書かれた設計図・手続き（ストアド）を移行先のDB語に訳す。</div>
  <div class="nick"><b>DMS</b>＝引っ越し業者。営業しながら（稼働中）少しずつ荷物を運び、最後にサッと切り替える（低ダウンタイム）。</div>
  <div class="dh">💡 なぜこれが正解か</div>
  「Oracle固有を変換」＝SCT、「稼働中を低ダウンタイムで移行」＝DMS、の2つが揃って初めて要件を満たす。ダンプ手動は止める必要があり、DataSyncはDB移行用途でない。
  <div class="dh">⚠️ つまずきやすい言葉</div>
  異種DB移行は「変換（SCT）＋移行（DMS）」のセットで覚える。同種DBで変換不要ならDMS単独。<b>固有要素の変換が要るか</b>でSCTの要否が決まる。`
},
{
  id:38, cat:"コスト最適化",
  scenario:"ある大企業は、AWS Organizations 配下に何十ものアカウントを持ち、利用が拡大しています。経営層は、どのアカウント・どのサービスにいくら使用しているかを横断的に把握し、予算を超えそうなときに通知を受け取ること、および複数アカウントのボリューム割引やコミット割引を組織全体でまとめて適用することを求めています。同社は、組織全体のコストの可視化・予算管理・割引の集約を行う必要があります。",
  ask:'これらの要件を満たすソリューションはどれですか。',
  options:[
    "各アカウントに個別にログインしてCost Explorerでコストを確認し、その数字をExcelに転記して全社のコストを手作業で集計し、予算超過も人手で見張りつつ、割引の集約は行わずに毎月まとめる運用にする。",
    "AWS Organizationsの一括請求（Consolidated Billing）でアカウントを集約し、Cost Explorerで横断的に可視化、AWS Budgetsで予算超過を通知し、ボリューム/コミット割引を組織全体で共有する。",
    "各アカウントでAWS Budgetsを個別に設定して、それぞれのアカウントで予算超過アラートを受け取れるようにし、全社横断の可視化やボリューム/コミット割引の共有は行わず、アカウントごとに独立して管理する。",
    "CloudWatchの請求アラームを各アカウントに個別に設定し、合計請求額が一定額を超えたらSNSで通知を受け取って、全社のコストは各自で見張りつつ、部門別の按分や割引の集約は別途手作業で行う。"
  ],
  answer:1,
  keypoint:'「組織全体を横断可視化」「予算超過通知」「割引を組織で集約」。4つともコスト把握に関わるが、<b>組織横断の可視化＋予算＋割引共有</b>を一括で満たすのはどれか。',
  explain:'B＝Organizationsの一括請求でアカウントを集約すると、Cost Explorerで横断的にコストを見られ、Budgetsで予算超過を通知でき、ボリューム/コミット割引が組織全体で共有される。3要件を一度に満たす。',
  elim:'A=個別確認＋Excle手集計は組織横断の自動可視化でなく運用が破綻（手作業）。C=各アカウント個別のBudgetsでは組織横断の集約・割引共有ができない。D=請求アラームは通知の一部だけで、横断可視化や割引集約をカバーしない。組織横断を一括で満たすのは一括請求＋Cost Explorer＋Budgets。',
  confusion:'<b>一括請求（Consolidated Billing）</b>＝複数アカウントを集約し割引共有＋横断請求。<b>Cost Explorer</b>＝横断可視化。<b>Budgets</b>＝予算超過の通知。組織全体のコスト管理はこの3点セット。',
  deep:`
  <div class="dh">🏷 たとえ</div>
  <div class="nick"><b>一括請求</b>＝家族の携帯料金をまとめて1つの請求に。まとめるとボリューム割引が効く。</div>
  <div class="nick"><b>Cost Explorer</b>＝誰が何にいくら使ったかの家計簿（横断で見える）。</div>
  <div class="nick"><b>Budgets</b>＝「今月の予算を超えそう」と教えてくれるアラート。</div>
  <div class="dh">💡 なぜこれが正解か</div>
  「横断可視化＋予算通知＋割引集約」の3つを一度に満たすのは、一括請求でまとめた上でCost Explorer＋Budgetsを使う構成。個別設定は横断・集約ができない。
  <div class="dh">⚠️ つまずきやすい言葉</div>
  「組織全体・複数アカウントを横断」が出たら、まずOrganizationsの一括請求でまとめる発想。可視化＝Cost Explorer、予算通知＝Budgets、と役割で覚える。`
},
{
  id:39, cat:"疎結合",
  scenario:"ある企業は、ユーザーからのリクエストを Amazon SQS キューに入れ、ワーカー (コンシューマ) が取り出して処理しています。同社は、特定のメッセージで処理が失敗すると、ワーカーが同じメッセージを何度も取得しては失敗するループに陥り、キューが詰まって他の正常なメッセージの処理も遅延する事象を確認しました。同社は、繰り返し失敗するメッセージを切り分けて、正常な処理の流れを止めないようにする必要があります。",
  ask:'これらの要件を満たすソリューションはどれですか。',
  options:[
    "ワーカーの数を増やして並列処理を強化し、繰り返し失敗するメッセージがあっても、全体のスループットを上げることで詰まりを吸収する。",
    "可視性タイムアウトを長く設定して失敗メッセージが再表示されるまでの間隔を空け、その間に他の正常なメッセージの処理を進めて本流を止めないようにする。",
    "デッドレターキュー（DLQ）を設定し、maxReceiveCountを超えて失敗したメッセージをDLQへ自動退避させて、本流のキューから取り除く。",
    "FIFOキューに変更して順序保証と重複排除を効かせることで、繰り返し失敗するメッセージが何度も処理されないようにして本流への影響を抑える。"
  ],
  answer:2,
  keypoint:'「特定メッセージが繰り返し失敗」「ループでキューが詰まる」「失敗分を切り分けて本流を止めない」。4つともSQSの設定だが、<b>失敗を繰り返すメッセージを自動退避</b>するのはどれか。',
  explain:'C＝デッドレターキュー（DLQ）にmaxReceiveCountを設定すると、規定回数を超えて処理に失敗したメッセージがDLQへ自動的に移され、本流のキューから取り除かれる。詰まりの原因（毒メッセージ）を隔離できる。',
  elim:'A=ワーカー増強しても失敗メッセージのループは残り根本解決にならない。B=可視性タイムアウト延長は再試行間隔を変えるだけで、永久に失敗するメッセージは詰まり続ける。D=FIFOは順序・重複排除であって、繰り返し失敗するメッセージの隔離はしない。失敗メッセージの切り分けはDLQ。',
  confusion:'<b>DLQ＋maxReceiveCount</b>＝規定回数失敗したメッセージを自動退避（毒メッセージの隔離）。<b>可視性タイムアウト</b>＝再表示までの待ち時間（隔離はしない）。<b>FIFO</b>＝順序・重複排除。詰まりの原因隔離＝DLQ。',
  terms:[
    {t:"デッドレターキュー（DLQ）", d:"処理に失敗し続けるメッセージを退避させる専用キュー。本流のキューから毒メッセージを取り除いて詰まりを防ぐ。"},
    {t:"maxReceiveCount", d:"メッセージが何回受信（取得→失敗）されたらDLQへ送るかの閾値。"}
  ],
  deep:`
  <div class="dh">🏷 たとえ</div>
  <div class="nick"><b>DLQ</b>＝何度やっても処理できない不良品を「保留箱」に移す仕組み。ラインに不良品が居座って全体が止まるのを防ぐ。</div>
  <div class="nick"><b>可視性タイムアウト</b>＝処理中の品を一時的に隠す時間。延ばしても不良品が消えるわけではない。</div>
  <div class="dh">💡 なぜこれが正解か</div>
  「特定メッセージが失敗ループでキューを詰まらせる」＝毒メッセージ問題。規定回数失敗したら保留箱（DLQ）へ自動で逃がすのが直球。ワーカー増も待ち延長も毒は残る。
  <div class="dh">⚠️ つまずきやすい言葉</div>
  「繰り返し失敗するメッセージ」「処理が詰まる」が出たらDLQ＋maxReceiveCount。順序が主題ならFIFO、と症状で切り分ける。`
},
{
  id:40, cat:"高性能",
  scenario:"ある企業は、グローバルに展開する SaaS を運用しており、ユーザープロフィールとセッション状態を Amazon DynamoDB に保存しています。同社は、世界各地のユーザーが自分の地域から低遅延で読み書きでき、ある地域の障害時も他地域で継続できるマルチリージョン構成を必要としています。データはキー単位のアクセスが中心であり、同社は各地域でローカルに読み書きすることを求めています。",
  ask:'これらの要件を満たすソリューションはどれですか。',
  options:[
    "DynamoDBのオンデマンドキャパシティにして、単一リージョン内で読み書きのスケールに自動追従させ、各地域からはそのリージョンへアクセスさせる。",
    "DynamoDB Accelerator（DAX）を各地域に置いて読み取りをキャッシュし、地域ごとの読み取りレイテンシを下げて、マルチリージョンの読み書きに対応する。",
    "DynamoDBのデータをリージョン間でバックアップ＆リストアしておき、リージョン障害が起きたら別リージョンで復元して、そこから読み書きを再開する方式にする。",
    "DynamoDBグローバルテーブルを構成し、複数リージョンにレプリカを置いて各地域でローカルに読み書きでき、リージョン障害時も他地域で継続できるようにする。"
  ],
  answer:3,
  keypoint:'「各地域でローカルに読み書き」「マルチリージョンで障害継続」「DynamoDB・キー単位」。4つともDynamoDB関連だが、<b>複数リージョンで読み書きできる構成</b>はどれか。',
  explain:'D＝DynamoDBグローバルテーブルは複数リージョンにレプリカを持ち、各リージョンでローカルに読み書きでき（マルチアクティブ）、あるリージョンの障害時も他リージョンで継続できる。地域低遅延＋マルチリージョン冗長を満たす。',
  elim:'A=オンデマンドは単一リージョンのスケール追従で、地域分散・マルチリージョン冗長にはならない。B=DAXは読み取りキャッシュで、書き込みのマルチリージョンや障害時継続はカバーしない。C=バックアップ&リストアは復旧に時間がかかり「各地域でローカル読み書き」も満たさない。マルチリージョン読み書きはグローバルテーブル。',
  confusion:'<b>DynamoDBグローバルテーブル</b>＝複数リージョンでローカル読み書き＋マルチリージョン冗長（マルチアクティブ）。<b>DAX</b>＝読み取りキャッシュ（単一リージョンの高速化）。<b>Auroraグローバルデータベース</b>＝RDB版の同種機能。',
  deep:`
  <div class="dh">🏷 たとえ</div>
  <div class="nick"><b>グローバルテーブル</b>＝世界各地に同じ内容の台帳を置き、どの地域でも自分の近くの台帳に読み書きできる。書いた内容は他地域の台帳にも自動で反映される。1地域が倒れても他で続く。</div>
  <div class="nick"><b>DAX</b>＝読み取り専用の早出し係（キャッシュ）。書き込みのマルチリージョンや冗長はカバーしない。</div>
  <div class="dh">💡 なぜこれが正解か</div>
  「各地域でローカル読み書き＋障害時も他地域で継続」＝マルチアクティブなグローバルテーブル。DAXは読み取り高速化だけ、バックアップは復旧に時間がかかる。
  <div class="dh">⚠️ つまずきやすい言葉</div>
  DynamoDBで「マルチリージョンの読み書き・地域低遅延」＝グローバルテーブル。読み取りをマイクロ秒で速くだけならDAX、と<b>マルチリージョンか高速化か</b>で切り分ける。`
},
{
  id:41, cat:"セキュリティ",
  scenario:"ある企業は、Amazon S3 バケットに保存している大量のドキュメントの中に、クレジットカード番号やマイナンバー、個人情報などの機微情報が紛れ込んでいないかを継続的に把握する必要があります。同社は、どのバケット・どのオブジェクトに、どのような種類の個人情報がどれだけ含まれるかを自動で発見・分類し、漏洩リスクを可視化することを求めています。同社の社内には機械学習の専門知識がなく、自前で検出ロジックを作成することは避けたいと考えています。",
  ask:'これらの要件を満たすソリューションはどれですか。',
  options:[
    "Amazon Macieを有効化し、S3バケットを継続スキャンしてクレジットカード番号や個人情報などの機微情報を自動で発見・分類し、リスクを可視化する。",
    "Amazon GuardDutyを有効化し、S3への不審なアクセスやAPI呼び出しを検知して、その通信パターンから機微情報の漏洩リスクを把握する。",
    "AWS Configのルールで、暗号化されていないS3バケットや公開設定を検出してコンプライアンス状態を管理し、機微情報まわりのリスクを把握する。",
    "Amazon Inspectorで、S3にアクセスするEC2やコンテナの脆弱性(CVE)をスキャンして、機微情報まわりのリスクを間接的に把握する。"
  ],
  answer:0,
  keypoint:'「S3内の個人情報・機微情報を発見・分類」「自前ロジックを作りたくない」。4つともセキュリティサービスだが、<b>S3内の機微データの中身を発見・分類</b>するのはどれか。',
  explain:'A＝MacieはMLを使ってS3内のオブジェクトをスキャンし、クレジットカード番号・個人情報などの機微情報を自動で発見・分類してリスクを可視化する。データの中身の検出の専用サービス。',
  elim:'B=GuardDutyは脅威・不審アクセスの検知で、データの中身（個人情報が含まれるか）は分類しない。C=Configは構成（暗号化されているか等）の検出で、中身の個人情報は見ない。D=Inspectorは脆弱性スキャンでデータ内容の分類はしない。S3内の機微情報の発見・分類はMacie。',
  confusion:'セキュリティの守備範囲：<b>Macie</b>＝S3内の個人情報・機微データの発見と分類。<b>GuardDuty</b>＝脅威・不審な挙動の検知。<b>Config</b>＝構成の逸脱。<b>Inspector</b>＝脆弱性。「データの中身に個人情報」＝Macie。',
  deep:`
  <div class="dh">🏷 たとえ</div>
  <div class="nick"><b>Macie</b>＝書類棚を1枚ずつめくって「これはマイナンバーが書いてある」「これはカード番号」と中身を仕分ける個人情報の専門家。</div>
  <div class="nick"><b>GuardDuty</b>＝棚に不審な人が近づいたら教える警備員（中身は見ない）。</div>
  <div class="nick"><b>Config</b>＝棚に鍵がかかっているか（暗号化）を点検する係（中身は見ない）。</div>
  <div class="dh">💡 なぜこれが正解か</div>
  「S3の中身に個人情報が紛れていないか発見・分類」＝データの中身を読むMacie。GuardDutyは挙動、Configは構成、Inspectorは脆弱性で、どれも中身の機微情報は分類しない。
  <div class="dh">⚠️ つまずきやすい言葉</div>
  「個人情報・機微データの発見/分類」はMacieの専売。「脅威の検知」はGuardDuty、と<b>データの中身か挙動か</b>で切り分ける。`
},
{
  id:42, cat:"サーバーレス",
  scenario:"ある企業は、サーバーレスアプリケーションを Amazon API Gateway → AWS Lambda → Amazon RDS (MySQL) という構成で運用しています。アクセスが急増すると Lambda の同時実行が一気に増え、各 Lambda 関数が新規にデータベース接続を確立するため、RDS の接続数が枯渇してエラーになります。同社は、Lambda はそのままに、データベースへの接続を効率化して接続枯渇を防ぐ必要があります。同社は、コードの大幅な改修を避けたいと考えています。",
  ask:'これらの要件を満たすソリューションはどれですか。',
  options:[
    "Lambdaの予約済み同時実行数を低く制限して、RDSへの同時接続数が一定を超えないように抑え込み、スループットを犠牲にして枯渇を防ぐ。",
    "RDS Proxyを導入し、LambdaとRDSの間でコネクションをプールして多数の同時実行が少数の接続を共有するようにする。",
    "RDSをAuroraに移行し、リードレプリカを複数増やして接続先を分散することで、1台あたりの接続数を下げて枯渇を緩和する。",
    "Lambdaの処理を見直し、関数の実行ごとにDB接続を開いて処理後すぐ閉じる短命接続に改修して、接続が溜まらないようにする。"
  ],
  answer:1,
  keypoint:'「Lambda急増でRDS接続枯渇」「Lambdaはそのまま」「コード改修最小」。4つとも接続枯渇に関わる手だが、<b>コネクションプールで接続を共有しつつ改修最小</b>はどれか。',
  explain:'B＝RDS Proxyは間に入ってコネクションをプール・再利用するので、Lambdaの同時実行が増えても少数の接続を共有でき、接続枯渇を防ぐ。Lambda側のコード改修もほぼ不要。',
  elim:'A=同時実行制限はスループットを犠牲にして枯渇を避けるだけで処理が詰まる。C=Auroraへの移行＋レプリカは大がかりで、書き込みの接続枯渇そのものはコネクション管理が要る。D=接続を開閉する改修はコード変更が大きく、Lambdaの性質上コネクション再利用が効きにくい。改修最小で枯渇を防ぐのはRDS Proxy。',
  confusion:'<b>RDS Proxy</b>＝コネクションプールで接続を共有（Lambda×RDSの接続枯渇の定番・改修最小）。<b>同時実行制限</b>＝枯渇は防げるがスループット犠牲。Lambda＋RDSの接続枯渇＝まずRDS Proxy。',
  deep:`
  <div class="dh">🏷 たとえ</div>
  <div class="nick"><b>RDS Proxy</b>＝受付の取次。客（Lambda）が大勢来ても奥の窓口（DB接続）を限られた数で使い回す。客が増えても窓口がパンクしない。Lambda側は受付に頼むだけで作法を変えなくていい（改修最小）。</div>
  <div class="dh">💡 なぜこれが正解か</div>
  Lambdaは同時実行ごとに接続を張るので急増で枯渇する。これを使い回し（プール）で根本から解くのがRDS Proxy。同時実行制限は詰まり、Aurora移行は大がかり。
  <div class="dh">⚠️ つまずきやすい言葉</div>
  「Lambda＋RDSで接続数が枯渇」は<b>RDS Proxy</b>を選ばせる典型。読み取り遅延ならElastiCache/レプリカ、と症状で切り分ける（接続枯渇＝Proxy）。`
},
{
  id:43, cat:"ストレージ",
  scenario:"ある企業は、建築設計事務所を営んでおり、Windows ベースのファイルサーバーを AWS へ移行する必要があります。複数の Windows クライアントから SMB プロトコルで共有フォルダにアクセスし、Active Directory と統合したアクセス権管理 (既存のドメインユーザーでの認証) も必要です。同社は、Windows アプリケーションとの互換性が高い、フルマネージドの共有ファイルストレージを必要としています。",
  ask:'これらの要件を満たすソリューションはどれですか。',
  options:[
    "Amazon EFS(NFS)を作成し、Windowsクライアントから何らかの方法でマウントして共有ファイルストレージとして使い、SMBやAD統合は別途代替して運用する。",
    "S3バケットに共有ファイルを置き、各Windowsクライアントからマウントツールやアプリ経由でアクセスして、従来の共有フォルダの代わりとして使う。",
    "Amazon FSx for Windows File Serverを使い、SMBアクセス・Active Directory統合・Windows互換のフルマネージド共有ファイルストレージを提供する。",
    "EC2にWindows Serverを立ててファイルサーバーロールを構成し、自前でSMB共有とActive Directory統合を設定して、その可用性やパッチも継続的に運用する。"
  ],
  answer:2,
  keypoint:'「Windows互換」「SMB」「AD統合」「フルマネージド共有FS」。4つともファイル共有の手だが、<b>Windows向けのマネージド共有ファイルサーバー</b>はどれか。',
  explain:'C＝FSx for Windows File ServerはSMBプロトコル、Active Directory統合、Windows互換をフルマネージドで提供する。Windowsファイルサーバー移行の専用サービスで要件すべてに合致。',
  elim:'A=EFSはLinux向けのNFSで、SMB/AD統合のWindows共有には適さない。B=S3はオブジェクトストレージで共有フォルダ（SMB）にならない。D=EC2自前Windowsファイルサーバーは実現できるが運用・パッチ・可用性の管理が全部残り「フルマネージド」に反する。Windows共有のマネージドはFSx for Windows。',
  confusion:'共有ファイルストレージ：<b>FSx for Windows</b>＝SMB・AD統合・Windows互換（Windowsファイルサーバー）。<b>EFS</b>＝NFS・Linux向け。<b>S3</b>＝オブジェクト（ファイル共有ではない）。Windows＋SMB＋AD＝FSx for Windows。',
  deep:`
  <div class="dh">🏷 たとえ</div>
  <div class="nick"><b>FSx for Windows</b>＝Windows用の共有フォルダをまるごと貸してくれるサービス。既存の社員アカウント（AD）でそのままログインでき、Windowsアプリも今まで通り。管理は任せられる。</div>
  <div class="nick"><b>EFS</b>＝Linux向けの共有本棚（NFS）。Windowsの共有フォルダ（SMB）とは作法が違う。</div>
  <div class="dh">💡 なぜこれが正解か</div>
  「Windows・SMB・AD統合・マネージド」＝FSx for Windowsがそのもの。EFSはLinux/NFS、S3はファイル共有でなく、自前EC2は運用が残る。
  <div class="dh">⚠️ つまずきやすい言葉</div>
  共有ファイルは「Windows/SMB/AD＝FSx for Windows」「Linux/NFS＝EFS」で切り分ける。オブジェクト保存ならS3、と用途で区別。`
},
{
  id:44, cat:"疎結合",
  scenario:"ある企業は、社内外のさまざまなイベント源 (SaaS アプリケーションの通知、AWS サービスの状態変化、定期スケジュール) を受け取り、その内容 (イベントの種類や属性) に応じて、適切な複数のターゲット (AWS Lambda、Amazon SQS、AWS Step Functions など) へ振り分ける必要があります。ルールは今後増える見込みであり、同社は、イベントの中身でフィルタして柔軟にルーティングすることを求めています。",
  ask:'これらの要件を満たすソリューションはどれですか。',
  options:[
    "Amazon EventBridgeのイベントバスとルールを使い、イベントの中身（パターン）でフィルタして、複数のターゲットへ柔軟にルーティングする。",
    "Amazon SNSトピックにすべてのイベントをパブリッシュして全サブスクライバに同報し、各受け手が自分に必要なイベントかどうかを受信後に判断して処理させる。",
    "Amazon SQSキューにすべてのイベントを入れ、コンシューマが各メッセージを読んで内容ごとに処理を分岐させ、ルーティングのロジックはコンシューマ側に作り込む。",
    "Amazon Kinesis Data Streamsに全イベントを流し、各コンシューマがストリームを読んで自分に必要なイベントだけを選んで処理する構成にする。"
  ],
  answer:0,
  keypoint:'「多様なイベント源」「中身（属性）でフィルタ」「複数ターゲットへルーティング」「ルールが増える」。4つとも連携手段だが、<b>内容ベースのフィルタ＋ルーティング</b>に特化するのはどれか。',
  explain:'A＝EventBridgeはイベントの中身（JSONのパターン）でフィルタするルールを定義し、SaaS/AWS/スケジュールなど多様な源から複数ターゲットへ柔軟にルーティングできる。内容ベースルーティングの専用サービス。',
  elim:'B=SNSは同報（fanout）で、内容でのきめ細かいフィルタ・ルーティングは主目的でない。C=SQSはキューで、分岐ロジックをコンシューマ側に全部書く必要がある。D=Kinesisはストリーム処理向けで、ルールベースのイベントルーティングではない。内容フィルタ＋多ターゲットはEventBridge。',
  confusion:'<b>EventBridge</b>＝イベントの中身でフィルタ＋多様な源/ターゲットへルーティング（ルールベース）。<b>SNS</b>＝単純な同報（fanout）。<b>SQS</b>＝1対1のキュー。中身で賢く振り分けるならEventBridge。',
  deep:`
  <div class="dh">🏷 たとえ</div>
  <div class="nick"><b>EventBridge</b>＝郵便の自動仕分け機。届いた手紙の中身（差出人・種類）を見て「これは経理へ」「これは出荷へ」と複数の宛先に賢く振り分ける。仕分けルールは後から足せる。</div>
  <div class="nick"><b>SNS</b>＝一斉放送（拡声器）。全員に同じ内容を流すだけで中身の仕分けはしない。</div>
  <div class="dh">💡 なぜこれが正解か</div>
  「多様な源・中身でフィルタ・複数ターゲット・ルール追加」＝内容ベースルーティングのEventBridge。SNSは同報のみ、SQSは分岐を自前実装。
  <div class="dh">⚠️ つまずきやすい言葉</div>
  「1つを単純に複数へ同報」＝SNS、「中身を見て条件で振り分け・SaaSやスケジュールも源」＝EventBridge。<b>フィルタ・ルーティングの賢さ</b>で切り分ける。`
},
{
  id:45, cat:"配信/CDN",
  scenario:"ある企業は、動画教材サービスを運用しており、有料会員にだけ限定動画を Amazon CloudFront 経由で配信する必要があります。動画は Amazon S3 に置き、CloudFront で配信します。同社は、会員がログイン後に取得した URL でのみ、かつ一定時間だけ動画にアクセスでき、URL を他人に共有されても期限が切れれば視聴できないようにすることを求めています。同社は、非会員や期限切れのアクセスを拒否する必要があります。",
  ask:'これらの要件を満たすソリューションはどれですか。',
  options:[
    "S3バケットを公開設定にしてCloudFrontから配信し、URLを知っている会員だけがアクセスする運用にして、URLが漏れない前提で限定配信とみなす。",
    "CloudFrontの署名付きURL（または署名付きCookie）を使い、会員に期限付きの署名URLを発行して、有効期限内のアクセスだけを許可する。",
    "WAFをCloudFrontに関連付け、会員のIPアドレスを許可リストに登録してアクセスを制御し、許可IP以外からの視聴をブロックして限定配信にする。",
    "CloudFrontのGeo Restrictionで配信先の国を限定し、許可した地域からのアクセスだけを通すことで、その地域の会員だけが視聴できるようにする。"
  ],
  answer:1,
  keypoint:'「会員のみ」「一定時間だけ」「URL共有されても期限切れで無効」。4つともアクセス制御に関わるが、<b>期限付きで本人にだけ許可</b>するのはどれか。',
  explain:'B＝CloudFrontの署名付きURL/Cookieは、有効期限付きのアクセス権を会員に発行する。期限内のアクセスだけ許可され、期限が切れればURLを共有されても見られない。限定コンテンツ配信の定石。',
  elim:'A=S3公開＋URL頼みは、URLが漏れれば誰でも無期限にアクセスできる（期限・会員制御なし）。C=WAFのIP許可リストは会員のIPが変動・多数で管理不能。D=Geo Restrictionは国単位の制限で、個々の会員や期限の制御はできない。期限付き・本人限定は署名付きURL。',
  confusion:'<b>CloudFront署名付きURL/Cookie</b>＝期限付き・限定的なアクセス権を発行（有料会員/限定配信）。<b>Geo Restriction</b>＝国単位の制限。<b>WAF</b>＝攻撃やIPの制御。会員＋期限＝署名付きURL。',
  terms:[
    {t:"署名付きURL/Cookie", d:"有効期限やアクセス条件を埋め込んだURL/Cookie。期限内のみコンテンツにアクセスでき、期限切れ後は共有されても無効。"}
  ],
  deep:`
  <div class="dh">🏷 たとえ</div>
  <div class="nick"><b>署名付きURL</b>＝時間制限つきの入場チケット。会員に「23時まで有効」のチケットを渡す。時間を過ぎたら、誰かに見せても入れない。</div>
  <div class="nick"><b>S3公開＋URL</b>＝鍵のかかっていないドアに「URLを知ってる人だけ来てね」と貼るだけ。漏れたら誰でも無期限で入れる。</div>
  <div class="dh">💡 なぜこれが正解か</div>
  「会員だけ・一定時間だけ・共有されても期限切れで無効」＝期限付きチケットの署名付きURL。Geoは国単位、WAFはIP管理が破綻、公開は制御なし。
  <div class="dh">⚠️ つまずきやすい言葉</div>
  「特定ユーザーに・期限付きで」＝署名付きURL/Cookie。「国で制限」＝Geo Restriction、と<b>制御の単位（個人＋期限か、地域か）</b>で切り分ける。`
},
{
  id:46, cat:"データベース",
  scenario:"ある企業は、社内向けの分析ツールのバックエンドに Amazon Aurora (PostgreSQL 互換) を使用しています。このツールは平日の日中だけ断続的に使用され、夜間や週末はほとんどアクセスがありません。また、アクセスがある時間帯でも、負荷は大きく上下します。同社は、インスタンスを常時起動しておくと無駄が多いことを確認しました。同社は、使用されない時間帯はデータベースを停止し、使用され始めたら自動的に起動して、負荷に応じて容量が伸縮するデータベースを必要としています。",
  ask:'これらの要件を満たすソリューションはどれですか。',
  options:[
    "Auroraプロビジョンドインスタンスを最小サイズで常時起動し、負荷が上がったらインスタンスクラスを手動でスケールアップする。",
    "Auroraプロビジョンドクラスタに対し、夜間・週末はインスタンスを停止するスケジュールをLambdaで組んでコストを抑える。",
    "Aurora Serverless v2を使い、アクセスに応じて容量（ACU）を自動で伸縮させ、低負荷時は最小容量まで下げてコストを抑える。",
    "RDS for PostgreSQLをMulti-AZで構築し、リードレプリカで負荷の上下に対応する。"
  ],
  answer:2,
  keypoint:'「断続利用」「未使用時は無駄を避けたい」「負荷が大きく上下」「自動伸縮」。4つともAurora/RDSの構成だが、<b>負荷に応じて容量を自動伸縮し低負荷で絞る</b>のはどれか。',
  explain:'C＝Aurora Serverless v2はアクセスに応じて容量（ACU）を秒単位で自動伸縮し、低負荷時は最小容量まで下げる。断続的で負荷変動が大きく、常時フル起動が無駄なワークロードに最適。',
  elim:'A=最小常時起動＋手動スケールは手間がかかり自動伸縮しない。B=Lambdaで停止スケジュールを組むのは自前運用＋負荷変動への自動追従ではない。D=RDS Multi-AZ＋レプリカは可用性/読み取り分散で、断続利用のコスト最適化（容量自動伸縮）の解ではない。自動伸縮はServerless v2。',
  confusion:'<b>Aurora Serverless v2</b>＝負荷に応じ容量を自動伸縮（断続利用・変動大・常時起動が無駄な時）。<b>プロビジョンド</b>＝固定容量を常時起動（安定した負荷向け）。断続・変動が大きい＝Serverless v2。',
  deep:`
  <div class="dh">🏷 たとえ</div>
  <div class="nick"><b>Aurora Serverless v2</b>＝人が来たら自動で明かりがつき、いなくなったら絞るセンサー照明。使う分だけ容量が伸縮するのでアイドルの無駄が少ない。</div>
  <div class="nick"><b>プロビジョンド</b>＝つけっぱなしの照明。安定して使うなら良いが、断続利用だと消し忘れ（アイドル課金）が無駄。</div>
  <div class="dh">💡 なぜこれが正解か</div>
  「断続・負荷の上下が大きい・常時起動は無駄」＝容量を自動伸縮するServerless v2。手動スケールや停止スケジュール自作は運用が残る。
  <div class="dh">⚠️ つまずきやすい言葉</div>
  「負荷が読めない・断続・自動で伸縮」＝Serverless v2。「安定して常時一定の負荷」＝プロビジョンド、と<b>負荷の変動と連続性</b>で切り分ける。`
},
{
  id:47, cat:"セキュリティ",
  scenario:"ある企業は、一般消費者向けのモバイルアプリケーションと Web アプリケーションを新規に構築しています。同社は、数百万人規模のエンドユーザーのサインアップおよびサインイン (メールアドレスとパスワード、Google や Apple などのソーシャルログイン、MFA) を実装する必要があります。同社は、ユーザーディレクトリの管理やトークンの発行を自前で構築せず、マネージドなサービスに任せたいと考えています。これは社内の管理者向けの権限管理ではなく、アプリケーションの利用者の認証です。",
  ask:'これらの要件を満たすソリューションはどれですか。',
  options:[
    "エンドユーザーごとにIAMユーザーを作成し、IAMの認証情報でアプリにログインさせる。",
    "Amazon Cognitoのユーザープールを使い、サインアップ/サインイン・ソーシャルログイン・MFA・トークン発行をマネージドに提供する。",
    "IAM Identity Center（SSO）でエンドユーザーを管理し、各ユーザーに許可セットを割り当ててアプリにアクセスさせる。",
    "AWS Directory Service（Managed Microsoft AD）にエンドユーザーを登録し、ディレクトリ認証でアプリにログインさせる。"
  ],
  answer:1,
  keypoint:'「アプリの利用者（toC、数百万人）」「サインアップ/サインイン・ソーシャル・MFA」「自前で作らずマネージド」。4つとも認証に関わるが、<b>アプリ利用者向けのID管理</b>はどれか。',
  explain:'B＝Cognitoのユーザープールは、アプリのエンドユーザー向けにサインアップ/サインイン、ソーシャルログイン、MFA、トークン発行をマネージドで提供する。toCの大規模ユーザー認証の標準。',
  elim:'A=IAMユーザーは「AWSを操作する人（管理者・開発者）」向けで、数百万のエンドユーザーには使わない（破綻・誤用）。C=IAM Identity Centerは社員のAWSアクセス管理で、アプリ利用者の認証ではない。D=Managed ADは社内ディレクトリ向けで、toCの大規模サインアップには合わない。アプリ利用者の認証はCognito。',
  confusion:'認証の対象：<b>Cognito</b>＝アプリの利用者（toC・サインアップ/ソーシャル/MFA）。<b>IAM</b>＝AWSを操作する人（管理者・アプリのロール）。<b>IAM Identity Center</b>＝社員のAWS SSO。「アプリのお客さんのログイン」＝Cognito。',
  deep:`
  <div class="dh">🏷 たとえ</div>
  <div class="nick"><b>Cognito</b>＝お店のお客さん用の会員システム。何百万人でも会員登録・ログイン・SNS連携・二段階認証をまるごと面倒みる。</div>
  <div class="nick"><b>IAM</b>＝店の従業員用の社員証（AWSを操作する人向け）。お客さん一人ひとりに社員証は配らない。</div>
  <div class="dh">💡 なぜこれが正解か</div>
  「アプリの利用者・数百万・ソーシャル・MFA」＝toC認証のCognito。IAMユーザーは管理者向けで数百万のエンドユーザーには使わない。
  <div class="dh">⚠️ つまずきやすい言葉</div>
  「アプリのお客さんのログイン」＝Cognito、「AWSを操作する社員・開発者」＝IAM/Identity Center。<b>認証する相手がお客さんか社員か</b>で切り分ける。`
},
{
  id:48, cat:"高性能",
  scenario:"ある企業は、部門ごと、および本番環境と検証環境ごとに分かれた複数の VPC と、複数のオンプレミス拠点を相互に接続する必要があります。現在、同社は VPC ピアリングを個別に張っていますが、VPC と拠点が増えるたびに接続 (ピアリングや VPN) が網の目のように増加し、ルーティングの管理が破綻しかけています。同社は、多数の VPC とオンプレミスを、中央のハブで一元的に相互接続し、ルーティングを管理する必要があります。",
  ask:'これらの要件を満たすソリューションはどれですか。',
  options:[
    "すべてのVPC間でVPCピアリングをフルメッシュに張り、各VPCのルートテーブルに相互の経路を追加して相互接続する。",
    "各VPCにNATゲートウェイを置き、インターネット経由で相互に通信できるようにして接続管理を簡素化する。",
    "AWS Transit Gatewayをハブとして各VPCとオンプレVPNを接続し、中央で一元的にルーティングを管理する。",
    "各VPCにVPCエンドポイントを設定し、AWSサービス経由で相互の通信を中継させて接続する。"
  ],
  answer:2,
  keypoint:'「多数のVPC＋複数オンプレ」「ピアリングが網の目で破綻」「中央ハブで一元管理」。4つとも接続に関わるが、<b>ハブ&スポークで一元ルーティング</b>するのはどれか。',
  explain:'C＝Transit Gatewayは中央のハブとして多数のVPCとオンプレVPNを接続し、ルーティングを一元管理する。VPCや拠点が増えてもハブに繋ぐだけで済み、フルメッシュの複雑さを解消する。',
  elim:'A=フルメッシュのピアリングはVPCが増えるほど接続数が爆発し管理が破綻する（今の問題そのもの）。B=NAT＋インターネット経由はセキュリティ・経路管理上不適でVPC間相互接続の正攻法でない。D=VPCエンドポイントはAWSサービスへの接続で、VPC同士やオンプレの相互接続のハブではない。ハブ集約はTransit Gateway。',
  confusion:'<b>Transit Gateway</b>＝多数のVPC・オンプレを中央ハブで一元接続・ルーティング（ハブ&スポーク）。<b>VPCピアリング</b>＝1対1接続（数が増えるとフルメッシュで破綻）。多数を束ねるならTransit Gateway。',
  deep:`
  <div class="dh">🏷 たとえ</div>
  <div class="nick"><b>VPCピアリング</b>＝部屋同士を1本ずつ廊下でつなぐ。3部屋なら3本だが、10部屋だと45本（フルメッシュ）で管理不能。</div>
  <div class="nick"><b>Transit Gateway</b>＝中央のロビー（ハブ）。各部屋はロビーに1本つなぐだけで全部屋とつながる。新しい部屋もロビーに1本足すだけ。</div>
  <div class="dh">💡 なぜこれが正解か</div>
  「VPC・拠点が増えて網の目で破綻」＝ハブで束ねるTransit Gatewayの出番。ピアリングのフルメッシュは接続数が爆発するのが当の問題。
  <div class="dh">⚠️ つまずきやすい言葉</div>
  VPCが少数の1対1ならピアリングで十分だが、<b>多数のVPC＋オンプレを一元管理</b>が出たらTransit Gateway。「数が増えて管理が破綻」がハブ集約の合図。`
},
{
  id:49, cat:"可用性",
  scenario:"ある企業が、重要な静的コンテンツとバックアップデータを東京リージョンのS3に保存している。コンプライアンス要件で、リージョン全体の災害に備えて別リージョンにもデータのコピーを保持し、東京が失われても別リージョンからデータを取り出せるようにしたい。新しく書き込まれたオブジェクトも自動で別リージョンに複製されてほしい。",
  ask:'これらの要件を満たすソリューションはどれですか。',
  options:[
    "S3バージョニングを有効化して、同一リージョン内でオブジェクトの過去バージョンを保持してデータを保護する。",
    "S3のクロスリージョンレプリケーション（CRR）を設定し、新規オブジェクトを自動で別リージョンのバケットへ複製する。",
    "定期的にS3バケットの内容をAWS Backupでバックアップし、同一リージョン内に保管して復旧に備える。",
    "S3 Intelligent-Tieringを有効化して、アクセス頻度に応じて自動で階層を移動させてデータを保護する。"
  ],
  answer:1,
  keypoint:'「別リージョンにコピー保持」「リージョン災害に備える」「新規オブジェクトも自動複製」。4つともS3のデータ保護機能だが、<b>別リージョンへの自動複製</b>はどれか。',
  explain:'B＝クロスリージョンレプリケーション（CRR）は、新しく書き込まれたオブジェクトを自動で別リージョンのバケットへ複製する。リージョン全体の災害に備えてデータの地理的冗長を確保できる。',
  elim:'A=バージョニングは同一リージョン内の世代管理で、リージョン災害には備えられない。C=AWS Backupでも同一リージョン保管ではリージョン災害に対応できない（別リージョン保管にする必要があり、S3の自動複製要件にはCRRが直接的）。D=Intelligent-Tieringはコスト最適化で、リージョン冗長ではない。別リージョン自動複製はCRR。',
  confusion:'<b>CRR（クロスリージョンレプリケーション）</b>＝新規オブジェクトを別リージョンへ自動複製（リージョン災害対策）。<b>バージョニング</b>＝同一リージョンの世代管理。<b>同一リージョンレプリケーション（SRR）</b>＝同一リージョン内複製。リージョン跨ぎの冗長＝CRR。',
  deep:`
  <div class="dh">🏷 たとえ</div>
  <div class="nick"><b>CRR</b>＝大事な書類を別の街の支店にも自動で複写して送る。本店（東京）が被災しても支店（別リージョン）に同じ書類がある。</div>
  <div class="nick"><b>バージョニング</b>＝同じ棚に過去の版を残すだけ。棚（リージョン）ごと焼けたら全部失う。</div>
  <div class="dh">💡 なぜこれが正解か</div>
  「別リージョンにコピー・リージョン災害に備える・新規も自動」＝CRR。バージョニングやIntelligent-Tieringは同一リージョン内の話でリージョン災害に効かない。
  <div class="dh">⚠️ つまずきやすい言葉</div>
  「リージョンをまたいで複製」＝CRR、「同じリージョンで世代管理」＝バージョニング。<b>リージョンを跨ぐかどうか</b>で切り分ける。`
},
{
  id:50, cat:"配信/CDN",
  scenario:"ある企業は、メディアサービスを運用しており、静的サイトと画像を Amazon S3 に保存し、Amazon CloudFront 経由で配信しています。同社は、S3 バケットへの直接アクセス (CloudFront を経由しない URL でのアクセス) を禁止し、必ず CloudFront 経由でのみコンテンツにアクセスさせる必要があります。同社は、S3 バケットをパブリックにせず、CloudFront からのリクエストだけを許可する必要があります。",
  ask:'これらの要件を満たすソリューションはどれですか。',
  options:[
    "S3バケットをパブリック読み取りに設定し、利用者にはCloudFrontのURLだけを案内して、S3の直URLへの直接アクセスは控えてもらう運用上の取り決めで対応する。",
    "CloudFrontのOrigin Access Control（OAC）を設定し、バケットポリシーでそのCloudFrontディストリビューションからのアクセスのみを許可して、S3は非公開のままにする。",
    "S3バケットにIPアドレス制限のバケットポリシーを付け、CloudFrontのエッジが使うIPレンジからのアクセスだけを許可して、変動するそのIP一覧を保守し続ける。",
    "AWS WAFをS3バケットに直接関連付けて、CloudFront以外の送信元からのリクエストをブロックすることで、S3への直接アクセスを防ぐ。"
  ],
  answer:1,
  keypoint:'「S3は非公開のまま」「CloudFront経由のみ許可」「直接アクセス禁止」。4つともアクセス制御の手だが、<b>S3を非公開にしたままCloudFrontだけに許可</b>するのはどれか。',
  explain:'B＝OAC（Origin Access Control）を設定し、バケットポリシーで特定のCloudFrontディストリビューションからのアクセスのみ許可すれば、S3を非公開のまま「CloudFront経由のみ」を実現できる。S3+CloudFrontの定石。',
  elim:'A=S3パブリック＋URL案内では直接アクセスを技術的に防げない（誰でもバケットURLで取得可能）。C=CloudFrontのエッジIPは膨大で変動しIP制限は非現実的。D=WAFはS3バケットに直接関連付けできない（CloudFront/ALB等に付ける）。S3非公開＋CloudFront限定はOAC。',
  confusion:'<b>OAC（Origin Access Control）</b>＝S3を非公開のままCloudFront経由のみ許可（直接アクセス禁止の定番。旧OAIの後継）。S3公開＋URL頼み（A）は防げない。',
  terms:[
    {t:"OAC（Origin Access Control）", d:"CloudFrontがS3オリジンにアクセスするための仕組み。バケットを非公開のまま、特定のディストリビューションからのアクセスだけを許可できる（旧OAIの後継）。"}
  ],
  deep:`
  <div class="dh">🏷 たとえ</div>
  <div class="nick"><b>OAC</b>＝倉庫（S3）の鍵を配送業者（CloudFront）だけに渡す仕組み。倉庫は施錠したまま（非公開）、業者経由でしか中身を出せない。</div>
  <div class="nick"><b>S3公開＋URL案内</b>＝倉庫を開けっ放しにして「正面（CloudFront）から来てね」と頼むだけ。裏口（直URL）から誰でも入れる。</div>
  <div class="dh">💡 なぜこれが正解か</div>
  「S3は非公開・CloudFront経由のみ」＝OACでバケットポリシーをCloudFront限定にする。公開＋お願いは技術的に防げず、エッジIP制限は非現実的。
  <div class="dh">⚠️ つまずきやすい言葉</div>
  「CloudFront経由のみ・S3直アクセス禁止」が出たらOAC（旧OAI）。WAFはS3に直接は付かない（CloudFront/ALBに付ける）点も押さえる。`
},
{
  id:51, cat:"AI/ML",
  scenario:"ある企業は、SaaS 製品を提供しており、その問い合わせ対応に追われています。質問の多くは公開済みのマニュアルや FAQ に答えがありますが、利用者は自然な文章で質問してきます。同社は、社内の文書 (マニュアルや FAQ) を根拠として、自然な文章で回答を生成するチャットボットを構築する必要があります。同社の社内には機械学習の専門家がおらず、モデルを一から訓練することは避けたいと考えています。また、同社は、自社文書に基づいて回答させ、根拠のない作り話を避ける必要があります。",
  ask:'これらの要件を満たすソリューションはどれですか。',
  options:[
    "Amazon SageMakerで自社の質問応答モデルをゼロから訓練・デプロイして社内文書に答えられるようにし、データサイエンティストを確保して継続的に再学習する。",
    "Amazon Comprehendで問い合わせ文の感情やキーフレーズを分析し、その分類結果に応じてあらかじめ用意した定型文を返すチャットボットとして構成する。",
    "Amazon Bedrockの基盤モデルに、社内文書を検索して関連箇所を渡すRAG構成（Knowledge Bases等）を組み、自社文書を根拠に自然文で回答を生成する。",
    "Amazon Translateで多言語の問い合わせをいったん翻訳し、その翻訳結果を既存のFAQと文字列一致させて、最も近い項目の回答を返す方式にする。"
  ],
  answer:2,
  keypoint:'土台＝専門家なし・自社文書が根拠・自然文で回答・作り話を避けたい。4つともAIサービスだが、<b>基盤モデル＋自社文書検索（RAG）で根拠ある回答生成</b>はどれか。',
  explain:'C＝Bedrockの基盤モデルにRAG（社内文書を検索して関連箇所をモデルに渡す）を組むと、自社文書を根拠に自然文で回答でき、訓練不要で作り話（ハルシネーション）も抑えられる。生成AIチャットボットの定番構成。',
  elim:'A=SageMakerでゼロから訓練は専門家・データ・時間が必要で「専門家なし」に反する。B=Comprehendは分析（感情・キーフレーズ）で自然文の回答生成はしない。D=Translateは翻訳で、質問応答の生成はしない。根拠ある自然文生成はBedrock＋RAG。',
  confusion:'<b>Bedrock（＋RAG）</b>＝基盤モデルで自然文生成・自社文書を根拠に（訓練不要の生成AI）。<b>Comprehend</b>＝テキストの分析（生成しない）。<b>SageMaker</b>＝自前モデル訓練。生成AIで自社文書回答＝Bedrock＋RAG。',
  deep:`
  <div class="dh">🏷 あだ名</div>
  <div class="nick"><b>Bedrock</b>＝何でも屋の生成AI受付。学習済みの賢いモデルをすぐ呼べる。</div>
  <div class="nick"><b>RAG</b>＝回答前に社内文書を調べてカンペ（関連箇所）を渡す仕組み。根拠つきで答えるので作り話が減る。</div>
  <div class="nick"><b>SageMaker</b>＝モデルを一から作る工房（専門家・データが要る）。</div>
  <div class="dh">💡 なぜこれが正解か</div>
  「専門家なし・自社文書が根拠・自然文・作り話を避ける」＝Bedrock＋RAG。SageMakerは工房なので「専門家なし」と逆、Comprehendは生成しない。
  <div class="dh">⚠️ つまずきやすい言葉</div>
  生成AIで「自社の情報に基づいて答えさせる」＝Bedrock＋RAG（Knowledge Bases）。分析だけならComprehend、自前モデルが要る時だけSageMaker。`
},
{
  id:52, cat:"疎結合",
  scenario:"ある企業は、アプリケーションにおいて、ユーザーの操作を契機にレポート生成という重い処理を非同期で実行しています。この処理は実行される順序に意味があり、同じ操作が二重に登録されると、レポートが二重に作成されてしまいます。同社は、メッセージの処理順序を保証し、かつ重複した登録を排除する必要があります。スループットは中規模であり、極端な高スループットは必要ありません。",
  ask:'これらの要件を満たすソリューションはどれですか。',
  options:[
    "SQS標準キューを使い、コンシューマ側で順序の並べ替えと重複チェックのロジックを実装して対応する。",
    "SQS FIFOキューを使い、メッセージグループIDで順序を保証し、重複排除IDで重複した登録を自動的に排除する。",
    "SNSトピックにパブリッシュして複数のサブスクライバに同報し、各自で順序と重複を判断させる。",
    "Kinesis Data Streamsに流し、シャード内の順序を使って処理し、重複はコンシューマ側で除外する。"
  ],
  answer:1,
  keypoint:'「処理順序を保証」「重複登録を排除」「スループットは中規模（極端な高スループット不要）」。4つともメッセージングだが、<b>順序保証＋重複排除を標準機能で持つ</b>のはどれか。',
  explain:'B＝SQS FIFOキューはメッセージグループIDで順序を保証し、重複排除IDで重複メッセージを自動排除する。順序と重複排除を自前実装せず標準機能で得られる。中規模スループットの本ケースに最適。',
  elim:'A=SQS標準は順序保証なし＋重複の可能性があり、並べ替え・重複チェックを全部自前実装することになる。C=SNSは同報で順序・重複排除の保証はしない。D=Kinesisはシャード内順序はあるが重複排除は自前で、極端な高スループット向けでオーバースペック。標準機能で順序＋重複排除はFIFO。',
  confusion:'<b>SQS FIFO</b>＝順序保証＋重複排除（標準機能）。<b>SQS標準</b>＝順序保証なし・重複ありうる（自前で対処）。<b>Kinesis</b>＝高スループットストリーム（重複排除は自前）。順序＋重複排除が要件ならFIFO。',
  terms:[
    {t:"メッセージグループID", d:"FIFOキューで、同じグループIDのメッセージは送信順に処理される（順序保証の単位）。"},
    {t:"重複排除ID", d:"FIFOキューで、一定時間内に同じ重複排除IDのメッセージが来たら2通目以降を自動で捨てる（重複排除）。"}
  ],
  deep:`
  <div class="dh">🏷 たとえ</div>
  <div class="nick"><b>SQS FIFO</b>＝整理券方式の窓口。番号順（順序保証）に呼び、同じ整理券が二重に出ても1回しか受け付けない（重複排除）。仕組みが最初から備わっている。</div>
  <div class="nick"><b>SQS標準</b>＝順番も重複もこちらで管理する素のキュー（自前実装が増える）。</div>
  <div class="dh">💡 なぜこれが正解か</div>
  「順序を保証＋重複を排除＋中規模スループット」＝標準機能で両方を持つFIFO。標準キューは自前実装、Kinesisは高スループット向けで大げさ。
  <div class="dh">⚠️ つまずきやすい言葉</div>
  「順序」「重複排除」が出たらFIFO。ただしFIFOはスループット上限があるので、<b>極端な高スループット</b>が要件ならKinesisを検討、と規模で切り分ける。`
},
{
  id:53, cat:"コスト最適化",
  scenario:"ある企業は、多数の Amazon EC2 インスタンスを運用しています。各インスタンスの CPU およびメモリの使用率を確認したところ、同社は、その多くが割り当てに対して常に低い使用率であり、過剰なスペック (オーバープロビジョニング) になっている疑いがあることを確認しました。同社は、実際の使用状況に基づいて、適切なインスタンスタイプ (より小さい、または適切なタイプ) への変更の推奨を受け取りたいと考えています。同社は、データに基づいて EC2 のサイズを適正化し、コストを削減する必要があります。",
  ask:'これらの要件を満たすソリューションはどれですか。',
  options:[
    "すべてのEC2を実使用に関わらず一律で1段階小さいインスタンスタイプに変更してコストを下げ、性能不足が出たら個別に戻す方式にする。",
    "AWS Compute Optimizerを有効化し、実際の使用率メトリクスに基づいて各EC2に最適なインスタンスタイプを推奨させ、それに従って適正化する。",
    "Savings Plansを購入して現在のインスタンス使用量をそのまま長期コミットし、割引でコストを下げて、サイズの適正化は行わずに運用する。",
    "Auto Scalingを設定して負荷に応じて台数を増減させ、アイドルのインスタンスを減らすことで、個々のサイズはそのままにコストを下げる。"
  ],
  answer:1,
  keypoint:'「オーバープロビジョニングの疑い」「実使用に基づいて適切なタイプを推奨」「データでサイズ適正化」。4つともコスト削減だが、<b>実メトリクスからライトサイジングを推奨</b>するのはどれか。',
  explain:'B＝Compute Optimizerは実際のCPU/メモリ等のメトリクスを分析し、各EC2に最適なインスタンスタイプを推奨する。データに基づくライトサイジングの専用サービスで、過剰スペックを的確に見直せる。',
  elim:'A=一律1段階小さくは実使用を無視しており、性能不足やまだ過剰が残るリスク（データに基づかない）。C=Savings Plansは割引だが、過剰スペックのままコミットすると無駄を固定してしまう（先に適正化すべき）。D=Auto Scalingは台数の増減で、個々のインスタンスのサイズ適正化ではない。実使用ベースの適正化はCompute Optimizer。',
  confusion:'<b>Compute Optimizer</b>＝実メトリクスから最適なインスタンスタイプを推奨（ライトサイジング）。<b>Savings Plans</b>＝割引（適正化の後にやる）。<b>Auto Scaling</b>＝台数の増減（サイズではない）。過剰スペックの見直し＝Compute Optimizer。',
  deep:`
  <div class="dh">🏷 たとえ</div>
  <div class="nick"><b>Compute Optimizer</b>＝健康診断の結果（実使用率）を見て「あなたには1サイズ小さい服が合う」と具体的に勧めてくれる係。データに基づくので外さない。</div>
  <div class="nick"><b>一律で小さく</b>＝全員に同じサイズの服を配るようなもの。合わない人が出る。</div>
  <div class="dh">💡 なぜこれが正解か</div>
  「実使用に基づいて適切なタイプを推奨」＝Compute Optimizerそのもの。一律変更はデータ無視、Savings Plansは過剰スペックを固定するので適正化が先。
  <div class="dh">⚠️ つまずきやすい言葉</div>
  「実使用率に基づくサイズ適正化（ライトサイジング）」＝Compute Optimizer。割引コミット（Savings Plans）は<b>適正化してから</b>が鉄則（無駄を固定しない）。`
},
{
  id:54, cat:"高性能",
  scenario:"あるEコマースサイトが、ショッピングカートとログインセッションの情報をRDSに保存している。アクセスが増え、カートやセッションの読み書きが頻繁に発生してRDSの負荷が高く、応答が遅くなっている。セッション情報は一時的なデータで、超低遅延での読み書きが求められる。RDSからセッション/カートのアクセスを切り離して高速化したい。",
  ask:'これらの要件を満たすソリューションはどれですか。',
  options:[
    "RDSをスケールアップしてセッションの読み書きにも耐えられるよう、より上位のインスタンスクラスに変更し、一時データもDBに置いたまま性能を底上げする。",
    "RDSにリードレプリカを追加して、セッションやカートの読み取りをレプリカ側に分散させてプライマリの負荷を下げ、書き込みはプライマリで受ける構成にする。",
    "EC2のローカルディスク（インスタンスストア）にセッションを保存し、ディスクI/Oの速さで読み書きを高速化して、複数台での共有はアプリ側で吸収する。",
    "Amazon ElastiCache（Redis）にセッション/カート情報を保存し、インメモリで超低遅延の読み書きを行ってRDSの負荷を切り離す。"
  ],
  answer:3,
  keypoint:'「一時的なセッション/カート」「超低遅延の読み書き」「RDSから切り離す」。4つとも性能の手だが、<b>インメモリで超低遅延・セッション保存に最適</b>なのはどれか。',
  explain:'D＝ElastiCache（Redis）はインメモリで超低遅延の読み書きができ、一時的なセッション/カートの保存に最適。RDSからこれらのアクセスを切り離し、DB負荷も下げられる。セッションストアの定番。',
  elim:'A=スケールアップは一時しのぎで超低遅延のインメモリには及ばず、一時データをRDSに置く設計のまま。B=リードレプリカは読み取り分散だが書き込み頻繁なセッションには不向き＋超低遅延ではない。C=インスタンスストアはインスタンス終了で消え、複数台で共有できずセッションストアに不適。インメモリのElastiCacheが最適。',
  confusion:'<b>ElastiCache（Redis）</b>＝インメモリの超低遅延ストア（セッション/カート/キャッシュの定番）。<b>リードレプリカ</b>＝読み取り分散（書き込み頻繁な一時データには不向き）。一時的・超低遅延・セッション＝ElastiCache。',
  deep:`
  <div class="dh">🏷 たとえ</div>
  <div class="nick"><b>ElastiCache（Redis）</b>＝手元のメモ帳（インメモリ）。出し入れが一瞬。買い物カゴやログイン状態のような「今だけ・速さ命」のデータ置き場に最適。</div>
  <div class="nick"><b>RDS</b>＝きちんとした台帳（ディスク）。永続化には良いが、頻繁な一時データの出し入れには遅い。</div>
  <div class="dh">💡 なぜこれが正解か</div>
  「一時的・超低遅延・RDSから切り離す」＝インメモリのElastiCache。スケールアップやレプリカはRDSに置いたままで超低遅延に届かない。
  <div class="dh">⚠️ つまずきやすい言葉</div>
  セッション/カート/ランキングのような「一時的で超高速」なデータはElastiCache。永続的な業務データはRDS、と<b>永続性と速度要件</b>で切り分ける。`
},
{
  id:55, cat:"可用性",
  scenario:"ある企業が、ALB＋Auto ScalingのEC2でWebアプリを運用している。毎週月曜の朝9時にアクセスが急増することが過去のデータから明確に分かっている。現状の動的スケーリング（CPU閾値での増減）では、急増を検知してからインスタンスが立ち上がるまでに数分かかり、その間ユーザーが遅延を経験している。予測できる急増に対し、立ち上がりの遅れをなくして事前に備えたい。",
  ask:'これらの要件を満たすソリューションはどれですか。',
  options:[
    "Auto Scalingのスケジュールスケーリングで、毎週月曜9時の前にあらかじめ必要なインスタンス数まで増やしておき、急増の立ち上がりに間に合わせる。",
    "Auto Scalingの動的スケーリング（ターゲット追跡）のCPU閾値をさらに低めに調整して、負荷が上がり始めたらより早めにスケールアウトが始まるようにする。",
    "インスタンスを想定ピークの最大数で常時固定起動しておき、いつ急増が来ても即対応できる状態を維持して、立ち上がりの遅れをなくす。",
    "ALBのヘルスチェックの間隔を短く設定して、異常の検知と新しいインスタンスの投入をできるだけ早め、急増にも追従できるようにする。"
  ],
  answer:0,
  keypoint:'「急増の時刻が予測できる」「立ち上がりの遅れをなくす」「事前に備える」。4つともスケーリング関連だが、<b>予測できる時刻に事前増設</b>するのはどれか。',
  explain:'A＝スケジュールスケーリングは、決まった時刻（月曜9時前）にあらかじめインスタンスを増やす。立ち上がりの遅れを先回りで解消でき、時刻が予測できる急増に最適。',
  elim:'B=動的スケーリングの閾値を下げても「検知してから」立ち上がる遅れは残る（事前ではない）。C=常時最大数は急増には耐えるが平常時のコストが無駄（事前に備える最適解ではない）。D=ヘルスチェック間隔は異常検知の話で、急増への事前増設ではない。時刻が読める急増はスケジュールスケーリング。',
  confusion:'Auto Scaling：<b>スケジュールスケーリング</b>＝時刻が予測できる増減に事前対応。<b>動的スケーリング（ターゲット追跡）</b>＝予測できない負荷に追従（検知後）。<b>予測スケーリング</b>＝過去パターンから自動予測。時刻が分かっている定時の急増＝スケジュール。',
  deep:`
  <div class="dh">🏷 たとえ</div>
  <div class="nick"><b>スケジュールスケーリング</b>＝混む時間が分かっているお店が、開店前にバイトを増やしておく。客が来てから呼ぶより速い。</div>
  <div class="nick"><b>動的スケーリング</b>＝混んできたのを見てからバイトを呼ぶ。来てから動くので数分のタイムラグが出る。</div>
  <div class="dh">💡 なぜこれが正解か</div>
  「毎週月曜9時と分かっている」＝時刻が予測できる急増。事前に増やすスケジュールスケーリングが最適。閾値下げは結局「検知後」、常時最大は無駄。
  <div class="dh">⚠️ つまずきやすい言葉</div>
  「時刻が予測できる」＝スケジュール、「予測できない変動に追従」＝動的（ターゲット追跡）、「過去パターンから自動予測」＝予測スケーリング。<b>予測できるかどうか</b>で選ぶ。`
},
{
  id:56, cat:"データベース",
  scenario:"ある企業が、リレーショナルDBのバックエンドにAurораのMySQL互換を使っている。読み取りトラフィックが時間帯で大きく変動し、ピーク時はリードレプリカを手動で増やし、閑散時は減らす運用をしている。手動のレプリカ増減が運用負担になっており、読み取り負荷に応じてレプリカ数を自動で増減させたい。",
  ask:'これらの要件を満たすソリューションはどれですか。',
  options:[
    "Aurora Auto Scaling（レプリカAuto Scaling）を設定し、平均CPU使用率や接続数などのメトリクスに応じてリードレプリカ数を自動で増減させる。",
    "Lambdaを定期実行してCPUや接続数のメトリクスを確認し、APIでリードレプリカを増減させるスクリプトを自前で組んで運用する。",
    "Aurora Serverless v2に移行し、単一インスタンスの容量(ACU)自動スケールに読み取り負荷を任せて、レプリカ数の増減はしない構成にする。",
    "リードレプリカを想定する最大数まで常時起動しておき、閑散時もその台数を保ったまま、ピークにいつでも対応できるようにする。"
  ],
  answer:0,
  keypoint:'「Aurora」「読み取り負荷に応じてレプリカ数を自動増減」「手動運用をなくす」。4つとも読み取り対応の手だが、<b>レプリカ数を標準機能で自動増減</b>するのはどれか。',
  explain:'A＝Aurora Auto Scaling（レプリカAuto Scaling）は、CPU使用率や接続数などのメトリクスに基づいてリードレプリカ数を自動で増減させる標準機能。手動増減の運用負担をなくせる。',
  elim:'B=Lambdaで自前スクリプトは実現できるが標準機能があるのに自作するのは過剰運用。C=Serverless v2は単一インスタンスの容量スケールで、リードレプリカ「数」の増減とは別（読み取りを複数に分散する話ではない）。D=最大数常時起動は閑散時のコストが無駄。標準のレプリカAuto ScalingがA。',
  confusion:'<b>Aurora レプリカAuto Scaling</b>＝メトリクスに応じてリードレプリカ「数」を自動増減。<b>Serverless v2</b>＝インスタンスの「容量（ACU）」を自動伸縮。読み取りを複数台に分散しつつ自動増減＝レプリカAuto Scaling。',
  deep:`
  <div class="dh">🏷 たとえ</div>
  <div class="nick"><b>レプリカAuto Scaling</b>＝読み取り担当のコピー台帳（レプリカ）を、混み具合を見て自動で増やしたり減らしたりする店長。手動でやっていた増減を任せられる。</div>
  <div class="dh">💡 なぜこれが正解か</div>
  「レプリカの数を負荷に応じて自動増減」＝標準のレプリカAuto Scaling。Lambda自作は標準機能があるのに過剰、Serverless v2は容量の話でレプリカ数ではない。
  <div class="dh">⚠️ つまずきやすい言葉</div>
  「レプリカの数を自動で増減」＝レプリカAuto Scaling、「1台の容量を自動で伸縮」＝Serverless v2。<b>台数か容量か</b>で切り分ける。`
},
{
  id:57, cat:"セキュリティ",
  scenario:"ある企業が、大企業の社内ですでにMicrosoft Active Directory（AD）を運用しており、社員はADのアカウントで業務システムにログインしている。これらの社員が、複数のAWSアカウントにも既存のAD認証情報でシングルサインオン（SSO）でアクセスできるようにしたい。AWS用に新しくユーザーを作り直す運用は避けたい。",
  ask:'これらの要件を満たすソリューションはどれですか。',
  options:[
    "社員ごとにIAMユーザーを各AWSアカウントに作成し、ADのパスワードと同じものを手動で設定してログインさせ、入退社のたびに全アカウントで作り直す運用にする。",
    "AWS IAM Identity Center（旧AWS SSO）を既存のActive Directoryと連携し、社員が既存のAD認証情報で複数アカウントにSSOアクセスできるようにする。",
    "各社員にIAMアクセスキーを発行し、AWS CLIや各種ツールから各アカウントへアクセスさせ、その長期キーの配布と棚卸しを継続的に管理する。",
    "Amazon Cognitoのユーザープールに社員を登録し、アプリ経由で発行したトークンを使って各AWSアカウントへアクセスさせる構成にする。"
  ],
  answer:1,
  keypoint:'「既存ADの社員」「作り直さない」「複数AWSアカウントにSSO」。4つとも認証だが、<b>既存ADと連携して社員を複数アカウントにSSO</b>させるのはどれか。',
  explain:'B＝IAM Identity Center（旧AWS SSO）は既存のActive Directoryと連携でき、社員は使い慣れたAD認証情報で複数のAWSアカウントにシングルサインオンできる。ユーザーの作り直しが不要。',
  elim:'A=各アカウントにIAMユーザーを作り直すのは「作り直さない」に反し運用も破綻。C=アクセスキー発行はSSOでなく長期認証情報の配布で管理負担大。D=Cognitoはアプリのエンドユーザー（toC）向けで、社員のAWSアクセスSSOではない。既存ADの社員SSOはIAM Identity Center。',
  confusion:'<b>IAM Identity Center（旧AWS SSO）</b>＝既存AD連携で社員を複数AWSアカウントにSSO（社員向け）。<b>Cognito</b>＝アプリ利用者（toC）。<b>IAMユーザー</b>＝個別作成（作り直しになる）。社員＋既存AD＋SSO＝Identity Center。',
  deep:`
  <div class="dh">🏷 たとえ</div>
  <div class="nick"><b>IAM Identity Center</b>＝社員証（既存AD）を見せれば複数の建物（AWSアカウント）に1枚で入れる共通ゲート。新しい社員証を作り直す必要がない。</div>
  <div class="nick"><b>Cognito</b>＝お店のお客さん用の会員証（toC）。社員のSSOには使わない。</div>
  <div class="dh">💡 なぜこれが正解か</div>
  「既存ADの社員・作り直さない・複数アカウントSSO」＝IAM Identity Center。IAMユーザー作成は作り直しで破綻、Cognitoはお客さん向け。
  <div class="dh">⚠️ つまずきやすい言葉</div>
  「社員のAWSアクセスSSO・既存AD連携」＝IAM Identity Center、「アプリのお客さんのログイン」＝Cognito。<b>相手が社員かお客さんか</b>で切り分ける。`
},
{
  id:58, cat:"ストレージ",
  scenario:"ある企業が、オンプレミスのデータセンターから約80TBの観測データをAWSのS3へ一度だけ移行したい。データセンターのインターネット回線は細く、この量をネットワーク経由で送ると数週間〜数か月かかってしまう。物理的な手段も含め、現実的な時間で大容量データをAWSへ移行したい。",
  ask:'これらの要件を満たすソリューションはどれですか。',
  options:[
    "AWS Snowball Edgeを取り寄せてオンプレでデータをコピーし、デバイスをAWSに返送してS3へ取り込む（物理輸送によるオフライン移行）。",
    "AWS DataSyncでインターネット回線経由でS3へ転送し、並列化やスケジュールでスループットを上げて、細い回線のまま80TBを送り切る。",
    "S3 Transfer Accelerationを有効化し、最寄りのエッジロケーション経由で80TBをアップロードして、インターネット回線のまま転送を高速化する。",
    "AWS Storage Gatewayをオンプレに置き、ファイルをS3へ徐々にキャッシュ同期させながら、ハイブリッド運用のなかで80TBを移行していく。"
  ],
  answer:0,
  keypoint:'「80TB」「回線が細い」「ネット経由だと数週間〜数か月」「一度だけ移行」。4つとも移行手段だが、<b>細い回線をバイパスして物理輸送で現実的に運ぶ</b>のはどれか。',
  explain:'A＝Snowball Edgeは物理デバイスにデータをコピーして返送するオフライン移行で、細い回線に依存せず大容量を現実的な時間で運べる。回線がボトルネックの大容量一括移行の定番。',
  elim:'B=DataSyncは回線経由なので細い回線では結局数週間〜数か月かかる（ボトルネックが回線）。C=Transfer Accelerationも回線・インターネット経由で、80TBを細い回線で送る根本問題は解決しない。D=Storage Gatewayはハイブリッド運用向けで、一度きりの大容量移行を高速化する手段ではない。物理輸送のSnowballがA。',
  confusion:'<b>Snowball Edge</b>＝物理デバイスで大容量をオフライン移送（回線が細い/大容量一括）。<b>DataSync/Transfer Acceleration</b>＝回線経由（回線が太い時に有効、細いとボトルネック）。回線がネックの大容量＝Snowball。',
  deep:`
  <div class="dh">🏷 たとえ</div>
  <div class="nick"><b>Snowball Edge</b>＝大量の荷物を細い道（回線）でなく、トラック（物理デバイス）に積んで運ぶ。道が細くても関係ない。</div>
  <div class="nick"><b>DataSync</b>＝その細い道を通って荷物を送る。道が細ければ何をしても遅い。</div>
  <div class="dh">💡 なぜこれが正解か</div>
  「回線が細い＋80TB＋数週間かかる」＝回線がボトルネック。回線をバイパスして物理で運ぶSnowballが現実解。DataSyncやTransfer Accelerationは回線依存で根本解決にならない。
  <div class="dh">⚠️ つまずきやすい言葉</div>
  「回線が細い・大容量・一度きり」＝Snowball（物理）。「回線は十分・継続的に同期/転送」＝DataSync。<b>回線がボトルネックかどうか</b>で切り分ける。`
},
{
  id:59, cat:"サーバーレス",
  scenario:"ある企業が、バッチ処理基盤を設計している。処理は『コンテナ化された既存アプリ』で、1回あたり実行時間が長く（30分〜数時間かかるものもある）、大量のジョブをキューに溜めて順次・並列に実行したい。ジョブの数は時間帯で大きく変動する。長時間のコンテナバッチを、ジョブのスケジューリングまで含めてマネージドに実行したい。",
  ask:'これらの要件を満たすソリューションはどれですか。',
  options:[
    "キューから取り出した各ジョブをLambdaで実行し、1回が15分の制限に収まるように分割して順次こなし、大量のジョブをさばく。",
    "EC2を常時起動してcronでジョブを順番に実行し、混み具合に応じて起動台数を手動で調整しながら、その基盤を自前で運用し続ける。",
    "AWS Batchを使い、ジョブキューとコンピューティング環境（FargateやEC2/Spot）でコンテナバッチのスケジューリングと並列実行をマネージドに行う。",
    "Step Functionsで各ジョブをステートマシンのステップとして定義し、順番に1つずつ実行していく方式にして、大量ジョブのキューイングも組み込む。"
  ],
  answer:2,
  keypoint:'「コンテナバッチ」「1回30分〜数時間と長い」「大量ジョブをキューに溜めて順次・並列」「スケジューリング込みでマネージド」。4つとも実行できるが、<b>長時間コンテナバッチのジョブ管理に特化</b>するのはどれか。',
  explain:'C＝AWS Batchはジョブキューとコンピューティング環境を持ち、コンテナ化されたバッチのスケジューリング・並列実行・リソース確保をマネージドに行う。長時間ジョブ（Lambdaの15分上限を超える）に最適。',
  elim:'A=Lambdaは最大15分の実行時間制限があり「30分〜数時間」の長時間バッチに使えない。B=EC2常時起動＋cron＋手動調整は自前運用で変動への自動追従もない。D=Step Functionsはワークフローのオーケストレーションで、大量ジョブのキューイング・並列バッチ実行の基盤ではない。長時間コンテナバッチはAWS Batch。',
  confusion:'<b>AWS Batch</b>＝長時間・大量のコンテナバッチをジョブキュー＋計算環境でマネージド実行。<b>Lambda</b>＝最大15分の短時間処理（長時間バッチ不可）。<b>Step Functions</b>＝ワークフローの順序制御。長時間コンテナバッチ＝AWS Batch。',
  deep:`
  <div class="dh">🏷 たとえ</div>
  <div class="nick"><b>AWS Batch</b>＝工場の生産管理係。大量の注文（ジョブ）を行列に並べ、空いた機械（FargateやSpot）に割り振って長時間の加工も並列でこなす。</div>
  <div class="nick"><b>Lambda</b>＝短時間で帰る出張スタッフ（最大15分）。数時間かかる加工は任せられない。</div>
  <div class="dh">💡 なぜこれが正解か</div>
  「長時間（30分〜数時間）」がLambda（A・15分上限）を即脱落させる。大量ジョブのキューイング＋並列実行をマネージドでやるのはAWS Batch。
  <div class="dh">⚠️ つまずきやすい言葉</div>
  「短いイベント処理」＝Lambda、「長時間・大量のコンテナバッチ」＝AWS Batch、「順序・分岐のワークフロー」＝Step Functions。<b>処理時間と性質</b>で切り分ける。`
},
{
  id:60, cat:"高性能",
  scenario:"あるグローバル企業のWebアプリが、世界中のユーザーに動的コンテンツとAPIレスポンスを返している。多くは都度生成される動的な内容だが、HTTPSで配信され、遠隔地のユーザーほどレイテンシが大きい。TLS終端やコネクションの最適化、AWSのグローバルネットワークを活かして、動的コンテンツの配信も含めてグローバルなレイテンシを下げたい。",
  ask:'これらの要件を満たすソリューションはどれですか。',
  options:[
    "Route 53のレイテンシーベースルーティングで各ユーザーを最寄りリージョンへ振り分けるだけにとどめ、エッジでのTLS終端やAWS網経由の経路最適化までは行わない。",
    "Amazon CloudFrontを使い、動的コンテンツもエッジ経由（エッジでのTLS終端＋AWSグローバルネットワーク経由のオリジン接続）で配信してグローバルレイテンシを下げる。",
    "各リージョンにEC2を立て、ユーザーには最寄りリージョンのIPアドレスを手動で案内してアクセスさせ、配信の最適化やHTTPSも各自で手当てする。",
    "AWS Global Acceleratorで静的な固定IPを提供するだけにとどめ、HTTPの動的コンテンツのキャッシュやエッジでのTLS終端といった配信最適化は特に行わない。"
  ],
  answer:1,
  keypoint:'「HTTPSのWeb/API」「動的コンテンツ中心」「グローバルに低遅延」。4つとも配信/振り分けだが、<b>動的コンテンツもエッジ経由で最適化配信</b>するのはどれか。',
  explain:'B＝CloudFrontは静的だけでなく動的コンテンツもエッジ経由で配信でき、エッジでのTLS終端やAWSグローバルネットワーク経由のオリジン接続でレイテンシを下げる。HTTP/SのWeb・API配信の最適化に向く。',
  elim:'A=Route 53のレイテンシールーティングは最寄りリージョンへ振り分けるだけで、TLS終端や経路最適化はしない（不十分）。C=手動IP案内は運用が破綻し最適化にならない。D=Global AcceleratorはL4の非HTTP・固定IP向けで、HTTPの動的コンテンツ配信最適化（キャッシュ/TLS終端）はCloudFrontの領分。HTTP/Sの動的配信はCloudFront。',
  confusion:'<b>CloudFront</b>＝HTTP/Sの静的＋動的コンテンツをエッジ最適化配信（TLS終端・経路最適化）。<b>Global Accelerator</b>＝非HTTP（TCP/UDP）・固定IPの経路最適化（ゲーム等）。HTTPのWeb/API＝CloudFront。',
  deep:`
  <div class="dh">🏷 たとえ</div>
  <div class="nick"><b>CloudFront</b>＝世界中の支店（エッジ）。動的な内容も支店でTLSを受けてAWS専用網で本店につなぐので、遠い人でも速い。</div>
  <div class="nick"><b>Global Accelerator</b>＝非HTTP（ゲーム等）や固定IPが要る時の高速道路入口。HTTPのWeb配信最適化（キャッシュ/TLS終端）はCloudFrontの担当。</div>
  <div class="dh">💡 なぜこれが正解か</div>
  「HTTPSのWeb/API・動的・グローバル低遅延」＝CloudFront（動的コンテンツもエッジ最適化）。Route53は振り分けだけ、Global AcceleratorはHTTP配信最適化が主目的でない。
  <div class="dh">⚠️ つまずきやすい言葉</div>
  HTTP/SのWeb・API（静的/動的）＝CloudFront、非HTTP・固定IP（ゲーム/独自プロトコル）＝Global Accelerator。<b>HTTPかどうか</b>で切り分ける。`
},
{
  id:61, cat:"配信/CDN",
  scenario:"ある動画配信サービスが、ライセンス契約の都合で、特定の国・地域のユーザーにだけコンテンツを配信し、それ以外の国からのアクセスは拒否する必要がある。CloudFrontで配信しており、視聴可能な国を限定したい。個々のユーザー認証ではなく、アクセス元の国による制限をしたい。",
  ask:'これらの要件を満たすソリューションはどれですか。',
  options:[
    "CloudFrontのGeo Restriction（地理的制限）で許可する国のリストを設定し、それ以外の国からのアクセスを拒否する。",
    "CloudFrontの署名付きURLを発行し、許可した国のユーザーにだけそのURLを配ることで、地域単位のアクセス制限を実現する。",
    "WAFでアクセス元のIPアドレスを国ごとに手動でリスト化し、許可した国のIP以外を拒否することで、地域単位の配信制限を実現する。",
    "Route 53のジオロケーションルーティングで、許可した国以外からのDNSクエリには応答しないようにして、地域単位のアクセス制限とする。"
  ],
  answer:0,
  keypoint:'「特定の国・地域だけに配信」「国によるアクセス制限」「個人認証ではない」。4つとも制限の手だが、<b>CloudFrontで国単位の配信制限</b>を標準機能で行うのはどれか。',
  explain:'A＝CloudFrontのGeo Restrictionは、視聴を許可する国のリストを設定し、それ以外の国からのアクセスを拒否する標準機能。ライセンス都合の国単位配信制限にそのまま使える。',
  elim:'B=署名付きURLは個人・期限の制御で国単位の制限ではない（URLが国境を越えて共有されうる）。C=WAFで国別IPを手動リスト化は膨大で変動し非現実的（WAFの地理マッチもあるがCloudFront標準のGeo Restrictionが直接的）。D=Route 53ジオロケーションはDNS応答の振り分けで、確実なアクセス拒否（制限）には向かない。国単位の配信制限はGeo Restriction。',
  confusion:'<b>CloudFront Geo Restriction</b>＝国単位で配信を許可/拒否（ライセンス都合の地域制限）。<b>署名付きURL</b>＝個人＋期限の制御。<b>Geo（国）と個人（署名URL）</b>は制御の単位が違う。',
  deep:`
  <div class="dh">🏷 たとえ</div>
  <div class="nick"><b>Geo Restriction</b>＝「この映画は日本国内のみ上映可」のような国単位の上映制限。許可国リストを設定すれば他国は弾かれる。</div>
  <div class="nick"><b>署名付きURL</b>＝時間制限つきの入場券（個人向け）。国の制限ではない。</div>
  <div class="dh">💡 なぜこれが正解か</div>
  「特定の国だけ・国によるアクセス制限」＝CloudFrontのGeo Restriction。署名付きURLは個人/期限、WAF手動IPは非現実的。
  <div class="dh">⚠️ つまずきやすい言葉</div>
  「国・地域で制限」＝Geo Restriction、「特定ユーザーに期限付きで」＝署名付きURL。<b>制限の単位が国か個人か</b>で切り分ける。`
},
{
  id:62, cat:"疎結合",
  scenario:"ある企業が、フロントのWebアプリ（Lambda）とバックエンドの処理（別のLambda）を連携させている。現在はフロントがバックエンドを同期的に直接呼び出しており、バックエンドの処理が重いときにフロントが待たされてタイムアウトしたり、バックエンドの一時的な障害がフロントに直接波及したりする。両者を切り離し、バックエンドが一時的に落ちてもリクエストを失わず後で処理できるようにしたい。",
  ask:'これらの要件を満たすソリューションはどれですか。',
  options:[
    "フロントとバックエンドの間にSQSキューを挟み、フロントはキューに入れるだけで応答を返し、バックエンドが自分のペースで取り出して処理する（障害時はキューに保持）。",
    "フロントのLambdaのタイムアウト時間を最大まで延ばし、同期呼び出しのままバックエンドの処理完了を待てるようにして、重い処理にも耐える。",
    "バックエンドのLambdaの同時実行数を引き上げて、重い処理が殺到しても待たせずに捌けるようにし、フロントからの同期呼び出しを成立させる。",
    "フロントからバックエンドをリトライ付きで同期呼び出しし、失敗したら一定回数まで再試行することで、障害時の取りこぼしを減らす。"
  ],
  answer:0,
  keypoint:'「同期直結で待たされる・障害が波及」「両者を切り離す」「障害時もリクエストを失わず後で処理」。4つとも対処だが、<b>間にバッファを挟んで疎結合化</b>するのはどれか。',
  explain:'A＝間にSQSキューを挟むと、フロントはキューに入れて即応答を返し、バックエンドは自分のペースで処理できる。バックエンドが一時的に落ちてもメッセージはキューに保持され、復旧後に処理できる（リクエストを失わない）。疎結合化の定石。',
  elim:'B=タイムアウト延長は同期のままで根本的に疎結合化していない（重い処理で結局待つ・障害も波及）。C=同時実行増は処理能力の話で、障害時のリクエスト保持にならない。D=同期リトライは結合したままで、バックエンド障害が続けばフロントも失敗する。バッファで切り離すのはSQS。',
  confusion:'<b>SQSを挟む</b>＝同期直結を非同期・疎結合化し、障害時もキューに保持（リクエストを失わない）。<b>タイムアウト延長/リトライ</b>＝同期のままで根本解決にならない。コンポーネントを切り離す＝間にキュー。',
  deep:`
  <div class="dh">🏷 たとえ</div>
  <div class="nick"><b>SQSを挟む</b>＝注文を受付（フロント）が伝票スタンド（キュー）に挿すだけ。厨房（バックエンド）が忙しくても受付は待たず次の客へ。厨房が一時的に止まっても伝票は残るので後で作れる。</div>
  <div class="nick"><b>同期直結</b>＝受付が厨房の料理完成まで客の前で待つ。厨房が詰まれば受付も止まる。</div>
  <div class="dh">💡 なぜこれが正解か</div>
  「待たされる・障害が波及・リクエストを失いたくない」＝間にキュー（SQS）を挟んで疎結合化。タイムアウト延長やリトライは同期のままで根本解決にならない。
  <div class="dh">⚠️ つまずきやすい言葉</div>
  「コンポーネントを切り離す・障害を波及させない・リクエストを失わない」＝間にSQS。同期のチューニング（タイムアウト/リトライ）は結合したままなので疎結合化にならない。`
},
{
  id:63, cat:"セキュリティ",
  scenario:"ある企業が、多数のEC2インスタンスとECRのコンテナイメージを運用している。セキュリティチームから、これらのEC2やコンテナイメージに既知の脆弱性（古いパッケージ、CVE）が含まれていないかを継続的に自動スキャンし、リスクの高いものから対応したいと求められている。自前でスキャンツールを各インスタンスに入れて回る運用は避けたい。",
  ask:'これらの要件を満たすソリューションはどれですか。',
  options:[
    "各EC2に脆弱性スキャンツールを手動でインストールし、定期実行するcronを台ごとに設定して結果を集約し、CVEの把握を自前の運用で続ける。",
    "Amazon Inspectorを有効化し、EC2とECRのコンテナイメージを継続的に自動スキャンして既知の脆弱性（CVE）を検出し、リスクスコア順に提示する。",
    "Amazon GuardDutyを有効化して、脆弱性を持つインスタンスへの不審な通信やAPI呼び出しを検知し、その兆候から脆弱性のリスクを把握する。",
    "AWS Configのルールで、パッチが適用されていないインスタンスをコンプライアンス違反として検出し、それを脆弱性の有無の指標として扱う。"
  ],
  answer:1,
  keypoint:'「EC2とコンテナイメージ」「既知の脆弱性（CVE）」「継続的に自動スキャン」「自前ツール運用を避ける」。4つともセキュリティだが、<b>脆弱性を自動スキャンする</b>のはどれか。',
  explain:'B＝InspectorはEC2とECRのコンテナイメージを継続的に自動スキャンし、既知の脆弱性（CVE）を検出してリスクスコア順に提示する。エージェントベースで自前ツールの手動運用が不要。脆弱性管理の専用サービス。',
  elim:'A=各台に手動インストール＋cronは「自前運用を避けたい」に反する。C=GuardDutyは脅威・不審通信の検知で、脆弱性（CVE）のスキャンはしない。D=Configはパッチ適用状態の構成チェックはできるが、CVEレベルの継続的な脆弱性スキャン・リスクスコア化はInspectorの領分。脆弱性スキャンはInspector。',
  confusion:'<b>Inspector</b>＝EC2/コンテナの既知の脆弱性（CVE）を継続自動スキャン。<b>GuardDuty</b>＝脅威・不審な挙動の検知。<b>Config</b>＝構成の逸脱。脆弱性（CVE）スキャン＝Inspector。',
  deep:`
  <div class="dh">🏷 あだ名</div>
  <div class="nick"><b>Inspector</b>＝建物の定期点検員。「この窓の鍵は古い（CVE）」「このドアは脆い」と既知の弱点を継続的に見つけ、危険な順に教える。</div>
  <div class="nick"><b>GuardDuty</b>＝不審者を見張る警備員（脆弱性そのものは点検しない）。</div>
  <div class="dh">💡 なぜこれが正解か</div>
  「EC2・コンテナの既知の脆弱性を継続スキャン」＝Inspector。手動ツールは運用が残り、GuardDutyは脅威検知、Configは構成チェックで、CVEの脆弱性スキャンはInspectorの専門。
  <div class="dh">⚠️ つまずきやすい言葉</div>
  「脆弱性・CVE・パッチ未適用のスキャン」＝Inspector、「不正アクセス・侵害の検知」＝GuardDuty。<b>弱点の点検か、攻撃の検知か</b>で切り分ける。`
},
{
  id:64, cat:"配信/CDN",
  scenario:"世界中に利用者がいるWebサイトを運営している。全リクエストでHTTPヘッダーの軽量な書き換え（A/Bテスト用Cookieの付与、末尾スラッシュのURL正規化）を行いたい。処理はごく単純だが秒間数万リクエストあり、ユーザーに近い場所で実行したい。既にCloudFrontでコンテンツを配信している。",
  ask:'これらの要件を満たすソリューションはどれですか。',
  options:[
    "オリジンのALB配下のEC2にヘッダー書き換え処理を実装し、全リクエストをオリジンまで通して処理させ、結果をCloudFrontでキャッシュする。",
    "CloudFrontのLambda@Edge（オリジンリクエスト）で書き換え処理を実行し、Node.jsランタイムで柔軟にロジックを記述してオリジンへ渡す。",
    "API Gatewayのマッピングテンプレートでヘッダーを書き換え、その背後にコンテンツ配信のオリジンを置く構成に組み替える。",
    "CloudFront Functions（ビューワーリクエスト/レスポンス）に軽量なJavaScriptを書き、エッジロケーションでヘッダーとURLを書き換える。"
  ],
  answer:3,
  keypoint:'「軽量なヘッダー・URL書き換え」「秒間数万」「ユーザーに近い場所で低レイテンシ・低コスト」。4つともエッジ/配信に絡むが、<b>最軽量の処理を最安でエッジ実行する</b>のはどれか。',
  explain:'D＝CloudFront Functionsはビューワーリクエスト/レスポンスのタイミングでエッジロケーション自体で動き、ヘッダー操作・URL書き換えといった軽量処理にサブミリ秒・極めて低コストで対応する。まさにこの用途の専用機能。',
  elim:'A=オリジンEC2まで往復するのでエッジ処理にならず低レイテンシ要件に反する。B=Lambda@Edgeはより重い処理（オリジン応答の加工・外部アクセス）向けで、単純なヘッダー操作には起動コスト・料金が割高。C=API Gatewayはエッジ書き換えとは別物で配信経路に挟む構成が不自然。軽量・最安のエッジ処理＝CloudFront Functions。',
  confusion:'<b>CloudFront Functions</b>＝サブミリ秒の軽量処理（ヘッダー/URL書き換え）に最安。<b>Lambda@Edge</b>＝より重い処理・外部アクセスが要る時。<b>軽いか重いか</b>で選ぶ。',
  deep:`
  <div class="dh">🏷 あだ名</div>
  <div class="nick"><b>CloudFront Functions</b>＝各支店（エッジ）の入口に立つ受付の付箋作業。ハンコを押す程度の一瞬の仕事を、本店に送らずその場で片付ける。</div>
  <div class="nick"><b>Lambda@Edge</b>＝同じ支店でももっと手の込んだ事務処理をする係。重いぶん時間も費用もかかる。</div>
  <div class="dh">💡 なぜこれが正解か</div>
  「軽量なヘッダー・URL書き換えをユーザーに近い場所で最安」＝CloudFront Functions。オリジン往復はレイテンシ大、Lambda@Edgeは軽い用途には過剰。
  <div class="dh">⚠️ つまずきやすい言葉</div>
  「軽量・ヘッダー操作・サブミリ秒・最安」＝CloudFront Functions、「重い処理・外部呼び出し・オリジン応答の加工」＝Lambda@Edge。<b>処理の重さ</b>で切り分ける。`
},
{
  id:65, cat:"セキュリティ",
  scenario:"監査部門から「誰が・いつ・どのAWSのAPI操作を行ったか」を全リージョンで記録し、後から改ざんできない形で長期保管せよと求められた。インシデント調査で操作主体を追跡できる必要がある。アプリケーションのログ収集基盤は別に存在している。",
  ask:'これらの要件を満たすソリューションはどれですか。',
  options:[
    "Amazon GuardDutyを有効化し、不審なAPI呼び出しを脅威として検知してアラートを発報し、その検出結果を保管する。",
    "AWS Configを全リージョンで有効化し、リソースの構成変更を記録してコンプライアンス評価に用い、変更履歴を保管する。",
    "CloudWatch Logsにアプリケーションと各サービスのログを集約し、ロググループを長期保持期間で保管する。",
    "AWS CloudTrailで全リージョンの証跡を作成してS3に出力し、バケットにObject Lockを設定して改ざんを防止する。"
  ],
  answer:3,
  keypoint:'「誰がどのAPIを叩いたか」「全リージョン」「改ざん防止で長期保管」。4つともセキュリティ/記録系だが、<b>API操作の監査証跡を残す</b>のはどれか。',
  explain:'D＝CloudTrailはアカウント内のAPI呼び出し（誰が・いつ・何を）をイベントとして全リージョンで記録できる監査の標準サービス。出力先S3にObject Lock（WORM）をかければ改ざん不能の長期保管が成立する。',
  elim:'A=GuardDutyは脅威の「検知」であって全API操作の証跡記録ではない。B=Configは構成変更の記録で、API呼び出し主体の追跡が主目的でない。C=CloudWatch Logsはアプリログ向けで、AWS API操作の監査証跡としては不適。操作の証跡＝CloudTrail。',
  confusion:'<b>CloudTrail</b>＝誰がどのAPIを叩いたか（操作の証跡）。<b>Config</b>＝構成がどう変わったか。<b>GuardDuty</b>＝脅威の検知。<b>CloudWatch Logs</b>＝ログの集約。操作の監査＝CloudTrail。',
  deep:`
  <div class="dh">🏷 あだ名</div>
  <div class="nick"><b>CloudTrail</b>＝建物の入退室記録簿。誰が何時にどの部屋（API）を操作したかを全部書き留める。Object Lockで「ページを破れない記録簿」にする。</div>
  <div class="nick"><b>Config</b>＝部屋の模様替え（構成変更）の記録係で、操作した人を追うのが主目的ではない。</div>
  <div class="dh">💡 なぜこれが正解か</div>
  「API操作を誰がしたか・全リージョン・改ざん防止」＝CloudTrail＋S3 Object Lock。GuardDutyは検知、Configは構成、CloudWatch Logsはアプリログ。
  <div class="dh">⚠️ つまずきやすい言葉</div>
  「誰が・いつ・どのAPI・監査・証跡」＝CloudTrail。「不審な挙動・脅威」＝GuardDuty。<b>記録か検知か</b>で切り分ける。`
},
{
  id:66, cat:"データベース",
  scenario:"モバイルアプリのセッション情報や一時的な認証トークンをDynamoDBに保存している。これらは一定期間（例：24時間）を過ぎると不要になる。期限切れ項目を自動で削除して、ストレージコストと削除のための運用負荷をできるだけ抑えたい。",
  ask:'これらの要件を満たすソリューションはどれですか。',
  options:[
    "各項目に有効期限のUNIXタイムスタンプ属性を持たせ、DynamoDBのTTL機能を有効化して期限切れ項目を自動削除させる。",
    "Lambdaを1時間ごとにEventBridgeで起動し、テーブルをScanして期限切れ項目を抽出しBatchWriteItemで削除する処理を実装する。",
    "DynamoDB Streamsで全項目の変更をLambdaに流し、項目ごとに経過時間を判定して期限が来たら削除する処理を実装する。",
    "Step Functionsで日次ワークフローを組み、テーブルを新規に作り直して有効な項目だけを移し替えて古いテーブルを破棄する。"
  ],
  answer:0,
  keypoint:'「期限切れで不要」「自動削除」「運用負荷とコストを最小」。4つとも技術的に削除はできるが、<b>追加コストも運用もほぼゼロで自動失効させる</b>のはどれか。',
  explain:'A＝DynamoDBのTTLは項目のタイムスタンプ属性を見て期限切れを自動削除する標準機能。追加料金なし・運用コードゼロで、まさにこの用途のために用意されている。',
  elim:'B=定期ScanはScanの読み取りコストとLambdaの運用が発生する。C=Streams＋Lambdaは全変更を処理し続けるコストと実装が重い。D=テーブル作り直しは大掛かりで一時的な可用性影響もある。いずれも動くが運用・コストでTTLに劣る。自動失効＝TTL。',
  terms:[{t:"TTL (Time To Live)",d:"項目に持たせた有効期限のタイムスタンプを過ぎると、DynamoDBが自動で項目を削除する機能。追加料金なし。"}],
  confusion:'<b>DynamoDB TTL</b>＝一時データの自動失効（無料・運用ゼロ）。<b>DynamoDB Streams</b>＝項目変更を他処理に流す。削除の自動化はTTL。',
  deep:`
  <div class="dh">🏷 あだ名</div>
  <div class="nick"><b>TTL</b>＝牛乳パックの賞味期限シール。期限が来たら冷蔵庫（テーブル）が自動で捨ててくれる。自分で毎日中を点検（Scan）しなくていい。</div>
  <div class="dh">💡 なぜこれが正解か</div>
  「期限が来たら自動で消える・追加コストなし・運用ゼロ」＝TTL。定期ScanやStreamsやテーブル作り直しはどれもコスト・手間が増える。
  <div class="dh">⚠️ つまずきやすい言葉</div>
  「一時データ・有効期限・自動削除・運用を最小」＝TTL。自前で削除を回すのは過剰。`
},
{
  id:67, cat:"高性能",
  scenario:"オンプレミスのデータセンターとAWSの間で、毎日大容量のデータを転送するバッチ処理がある。現在はインターネット経由のサイト間VPNを使っているが、時間帯によって帯域と遅延が大きく変動し、処理が安定しない。一貫した低遅延と安定した帯域を確保したい。",
  ask:'これらの要件を満たすソリューションはどれですか。',
  options:[
    "サイト間VPNトンネルを複数本張ってECMPで束ね、合計帯域を増やしてインターネット経由の転送を高速化する。",
    "Transit Gatewayを導入してVPN接続を集約し、複数VPCへの経路を一元管理して転送経路を整理する。",
    "S3 Transfer Accelerationを有効化し、CloudFrontのエッジ経由でデータをS3に高速アップロードする。",
    "AWS Direct Connectで専用線を敷設し、インターネットを経由しない一貫した低遅延・安定帯域の接続を確立する。"
  ],
  answer:3,
  keypoint:'「オンプレ↔AWS」「帯域・遅延が変動して不安定」「一貫した低遅延・安定帯域」。4つとも転送に関わるが、<b>経路を安定させて遅延を一定にする</b>のはどれか。',
  explain:'D＝Direct ConnectはオンプレとAWSを専用線で物理的に接続し、インターネットを経由しないため帯域と遅延が一貫して安定する。大容量・定常的な転送で安定性が要る時の本命。',
  elim:'A=VPNを束ねても経路はインターネットのままで遅延変動の根本は解決しない。B=Transit Gatewayは接続の集約・経路管理で、回線品質そのものは上げない。C=Transfer AccelerationはS3アップロード向けでオンプレ↔AWSの汎用接続でない。一貫した低遅延＝Direct Connect。',
  confusion:'<b>Direct Connect</b>＝専用線で一貫した低遅延・安定帯域（インターネット非経由）。<b>VPN</b>＝手軽だがインターネット経由で品質が変動。安定重視＝Direct Connect。',
  deep:`
  <div class="dh">🏷 あだ名</div>
  <div class="nick"><b>Direct Connect</b>＝会社専用の高速道路を一本通す。一般道（インターネット＝VPN）の渋滞に巻き込まれず、毎日同じ時間で着く。</div>
  <div class="nick"><b>VPN</b>＝一般道にトンネル（暗号化）を掘っただけ。道自体は混雑次第で遅延が変わる。</div>
  <div class="dh">💡 なぜこれが正解か</div>
  「一貫した低遅延・安定帯域」＝専用線のDirect Connect。VPNを何本束ねても経路はインターネットで変動は残る。
  <div class="dh">⚠️ つまずきやすい言葉</div>
  「一貫した・安定した・専用線」＝Direct Connect、「手軽・暗号化・コスト安いが変動」＝VPN。<b>安定か手軽か</b>で切り分ける。`
},
{
  id:68, cat:"ストレージ",
  scenario:"画像処理サービスで、元画像から生成したサムネイルや中間ファイルをS3に大量に保存している。これらはアクセス頻度が低く、万一消えても元画像からいつでも再生成できる。可用性は多少落としても構わないので、保管コストを最小化したい。",
  ask:'これらの要件を満たすソリューションはどれですか。',
  options:[
    "S3 Standardに保存し、高い可用性と即時アクセスを確保したまま大量のサムネイルを置いておく。",
    "S3 Standard-IAに保存し、低頻度アクセス向けの料金で3つのアベイラビリティゾーンに冗長化して保管する。",
    "S3 One Zone-IAに保存し、単一AZでの低頻度アクセス向け料金で、再生成可能なデータを最も安く保管する。",
    "S3 Glacier Flexible Retrievalに保存し、アーカイブ向けの最安クラスでサムネイルを長期保管する。"
  ],
  answer:2,
  keypoint:'「再生成可能」「低頻度」「可用性は多少落としてよい」「保管コスト最小」。4つとも保存先として正しいが、<b>単一AZ許容で最安にする</b>のはどれか。',
  explain:'C＝S3 One Zone-IAは低頻度アクセスデータを単一AZに保存することでStandard-IAより安い。AZ障害でデータを失うリスクがあるが、元から再生成できるデータなのでそのトレードオフが許容でき、コスト最小化に最適。',
  elim:'A=Standardは高可用だが割高で、可用性を落とせる本件には過剰。B=Standard-IAは3AZ冗長のぶんOne Zone-IAより高い。D=Glacierは取り出しに時間がかかり「すぐ再利用したいサムネイル」には不向き＋取り出しコスト。単一AZ許容の低頻度＝One Zone-IA。',
  confusion:'<b>S3 One Zone-IA</b>＝単一AZ・低頻度・再生成可能データに最安。<b>Standard-IA</b>＝3AZ冗長の低頻度。<b>可用性を落とせるか</b>で選ぶ。',
  deep:`
  <div class="dh">🏷 あだ名</div>
  <div class="nick"><b>One Zone-IA</b>＝倉庫を1棟だけにして賃料を下げる作戦。万一その倉庫が燃えても、元データから作り直せる物（サムネイル）だから困らない。</div>
  <div class="nick"><b>Standard-IA</b>＝同じ低頻度でも倉庫を3棟（3AZ）に分散するぶん賃料が高い。</div>
  <div class="dh">💡 なぜこれが正解か</div>
  「再生成できる＝可用性を落とせる」＋「低頻度・最安」＝One Zone-IA。Standardは割高、Standard-IAは3AZで高い、Glacierは即時取り出せない。
  <div class="dh">⚠️ つまずきやすい言葉</div>
  「再生成可能・単一AZでよい・最安」＝One Zone-IA、「即時アクセス不要・アーカイブ」＝Glacier。<b>可用性を落とせるか／即時要るか</b>で切り分ける。`
},
{
  id:69, cat:"セキュリティ",
  scenario:"S3に保存する機密データを保管時に暗号化する必要がある。さらに監査要件で、暗号化キーへのアクセスを細かく制御し、キーの利用履歴を追跡でき、キーの定期ローテーションも管理したい。鍵管理のための独自インフラは持ちたくない。",
  ask:'これらの要件を満たすソリューションはどれですか。',
  options:[
    "アプリ側で独自に暗号化してからS3にアップロードし、暗号鍵の生成・保管・ローテーションをすべて自社で行うクライアントサイド暗号化で、保管時の暗号化を実現する。",
    "SSE-S3（Amazon S3管理キー）でバケットを暗号化し、AWSが管理する鍵で保管時の暗号化を任せて、鍵のアクセス制御や利用監査の細かい設定はしない。",
    "バケットポリシーでHTTPS（aws:SecureTransport）を必須にして通信経路（in transit）を暗号化し、それで保管時のデータ保護まで満たせるものとする。",
    "SSE-KMS（AWS KMSキー）でバケットを暗号化し、キーポリシーでアクセスを制御し、CloudTrailで利用を監査し自動ローテーションを有効化する。"
  ],
  answer:3,
  keypoint:'「保管時の暗号化」「キーのアクセス制御・利用監査・ローテーション」「鍵管理インフラを持たない」。4つとも暗号化に関わるが、<b>キーを細かく管理・監査できる</b>のはどれか。',
  explain:'D＝SSE-KMSはKMSのキーでS3を暗号化し、キーポリシー/IAMでアクセスを細かく制御、CloudTrailでキー利用を監査、自動ローテーションも設定できる。鍵管理を任せつつ統制を効かせられる本命。',
  elim:'A=クライアントサイド暗号化は鍵の生成・保管・ローテーションを全部自前で背負い、要件「独自インフラを持ちたくない」に反する。B=SSE-S3はAWS管理鍵で暗号化はするがキー単位のアクセス制御・利用監査の粒度が低い。C=HTTPS必須は通信時（in transit）の話で保管時（at rest）暗号化ではない。鍵の統制＝SSE-KMS。',
  confusion:'<b>SSE-KMS</b>＝キーのアクセス制御・監査・ローテーションを管理。<b>SSE-S3</b>＝AWS任せで楽だが統制の粒度が低い。<b>at rest</b>（保管時）と<b>in transit</b>（通信時=HTTPS）は別。',
  deep:`
  <div class="dh">🏷 あだ名</div>
  <div class="nick"><b>SSE-KMS</b>＝鍵を金庫室（KMS）で集中管理。誰が鍵を使ったか台帳（CloudTrail）に残り、合鍵の配り方（キーポリシー）も決められ、定期的に鍵を取り替える（ローテーション）。</div>
  <div class="nick"><b>SSE-S3</b>＝鍵の管理を丸ごとお任せ。楽だが「誰がどの鍵を使ったか」の細かい統制はできない。</div>
  <div class="dh">💡 なぜこれが正解か</div>
  「保管時暗号化＋鍵のアクセス制御・監査・ローテーション・自前インフラ不要」＝SSE-KMS。自前暗号化は鍵管理が重く、SSE-S3は統制が粗く、HTTPSは通信時の話。
  <div class="dh">⚠️ つまずきやすい言葉</div>
  「キーのアクセス制御・利用監査・ローテーション」＝KMS。「通信を暗号化（HTTPS）」＝in transitで別物。<b>保管時か通信時か／鍵を管理したいか</b>で切り分ける。`
},
{
  id:70, cat:"可用性",
  scenario:"既存の本番アプリに新バージョンをリリースするにあたり、いきなり全ユーザーを切り替えるのは怖い。まず全トラフィックの5%だけを新環境に流して問題がないか様子を見て、問題なければ徐々に割合を増やしていきたい（カナリアリリース）。DNSはRoute 53で管理している。",
  ask:'これらの要件を満たすソリューションはどれですか。',
  options:[
    "フェイルオーバールーティングで、プライマリを旧環境・セカンダリを新環境にし、ヘルスチェックの結果で切り替える。",
    "レイテンシールーティングで、ユーザーから応答が速い方のエンドポイントへ自動的に振り分けてリリースする。",
    "加重ルーティングで、新環境に重み5・旧環境に重み95を設定し、徐々に新環境の重みを上げて移行していく。",
    "位置情報ルーティングで、特定の地域のユーザーだけを新環境に振り向けて反応を確認しながら進める。"
  ],
  answer:2,
  keypoint:'「最初5%だけ」「問題なければ徐々に増やす」＝割合でトラフィックを分けたい。4つともRoute 53の正しいルーティングだが、<b>割合で配分できる</b>のはどれか。',
  explain:'C＝加重ルーティングはレコードに重みを付けて指定した割合でトラフィックを分配できる。新5/旧95から始めて重みを動かせば、まさにカナリアの段階移行が実現する。',
  elim:'A=フェイルオーバーは正常/異常での切替で「割合」を制御できない。B=レイテンシーは速さ基準で割合制御でない。D=位置情報は地域基準で、割合での段階移行とは軸が違う。割合で配分＝加重ルーティング。',
  confusion:'<b>加重ルーティング</b>＝割合（重み）で配分＝カナリア/A-Bに最適。<b>フェイルオーバー</b>＝正常/異常の切替。<b>レイテンシー</b>＝速い方。<b>位置情報</b>＝地域別。',
  deep:`
  <div class="dh">🏷 あだ名</div>
  <div class="nick"><b>加重ルーティング</b>＝行列を「95人は旧レジ、5人は新レジ」と割合で振り分ける案内係。新レジが大丈夫そうなら少しずつ新レジの割合を増やす。</div>
  <div class="dh">💡 なぜこれが正解か</div>
  「5%→徐々に増やす」＝割合制御＝加重ルーティング。フェイルオーバーは切替、レイテンシーは速さ、位置情報は地域で、どれも割合配分ではない。
  <div class="dh">⚠️ つまずきやすい言葉</div>
  「段階的・カナリア・○%だけ」＝加重ルーティング。「正常/異常で切替」＝フェイルオーバー。<b>割合か切替か地域か</b>で切り分ける。`
},
{
  id:71, cat:"サーバーレス",
  scenario:"API Gateway＋Lambdaで公開APIを提供している。利用者にAPIキーを発行し、契約プランに応じて「1日あたりの呼び出し回数の上限」と「秒間レート制限」を設けて、特定クライアントの過剰利用からバックエンドを守りたい。",
  ask:'これらの要件を満たすソリューションはどれですか。',
  options:[
    "AWS WAFのレートベースルールをAPI Gatewayに関連付け、送信元IPアドレス単位で一定時間内のリクエスト数を制限する。",
    "Lambdaの予約済み同時実行数を設定し、関数が同時に処理する数の上限でバックエンドへの負荷を抑える。",
    "CloudFrontをAPIの前段に置いてレスポンスをキャッシュし、オリジンへ届くリクエスト数そのものを削減する。",
    "API Gatewayの使用量プランを作成し、APIキーごとにクォータ（日次上限）とスロットリング（レート/バースト）を設定する。"
  ],
  answer:3,
  keypoint:'「APIキー単位」「1日あたりの上限」「秒間レート制限」。4つとも負荷を抑える正しい手だが、<b>クライアント（キー）別に上限を課す</b>のはどれか。',
  explain:'D＝API Gatewayの使用量プランはAPIキーごとにクォータ（例：1日1万回）とスロットリング（レート・バースト）を設定でき、契約プラン別の上限管理にそのまま合致する。',
  elim:'A=WAFのレートベースはIP単位で、APIキー（契約者）単位の上限管理ではない。B=Lambda予約同時実行はバックエンド保護にはなるがクライアント別の上限ではない。C=CloudFrontキャッシュは総量を減らすがキー別のクォータ制御ではない。キー別上限＝使用量プラン。',
  confusion:'<b>使用量プラン＋APIキー</b>＝クライアント別の日次上限・レート制限。<b>WAFレートベース</b>＝IP単位の制限。<b>キー単位かIP単位か</b>で切り分ける。',
  deep:`
  <div class="dh">🏷 あだ名</div>
  <div class="nick"><b>使用量プラン</b>＝会員ランク別の利用券。「ゴールド会員は1日1万回まで」とキー（会員証）ごとに上限を決め、使いすぎを止める。</div>
  <div class="dh">💡 なぜこれが正解か</div>
  「APIキー単位・日次上限・レート制限」＝使用量プラン。WAFはIP単位、予約同時実行はバックエンド側、CloudFrontはキャッシュで、キー別の上限管理はできない。
  <div class="dh">⚠️ つまずきやすい言葉</div>
  「APIキー別・クォータ・契約プラン別の上限」＝API Gateway使用量プラン。「IP単位の制限」＝WAFレートベース。<b>キー単位かIP単位か</b>。`
},
{
  id:72, cat:"AI/ML",
  scenario:"ニュース記事サイトで、読者が記事を「耳で聞ける」ように、記事のテキストを自然な音声で読み上げてMP3として配信したい。機械学習の専門知識を持つ担当者はおらず、できるだけマネージドサービスで実現したい。",
  ask:'これらの要件を満たすソリューションはどれですか。',
  options:[
    "Amazon Pollyにテキストを渡し、自然な音声（ニューラル音声）のMP3に変換して読者に配信する。",
    "Amazon Transcribeに記事テキストを渡し、音声ファイルへ書き起こして読者に配信する。",
    "Amazon Translateで記事を別言語に変換し、その変換結果を音声として読者に配信する。",
    "Amazon Comprehendで記事の感情やキーフレーズを分析し、その分析結果を音声化して配信する。"
  ],
  answer:0,
  keypoint:'「テキスト→自然な音声（読み上げ）」「専門知識なし・マネージド」。4つとも実在のAIサービスだが、<b>文字を声にする</b>のはどれか。',
  explain:'A＝Amazon Pollyはテキストを自然な音声に変換する読み上げ（Text-to-Speech）サービス。ニューラル音声でMP3出力でき、MLの専門知識なしで記事の音声配信を実現できる。',
  elim:'B=Transcribeは音声→文字で向きが逆。C=Translateは翻訳で、音声化はしない。D=Comprehendはテキストの意味・感情分析で、音声を作る機能ではない。テキスト→音声＝Polly。',
  confusion:'<b>Polly</b>＝テキスト→音声（口）。<b>Transcribe</b>＝音声→テキスト（耳）。<b>Translate</b>＝翻訳（翻訳家）。<b>Comprehend</b>＝意味分析（文章を読む人）。',
  deep:`
  <div class="dh">🏷 あだ名</div>
  <div class="nick"><b>Polly</b>＝読み上げてくれる口。原稿（テキスト）を渡すと自然な声で読んでくれる。</div>
  <div class="nick"><b>Transcribe</b>＝聞いて書き取る耳（音声→文字）で、Pollyと向きが逆。</div>
  <div class="dh">💡 なぜこれが正解か</div>
  「テキストを自然な音声にして配信」＝Polly。Transcribeは逆向き、Translateは翻訳、Comprehendは分析で、どれも音声を作らない。
  <div class="dh">⚠️ つまずきやすい言葉</div>
  「読み上げ・テキスト→音声・MP3」＝Polly。「文字起こし・音声→テキスト」＝Transcribe。<b>向き（口か耳か）</b>で切り分ける。`
},
{
  id:73, cat:"疎結合",
  scenario:"注文処理システムで、SQSキューからメッセージを受け取ったコンシューマ（EC2上のワーカー）が、注文ごとに外部決済APIを呼ぶ処理をしている。決済APIの応答が遅いとき、メッセージの処理が可視性タイムアウトより長引き、まだ処理中なのに同じメッセージが別のワーカーにも配信されて二重決済が発生してしまった。重複処理を防ぎたい。",
  ask:'これらの要件を満たすソリューションはどれですか。',
  options:[
    "標準キューからSQS FIFOキューに変更し、メッセージグループ内の順序保証と重複排除によって、二重配信そのものをなくす。",
    "可視性タイムアウトを実際の処理時間より長く設定し、長引く処理ではChangeMessageVisibilityで延長して、処理完了までメッセージを他に配信させない。",
    "メッセージを受信した直後にDeleteMessageを呼んでキューから削除し、その後で決済処理を実行することで、再配信による重複処理を回避する。",
    "デッドレターキューを設定し、二重処理されてしまったメッセージを後から隔離することで、影響範囲を限定して本流への波及を抑える。"
  ],
  answer:1,
  keypoint:'「処理が可視性タイムアウトより長引いて」「同じメッセージが再配信され二重処理」。原因は可視性タイムアウト切れ。4つともSQSの正しい機能だが、<b>再配信の根本原因を断つ</b>のはどれか。',
  explain:'B＝可視性タイムアウトを処理時間より長くし、長引く時はChangeMessageVisibilityで延長すれば、処理完了（削除）まで他ワーカーに再配信されず重複処理を防げる。原因に直接効く。',
  elim:'A=FIFOは順序保証だが、それでも処理が可視性タイムアウトを超えれば再配信されうるので根本解決でない＋標準→FIFOはスループット制約も伴う。C=受信直後に削除すると処理失敗時にメッセージが失われる（信頼性を損なう危険な手）。D=DLQは失敗の隔離で、二重配信そのものは防げない。再配信防止＝可視性タイムアウトの適正化。',
  terms:[{t:"可視性タイムアウト",d:"コンシューマがメッセージを受信してから、他のコンシューマに再び見えなくなる時間。この間に処理を終えて削除しないと、再度配信され二重処理になる。"}],
  confusion:'<b>可視性タイムアウト</b>＝処理中の再配信を防ぐ時間。処理が長引くなら延長する。<b>FIFO</b>＝順序・重複排除（配信の順序問題）。<b>DLQ</b>＝失敗メッセージの隔離。二重配信の防止は可視性タイムアウト。',
  deep:`
  <div class="dh">🏷 あだ名</div>
  <div class="nick"><b>可視性タイムアウト</b>＝伝票を取った店員がいる間、その伝票を「処理中」として隠す時間。隠す時間が短すぎると、まだ作ってる料理の伝票が別の店員にも見えて二度作ってしまう。</div>
  <div class="dh">💡 なぜこれが正解か</div>
  原因は「処理が隠す時間を超えた→再び見えて二重処理」。隠す時間を処理に合わせて長くし、長引けば延長すれば再配信されない。受信即削除は失敗時にデータを失う危険手。
  <div class="dh">⚠️ つまずきやすい言葉</div>
  「処理が長引いて再配信・二重処理」＝可視性タイムアウトの調整。「順序がバラバラ・重複排除」＝FIFO。<b>原因が時間切れか順序か</b>で切り分ける。`
},
{
  id:74, cat:"配信/CDN",
  scenario:"動画配信サービスで、有料会員だけが視聴できる動画ファイルをS3に置き、CloudFront経由で配信している。会員がログイン後に取得したURLを使って動画にアクセスするが、そのURLを第三者にシェアされると非会員でも視聴できてしまう。一定時間で失効し、許可した相手だけがアクセスできる形で、CloudFront経由の限定配信を行いたい。",
  ask:'これらの要件を満たすソリューションはどれですか。',
  options:[
    "S3バケットのバケットポリシーで会員のIPアドレス範囲のみを許可し、CloudFront経由のアクセスをそのIPに限定することで、会員だけに配信する。",
    "CloudFrontの署名付きURL（または署名付きCookie）を発行し、有効期限とアクセス条件を埋め込んで、期限切れ後はアクセスできないようにする。",
    "CloudFrontでGeo Restrictionを設定し、許可した国からのアクセスだけに限定することで、その地域以外の非会員の視聴を防ぐ。",
    "Origin Access Control（OAC）を設定し、CloudFront経由でのみS3にアクセスできるようにしてS3への直リンクを防ぎ、それで会員限定の時限配信も兼ねる。"
  ],
  answer:1,
  keypoint:'「許可した相手だけ」「一定時間で失効」「CloudFront経由の限定配信」。4つともCloudFront/S3の正しいアクセス制御だが、<b>時間制限付きで個別に許可する</b>のはどれか。',
  explain:'B＝CloudFrontの署名付きURL/Cookieは有効期限やアクセス条件を署名に埋め込み、期限切れ後や条件外のアクセスを拒否できる。会員にだけ時間制限付きで配信する用途の本命。',
  elim:'A=IP制限は会員個人の識別にならず、URLシェアによる漏洩も防げない。C=Geo Restrictionは国単位で、許可した相手個人の限定や時間失効はできない。D=OACはS3直リンクを防いでCloudFront経由を強制するが、CloudFrontのURL自体を取得した第三者は視聴できてしまう（個別・時間制限の制御は別）。要件適合でB。',
  confusion:'<b>署名付きURL/Cookie</b>＝個別・時間制限付きのアクセス許可（限定配信）。<b>OAC</b>＝S3直アクセスを禁じCloudFront経由を強制（オリジン保護）。<b>Geo Restriction</b>＝国単位の制限。',
  deep:`
  <div class="dh">🏷 あだ名</div>
  <div class="nick"><b>署名付きURL</b>＝「○時まで有効」と書いた使い捨ての入場券。期限が切れたら同じURLでも入れない。</div>
  <div class="nick"><b>OAC</b>＝裏口（S3直リンク）を施錠して正面（CloudFront）からしか入れなくする鍵。誰でもいいから正面から来た人は入れる。</div>
  <div class="dh">💡 なぜこれが正解か</div>
  「許可した相手・一定時間で失効」＝署名付きURL/Cookie。OACは経路の強制で時間制限・個別許可はしない、IP/Geoは個人を識別しない。
  <div class="dh">⚠️ つまずきやすい言葉</div>
  「時間制限・限定配信・期限切れ」＝署名付きURL。「S3への直リンク防止・オリジン保護」＝OAC。<b>誰に時間制限で配るか／経路を縛るか</b>で切り分ける。`
},
{
  id:75, cat:"高性能",
  scenario:"ある分析基盤で、複数のEC2インスタンス（Auto Scalingグループ）から、共有の大容量データセットに同時にアクセスして読み書きしている。Linuxの標準的なファイルシステムとしてマウントでき、インスタンス台数が増減してもすべてのインスタンスから同じファイルを共有できるストレージが必要。容量はデータ量に応じて自動的に伸縮してほしい。",
  ask:'これらの要件を満たすソリューションはどれですか。',
  options:[
    "各EC2にEBS（gp3）ボリュームをアタッチし、必要に応じて手動でボリュームサイズを拡張して容量を確保する。",
    "Amazon EFSを作成して全EC2からNFSでマウントし、複数インスタンスから同じファイルを共有しつつ容量を自動伸縮させる。",
    "S3バケットにデータを置き、各EC2からAWS CLIでオブジェクトをダウンロード・アップロードして共有する。",
    "Amazon FSx for Windows File Serverを作成し、SMB経由で各EC2からファイル共有をマウントする。"
  ],
  answer:1,
  keypoint:'「複数Linux EC2から同時マウント」「台数増減しても同じファイルを共有」「容量が自動伸縮」。4つとも保存先として正しいが、<b>Linuxの複数同時マウント＋自動伸縮の共有ファイルシステム</b>はどれか。',
  explain:'B＝EFSはNFSで複数のLinux EC2から同時にマウントでき、容量はデータ量に応じて自動で伸縮する。Auto Scalingで台数が変わっても全インスタンスが同じファイルを共有できる、まさにこの用途のサービス。',
  elim:'A=EBSは原則1インスタンスにアタッチする外付けディスクで、複数からの共有マウントが基本できない＋手動拡張。C=S3はオブジェクトストレージでファイルシステムとしてのマウントではなく、同時読み書き共有の用途とずれる。D=FSx for WindowsはSMB（Windows向け）で、Linux標準のNFS共有には合わない。Linux共有＝EFS。',
  confusion:'<b>EFS</b>＝複数Linuxから同時マウント・自動伸縮（NFS共有ファイルシステム）。<b>EBS</b>＝単一インスタンスの外付けディスク。<b>FSx for Windows</b>＝Windows/SMBの共有。Linuxの共有ファイルシステム＝EFS。',
  deep:`
  <div class="dh">🏷 あだ名</div>
  <div class="nick"><b>EFS</b>＝みんなで使える共有の本棚（NFS）。何人（何台）来ても同じ棚を同時に読み書きでき、物が増えれば棚が自動で広がる。</div>
  <div class="nick"><b>EBS</b>＝1人用の外付けHDD。基本は1台にだけ繋ぐ。</div>
  <div class="dh">💡 なぜこれが正解か</div>
  「複数Linuxから同時・自動伸縮の共有」＝EFS。EBSは単一台向け、S3はマウントでなくオブジェクト、FSx for WindowsはWindows/SMB向け。
  <div class="dh">⚠️ つまずきやすい言葉</div>
  「複数から同時マウント・NFS・Linux共有」＝EFS、「Windows・SMB・Active Directory連携」＝FSx for Windows、「1台専用の外付け」＝EBS。<b>同時共有か単一か／LinuxかWindowsか</b>。`
},
{
  id:76, cat:"可用性",
  scenario:"あるECサイトが、毎日決まった時間帯（平日9時〜21時）にアクセスが多く、深夜から早朝はほとんどアクセスがない、という安定したパターンを持つ。Auto Scalingグループで運用しているが、需要が増えてからスケールアウトすると立ち上がりが間に合わず、朝のアクセス開始直後に一時的に応答が遅くなる。決まった時間に向けてあらかじめ容量を用意しておきたい。",
  ask:'これらの要件を満たすソリューションはどれですか。',
  options:[
    "ターゲット追跡スケーリングでCPU使用率の目標値を設定し、負荷が上がり始めたら自動でインスタンスを追加する。",
    "スケジュールスケーリングを設定し、平日9時の少し前に最小容量を引き上げ、21時以降に縮小するよう時刻ベースで容量を変更する。",
    "簡易スケーリングポリシーでCloudWatchアラームを設定し、閾値を超えたタイミングでインスタンスを追加する。",
    "Auto Scalingグループの最小容量を常にピーク時の台数に固定し、いつでも需要に応えられるようにする。"
  ],
  answer:1,
  keypoint:'「毎日決まった時間帯」という予測可能なパターン＋「立ち上がりが間に合わない」＝事前に用意したい。4つともスケーリングの正しい手だが、<b>決まった時刻に向けて先回りで容量を用意</b>するのはどれか。',
  explain:'B＝スケジュールスケーリングは時刻ベースで容量を変更でき、9時の手前で最小容量を引き上げておけばアクセス開始時に容量が揃っている。安定した時間帯パターンにはこれが最適。',
  elim:'A・C=ターゲット追跡や簡易スケーリングは「負荷が上がってから」反応するため立ち上がり遅れの問題が残る。D=ピーク台数で固定すれば遅れはないが深夜も無駄に動かしコストが大きい（縮小しない）。予測可能な時間帯への先回り＝スケジュールスケーリング。',
  confusion:'<b>スケジュールスケーリング</b>＝決まった時刻に先回りで容量変更（予測可能なパターン）。<b>ターゲット追跡</b>＝負荷の指標を見て後追いで増減。<b>固定</b>＝遅れはないがコスト大。',
  deep:`
  <div class="dh">🏷 あだ名</div>
  <div class="nick"><b>スケジュールスケーリング</b>＝開店前にバイトを多めに呼んでおく店長。9時に客が来てから呼ぶ（後追い）と間に合わないので、毎日決まって8時45分に増員する。</div>
  <div class="dh">💡 なぜこれが正解か</div>
  「毎日決まった時間帯」＝予測できるので時刻ベースで先回り＝スケジュールスケーリング。後追いのターゲット追跡・簡易は立ち上がり遅れが残り、固定は深夜が無駄。
  <div class="dh">⚠️ つまずきやすい言葉</div>
  「決まった時間・予測できる需要・事前に用意」＝スケジュールスケーリング。「負荷に応じて自動増減」＝ターゲット追跡。<b>予測できる時刻か、その場の負荷か</b>で切り分ける。`
},
{
  id:77, cat:"セキュリティ",
  scenario:"あるVPCで、セキュリティチームから「インスタンス間やインターネットとの通信が、いつ・どの送信元から・どの宛先へ・許可されたか拒否されたか」を記録して、不審な通信の調査やトラブルシューティングに使いたいと要望が出た。パケットの中身までは不要で、通信のメタデータ（IP・ポート・許可/拒否）のログが取れればよい。",
  ask:'これらの要件を満たすソリューションはどれですか。',
  options:[
    "VPCフローログを有効化し、ENI単位で通信のメタデータ（送信元/宛先IP・ポート・許可/拒否）をCloudWatch LogsまたはS3に記録する。",
    "AWS CloudTrailを有効化し、VPC内のインスタンス間のすべてのネットワーク通信を、APIの証跡と同じように記録できるものとして扱う。",
    "Amazon GuardDutyを有効化し、不審な通信を検知して、その許可/拒否を含む通信メタデータのログまで自動で保存できるものとして構成する。",
    "Traffic Mirroringを設定し、対象ENIの全パケットを丸ごとコピーして分析用アプライアンスへ送り、その中から通信のメタデータを取り出して記録する。"
  ],
  answer:0,
  keypoint:'「通信のメタデータ（IP・ポート・許可/拒否）」「中身は不要」「記録して調査に使う」。4つとも監視/記録に関わるが、<b>VPCの通信メタデータを記録する</b>のはどれか。',
  explain:'A＝VPCフローログはENI単位で通信のメタデータ（送信元/宛先IP・ポート・プロトコル・許可/拒否）をCloudWatch LogsやS3に記録する。パケット中身は含まず、まさにこの要件のための機能。',
  elim:'B=CloudTrailはAWS APIの操作証跡で、ネットワークの通信ログではない。C=GuardDutyは脅威の検知であって全通信の記録そのものではない。D=Traffic Mirroringはパケットの中身まで丸ごとコピーする重い手段で「中身は不要」の要件に対し過剰。通信メタデータの記録＝VPCフローログ。',
  confusion:'<b>VPCフローログ</b>＝通信のメタデータ（IP/ポート/許可・拒否）を記録。<b>CloudTrail</b>＝AWS API操作の証跡。<b>Traffic Mirroring</b>＝パケット中身の複製（重い）。通信の記録＝フローログ。',
  deep:`
  <div class="dh">🏷 あだ名</div>
  <div class="nick"><b>VPCフローログ</b>＝建物の通信記録の受付台帳。「誰から誰へ・どのドア（ポート）・通した/断った」を書く。会話の中身（パケット本体）までは書かない。</div>
  <div class="nick"><b>CloudTrail</b>＝AWSの操作記録簿（API）。ネットワークの通信そのものは見ない。</div>
  <div class="dh">💡 なぜこれが正解か</div>
  「IP・ポート・許可/拒否のメタデータを記録」＝VPCフローログ。CloudTrailはAPI操作、GuardDutyは検知、Traffic Mirroringは中身まで取る過剰手段。
  <div class="dh">⚠️ つまずきやすい言葉</div>
  「通信のメタデータ・送信元/宛先・許可/拒否」＝VPCフローログ。「誰がどのAPIを叩いたか」＝CloudTrail。<b>通信の記録かAPI操作の記録か</b>で切り分ける。`
},
{
  id:78, cat:"AI/ML",
  scenario:"越境ECサイトで、海外の購入者が書いた多言語のレビューを、日本の運営チームが読めるように日本語へ自動翻訳して表示したい。レビューの言語はさまざまで、機械学習の専門知識を持つ担当者はいない。マネージドサービスで実現したい。",
  ask:'これらの要件を満たすソリューションはどれですか。',
  options:[
    "Amazon Translateにレビューを渡し、ソース言語の自動検出を使って多言語のテキストを日本語へ翻訳する。",
    "Amazon Comprehendでレビューの言語を検出し、その検出結果（言語コード）をそのまま日本語の翻訳文として表示する。",
    "Amazon Transcribeでレビューのテキストを音声化し、日本語ナレーションとして運営チームに提供する。",
    "Amazon Pollyでレビューを読み上げて音声化し、運営チームが耳で内容を把握できるようにする。"
  ],
  answer:0,
  keypoint:'「多言語のテキスト」→「日本語へ翻訳」「専門知識なし」。4つとも実在のAIサービスだが、<b>テキストを別言語に翻訳する</b>のはどれか。',
  explain:'A＝Amazon Translateはテキストを別言語へ翻訳するマネージドサービス。ソース言語の自動検出に対応するため、言語がさまざまな多言語レビューをそのまま日本語へ翻訳できる。',
  elim:'B=Comprehendは言語検出や感情分析はできるが「翻訳」はしない（言語コードを返すだけで翻訳文にならない）。C=Transcribeは音声→文字で、翻訳でも表示用途でもない。D=Pollyは読み上げ（音声化）で、翻訳しない。テキスト翻訳＝Translate。',
  confusion:'<b>Translate</b>＝テキストを別言語に翻訳（翻訳家）。<b>Comprehend</b>＝言語検出・感情・キーフレーズ分析（文章を読む人、翻訳はしない）。翻訳が要るならTranslate。',
  deep:`
  <div class="dh">🏷 あだ名</div>
  <div class="nick"><b>Translate</b>＝翻訳家。どの言語で書かれていても（自動検出）日本語に訳してくれる。</div>
  <div class="nick"><b>Comprehend</b>＝文章を読んで「これは英語だね」「怒ってる感じ」と分析する人。訳すのは仕事ではない。</div>
  <div class="dh">💡 なぜこれが正解か</div>
  「多言語→日本語に翻訳」＝Translate（ソース言語の自動検出付き）。Comprehendは言語検出止まりで翻訳しない、Transcribe/Pollyは音声系。
  <div class="dh">⚠️ つまずきやすい言葉</div>
  「翻訳・別言語へ変換」＝Translate。「言語を検出する・意味や感情を分析」＝Comprehend。<b>訳すのか分析するのか</b>で切り分ける。`
},
{
  id:79, cat:"ストレージ", multi:true,
  scenario:"S3バケットに重要な契約書類を保管している。運用担当者の誤操作や認証情報の漏洩によって、オブジェクトが誤って削除・上書きされたり、完全に消されたりするリスクを下げたい。万一上書き・削除されても以前の状態に戻せ、かつ削除操作自体を強力に保護する構成にしたい。",
  ask:'誤った削除や上書きからオブジェクトを保護し、後から以前の状態に復元できるようにするために取るべきアクションはどれですか。（2 つ選択）',
  options:[
    "S3バージョニングを有効化し、上書き・削除されても以前のバージョンを保持して復元できるようにする。",
    "バージョニング済みバケットでMFA Deleteを有効化し、バージョンの完全削除に多要素認証を要求して強力に保護する。",
    "ライフサイクルルールを設定し、古いオブジェクトを自動的にGlacier Deep Archiveへ移行して保管コストを下げる。",
    "ストレージクラスをS3 One Zone-IAに変更し、単一AZ保管にして保管コストを削減する。",
    "S3サーバーアクセスログとCloudTrailのデータイベントを有効化し、誰がいつ削除や上書きの操作を行ったかを記録する。"
  ],
  answer:[0,1],
  keypoint:'要件は「誤削除・誤上書きから守り、後から復元でき、削除を強力に保護」。5つのうち、軸が<b>データ保護・復元</b>なのか<b>コスト削減</b>なのか<b>監査</b>なのかで仕分ける。保護に効く2つを選ぶ。',
  explain:'A＝バージョニングで上書き・削除しても旧バージョンが残り復元できる。B＝MFA Deleteでバージョンの完全削除に多要素認証を要求し、誤操作・漏洩時の削除を強力に防ぐ。この2つが「保護＋復元」を満たす。',
  elim:'C=Glacier移行はコスト削減策で、誤削除・誤上書きからの保護とは軸が違う。D=One Zone-IAはむしろ単一AZで耐久性を下げるコスト削減で要件と逆方向。E=アクセスログ/CloudTrailは「誰が操作したか」を記録する事後の監査で、削除・上書きそのものを防いだり復元したりはしない。保護・復元の2つ＝A（バージョニング）とB（MFA Delete）。',
  confusion:'<b>バージョニング＋MFA Delete</b>＝誤削除・改ざんからの保護と復元。<b>ライフサイクル/One Zone-IA</b>＝コスト削減（保護ではない）。要件の軸が保護かコストかを最初に見分ける。',
  deep:`
  <div class="dh">🏷 あだ名</div>
  <div class="nick"><b>バージョニング</b>＝書類のコピーを世代ごとに残す。上書き・削除しても前の版を取り出せる。</div>
  <div class="nick"><b>MFA Delete</b>＝完全削除には二重ロック（多要素認証）を要求する金庫。鍵が漏れても勝手に消せない。</div>
  <div class="dh">💡 なぜA・Bが正解か</div>
  「誤削除・誤上書きから守り復元」＝バージョニング、「削除を強力に保護」＝MFA Delete。Glacier・One Zone-IAはコストの話で保護の軸ではない。
  <div class="dh">⚠️ つまずきやすい言葉</div>
  「保護・復元・誤削除対策」＝バージョニング＋MFA Delete。「コスト削減・アーカイブ・安く」が出たらライフサイクル/ストレージクラスの話で、保護の問いとは混ぜない。<b>保護かコストか</b>で2つを選ぶ。`
},
{
  id:80, cat:"コスト最適化", multi:true,
  scenario:"開発・検証用のEC2環境が多数あり、コストが膨らんでいる。これらは平日の業務時間だけ使われ、夜間・週末は誰も使わない。また、実際の使用状況に対してインスタンスサイズが過大なものも多いと分かっている。使い方は今後も変わる可能性があり、長期の利用量コミットはしたくない。",
  ask:'開発・検証環境のEC2コストを、長期の利用量コミットをせずに削減するために取るべきアクションはどれですか。（2 つ選択）',
  options:[
    "Instance Schedulerなどで、平日の業務時間外（夜間・週末）にインスタンスを自動停止・起動するスケジュールを設定する。",
    "対象インスタンスに対して3年前払いのStandard Reserved Instancesを購入し、最大の割引率を確保する。",
    "Compute Optimizerの推奨に基づいて、過大なインスタンスを実使用量に合ったサイズにライトサイジング（変更）する。",
    "1年・最大コミットのCompute Savings Plansを購入し、開発環境の料金単価を長期契約で下げる。",
    "Cost Explorerでコスト配分タグを付けて開発・検証環境の費用を可視化し、どこにコストがかかっているかをレポートする。"
  ],
  answer:[0,2],
  keypoint:'「業務時間だけ使う・夜間週末は不要」「サイズが過大」「長期コミットはしたくない」。5つのうち、<b>長期コミットなしで実際にコストを下げる</b>2つを選ぶ。',
  explain:'A＝使わない夜間・週末に自動停止すれば、止めている間の料金が発生せず大きく削減できる。C＝過大なサイズを実使用に合わせて縮小すれば単価が下がる。どちらもコミット不要で、使い方が変わっても柔軟に対応できる。',
  elim:'B=3年RIは長期の利用量コミットで「コミットしたくない・使い方が変わる」に真っ向から反する。D=Savings Plansも長期コミット前提で同じく要件に反する（常時稼働の安定ワークロード向け）。E=Cost Explorerでの可視化は「どこにコストがかかるか」を見るだけで、それ自体はコストを削減しない。長期コミット不要で削減に効く2つ＝A（スケジュール停止）とC（ライトサイジング）。',
  confusion:'<b>スケジュール停止＋ライトサイジング</b>＝コミット不要で柔軟（断続利用・過大サイズに効く）。<b>RI/Savings Plans</b>＝長期コミットで割引（常時稼働の安定ワークロード向け）。コミットの可否が分かれ目。',
  deep:`
  <div class="dh">🏷 あだ名</div>
  <div class="nick"><b>スケジュール停止</b>＝使わない時間は電気を消す。開発環境は夜・週末に誰もいないので消すだけで大幅節約。</div>
  <div class="nick"><b>ライトサイジング</b>＝大きすぎる部屋を実際の人数に合った広さに替えて賃料を下げる。</div>
  <div class="nick"><b>RI/Savings Plans</b>＝長期契約の定期券。毎日フルに使う人は得だが、使い方が変わる開発環境では縛りが裏目に出る。</div>
  <div class="dh">💡 なぜA・Cが正解か</div>
  「断続利用＋過大サイズ＋長期コミット不可」＝止める＋縮める。RI・Savings Plansは長期コミットで「使い方が変わる」開発環境に不向き。
  <div class="dh">⚠️ つまずきやすい言葉</div>
  「使う時間が決まっている・断続利用」＝スケジュール停止、「サイズが過大」＝ライトサイジング、「常時稼働・長期コミットOK」＝RI/Savings Plans。<b>コミットできるかどうか</b>で切り分ける。`
}
];


// ============================================================
// 複数選択(2つ選ぶ)増強（2026-06-16 saa-multi）id81〜88
// 本番SAAの「適切な対応を2つ選べ」形式。4択から2つ。
