QUESTIONS.push(
{
  id:81, cat:"セキュリティ", multi:true,
  scenario:"ある企業が新しくAWSアカウントを開設し、複数のメンバーで運用を始めようとしている。セキュリティ監査から『ルートユーザーの保護』と『最小権限の徹底』を最優先で実施するよう求められた。日常の構築作業はルートではなく権限を絞ったエンティティで行いたい。アカウントの初期セキュリティを固める対応を取りたい。",
  ask:'アカウントの初期セキュリティ強化に直接寄与するものはどれですか。（2 つ選択）',
  options:[
    "ルートユーザーにMFAを有効化し、ルートのアクセスキーが存在する場合は削除して、ルートは日常作業に使わない。",
    "運用を簡単にするため、全メンバーにAdministratorAccessポリシーを付与する。",
    "1つのIAMアクセスキーを全メンバーで共有し、ローテーションは年に1回行う。",
    "メンバーには職務に必要な権限だけを付与したIAMロール/ユーザーを用意し、最小権限の原則で運用する。",
    "IAM Access Analyzerを有効化して、外部に公開されたリソースを検出できるようにする。"
  ],
  answer:[0,3],
  keypoint:'2つ選ぶ問題。要件は「ルート保護」と「最小権限」。A＝ルートのMFA＋キー削除でルート保護、D＝必要な権限だけ付与で最小権限。B(全員Admin)とC(キー共有)は逆に権限を広げ共有してしまう典型的なアンチパターン。E(Access Analyzer)は有用だが初期の最優先2つそのものではない。',
  explain:'A＝ルートユーザーは最強権限なのでMFAで保護しアクセスキーは削除、日常はルートを使わないのが鉄則。D＝各メンバーに職務に必要な権限だけ与える最小権限は、万一の漏洩時の影響を最小化する。この2つがアカウント初期セキュリティの定石。',
  elim:'B＝全員にAdministratorAccessは最小権限の真逆で、1人の認証情報漏洩が全権限の漏洩になる。C＝アクセスキーの共有は誰の操作か追跡できず、年1回のローテーションも長すぎる。E＝IAM Access Analyzerは公開リソースの検出に有用だが、ルート保護・最小権限という今回の最優先要件そのものではない。正解はA・D。',
  confusion:'<b>ルート保護＝MFA＋アクセスキー削除＋日常は使わない／最小権限＝必要な権限だけ付与・共有しない。</b>「アカウントを固める」と来たら、ルートを封印し、各自に絞った権限を配る、の2点。',
  deep:`
  <div class="dh">🏷 出てきたものの「あだ名」</div>
  <div class="nick"><b>ルートユーザー</b>＝建物の「マスターキー」。何でも開く最強の鍵だから、金庫(MFA)にしまって普段は使わない。合鍵(アクセスキー)は作らない。</div>
  <div class="nick"><b>最小権限</b>＝各人に「自分の部屋の鍵だけ」を渡す考え方。鍵を1本落としても被害がその部屋で済む。</div>
  <div class="dh">💡 なぜこれが正解か</div>
  「ルート保護＋最小権限」がそのまま要件。マスターキーを封印(MFA＋キー削除)し、各自には必要な鍵だけ渡す。全員にマスターキー(Admin)や鍵の共有は真逆。
  <div class="dh">⚠️ つまずきやすい言葉</div>
  <b>「運用を簡単に」を理由に全員Admin・キー共有を選ばせる誘導が頻出の罠。</b>セキュリティ問題では"楽だから広く"は常に誤り。`
},
{
  id:82, cat:"高性能", multi:true,
  scenario:"あるモバイルアプリが、ユーザープロフィールをDynamoDBに保存している。新機能のリリースでアクセスが読み取り中心に急増し、しかもトラフィックの山が読みづらく予測できない。同じ人気ユーザーのデータが繰り返し読まれる傾向もある。アプリのレスポンスを保ちつつ、予測不能な負荷変動に追従したい。",
  ask:'DynamoDBの読み取り性能と、予測不能な負荷変動への追従に有効なものはどれですか。（2 つ選択）',
  options:[
    "毎回Scanオペレーションでテーブル全体を読み、必要なデータをアプリ側で絞り込む。",
    "DynamoDB Accelerator(DAX)をテーブルの前段に置き、繰り返し読まれるデータをマイクロ秒で返してテーブルへの読み取りを減らす。",
    "キャパシティをオンデマンドモードに切り替え、予測不能なトラフィックの増減に自動で追従させる。",
    "全ての読み取りを強整合性読み取りに変更して、常に最新の値を取得する。",
    "テーブルにグローバルセカンダリインデックス(GSI)を追加し、別の属性での検索を増やす。"
  ],
  answer:[1,2],
  keypoint:'2つ選ぶ問題。「繰り返し読まれる→キャッシュ(DAX)」「予測不能な変動→オンデマンドで自動追従」。BとCで性能と変動対応を満たす。Aの全件Scanは高コスト・低速、Dの常時強整合性はRCUを余計に消費、Eは別検索用で繰り返し読みの高速化や変動追従ではない。',
  explain:'B＝DAXはDynamoDB専用のインメモリキャッシュで、繰り返し読まれるデータをマイクロ秒で返しテーブルへの読み取り負荷を下げる。C＝オンデマンドキャパシティは事前のキャパシティ設定なしで予測不能なトラフィックに自動追従する。読み取り性能と変動対応の両方に効く。',
  elim:'A＝Scanはテーブル全体を読むため大量のRCUを消費し遅い（特定キーの取得はGetItem/Queryを使う）。D＝強整合性読み取りは結果整合性の倍のRCUを消費し、最新値が必須でない用途では性能・コストの無駄。E＝GSIは別の属性で検索するための索引で、同じデータの繰り返し読みの高速化や負荷変動追従とは軸が違う。正解はB・C。',
  confusion:'<b>繰り返し読み＝DAX(キャッシュ)／予測不能な変動＝オンデマンドキャパシティ(自動追従)。</b>「同じデータが何度も」ならDAX、「山が読めない」ならオンデマンド。Scanやむやみな強整合性は性能を下げる。',
  deep:`
  <div class="dh">🏷 出てきたものの「あだ名」</div>
  <div class="nick"><b>DAX</b>＝DynamoDB専属の「早出し係」。よく注文される品を手元に持って即出しする。テーブルへ取りに行く回数が減る。</div>
  <div class="nick"><b>オンデマンドキャパシティ</b>＝「使った分だけ・客数に勝手に合わせる」料金体系。山が読めなくても自動でさばく。</div>
  <div class="dh">💡 なぜこれが正解か</div>
  「同じデータが繰り返し＋山が読めない」＝早出し係(DAX)で読みを軽くし、客数追従(オンデマンド)で変動を吸収。全件Scanや常時強整合性は読みを重くするだけ。
  <div class="dh">⚠️ つまずきやすい言葉</div>
  <b>Scan(全件なめる＝重い)とQuery/GetItem(キー指定＝軽い)、結果整合性(安い)と強整合性(倍のRCU)を区別する。</b>「速く・安く」が要件なら重い方を選ばない。`
}
);

QUESTIONS.push(
{
  id:83, cat:"可用性", multi:true,
  scenario:"あるWebアプリが、単一AZの複数EC2で動いているが、各EC2のローカルディスクにユーザーのセッション情報を保持している。そのため特定のEC2が落ちるとそのユーザーはログアウトされ、AZ障害時にはサービスが止まる。可用性を高め、インスタンスが入れ替わっても影響が出ない構成にしたい。",
  ask:'スケールアウトと可用性の向上に直接寄与するものはどれですか。（2 つ選択）',
  options:[
    "セッション情報を各EC2のローカルディスクに保持したまま、ディスクをSSDに変えて読み書きを速くする。",
    "セッション情報をElastiCacheやDynamoDBなど外部ストアに持たせ、EC2をステートレスにする。",
    "1台の大型インスタンスにアプリを集約し、構成をシンプルにして管理を楽にする。",
    "Auto Scalingグループを複数AZに広げ、ALBのヘルスチェックで異常なインスタンスを自動で切り離す。",
    "各EC2に Elastic IP を割り当て、利用者が常に同じインスタンスへ接続するように固定する。"
  ],
  answer:[1,3],
  keypoint:'2つ選ぶ問題。可用性を上げてインスタンス入れ替えに強くするには「ステートレス化(セッション外出し)」と「複数AZ＋ヘルスチェック」。BとDが直接寄与。Aはローカル保持のままで入れ替えに弱い、Cは単一障害点に逆戻り、Eは特定インスタンスへの固定でむしろ入れ替えに弱くなる。',
  explain:'B＝セッションを外部ストアに出すとEC2がステートレスになり、どのインスタンスでも処理でき入れ替えても影響が出ない。D＝Auto Scalingを複数AZに広げALBのヘルスチェックで異常を切り離せば、AZ障害や個別障害に耐える。スケールアウト型の可用性の定石。',
  elim:'A＝ローカルディスクにセッションを残したままでは、インスタンスが落ちた/入れ替わった瞬間にセッションが消える＝可用性の本質が改善しない。C＝大型1台への集約は単一障害点そのもので可用性が下がる。E＝Elastic IPで特定インスタンスへ固定すると、そのインスタンスが落ちた時にユーザーが影響を受け、入れ替え前提のスケールアウトに逆行する。正解はB・D。',
  confusion:'<b>スケールアウト可用性＝ステートレス化(状態を外部へ)＋複数AZ配置(ALB＋ヘルスチェック)。</b>「インスタンスが入れ替わっても平気に」したいなら、まず状態をEC2の外へ出すのが鍵。',
  deep:`
  <div class="dh">🏷 出てきたものの「あだ名」</div>
  <div class="nick"><b>ステートレス化</b>＝店員が「自分のメモ帳」に客の情報を書くのをやめ、共有の台帳(ElastiCache/DynamoDB)に書く。どの店員に代わっても接客が続く。</div>
  <div class="nick"><b>複数AZ＋ヘルスチェック</b>＝店を複数の建物に分け、具合の悪い店員(異常インスタンス)を自動で休ませる(切り離す)。</div>
  <div class="dh">💡 なぜこれが正解か</div>
  「インスタンスが入れ替わっても影響を出さない」＝状態をEC2の外へ(ステートレス)＋複数AZで冗長化。ローカル保持のままや1台集約は、入れ替え・障害に弱いまま。
  <div class="dh">⚠️ つまずきやすい言葉</div>
  <b>可用性の第一歩は「状態(セッション)をどこに持つか」。</b>ローカルディスクに状態があると水平スケールも可用性も成立しない。`
},
{
  id:84, cat:"コスト最適化", multi:true,
  scenario:"ある企業が、AWSの月額コストが想定より膨らんでいることに気づいた。調べると、アクセス頻度が読みづらいデータをすべてS3 Standardに置きっぱなしにしていること、削除し忘れた古いEBSスナップショットや誰もアタッチしていないボリュームが大量に残っていることが分かった。サービスの可用性や性能は維持したまま、無駄なコストを削りたい。",
  ask:'ストレージコストの削減に直接寄与するものはどれですか。（2 つ選択）',
  options:[
    "すべてのデータをS3 Standardに置き続け、バケットポリシーでアクセスを制限してコストを抑える。",
    "すべてのEC2をオンデマンドの最大サイズで起動し、性能の余裕を最優先にする。",
    "S3 Intelligent-Tieringを有効にし、アクセス頻度が読みづらいデータの階層をAWSに自動最適化させる。",
    "未アタッチのEBSボリュームや不要になった古いスナップショットを棚卸しして削除する。",
    "すべてのS3オブジェクトをS3 Standardから強制的にGlacier Instant Retrievalへ移し、即時取り出しを維持する。"
  ],
  answer:[2,3],
  keypoint:'2つ選ぶ問題。「アクセス頻度が読みづらい→Intelligent-Tieringで自動最適化」「使っていないボリューム/スナップショット→削除」。CとDで無駄を削る。Aは単価が下がらず、Bはむしろコストを増やし、Eはアクセスがあると取り出し課金で逆に高くつきうる。',
  explain:'C＝Intelligent-Tieringはアクセスパターンが予測できないデータの階層を監視して自動で安い階層へ動かす。D＝未アタッチボリュームや不要スナップショットは課金され続けるので、棚卸しして削除すれば直接コストが減る。可用性・性能を落とさずに削れる2つ。',
  elim:'A＝Standardに置き続けるとストレージ単価は下がらない（アクセス制限してもストレージ代は変わらない）。B＝最大サイズで常時起動はコストを増やす方向で、コスト最適化の真逆。E＝アクセス頻度が読めないデータを一律でGlacier Instantに移すと、頻繁にアクセスされる分は取り出し課金がかさみ逆に高くつきうる（だから自動最適化のIntelligent-Tieringが適切）。正解はC・D。',
  confusion:'<b>アクセス頻度が読めない＝Intelligent-Tiering(自動)／規則的に古くなる＝固定ライフサイクル／使っていないリソース＝棚卸しして削除。</b>「コストが膨らむ」と来たら、階層最適化と不要リソース削除の2方向を見る。',
  deep:`
  <div class="dh">🏷 出てきたものの「あだ名」</div>
  <div class="nick"><b>S3 Intelligent-Tiering</b>＝「使われ方を見て自動で棚を移す」倉庫番。よく出る物は手前、出ない物は奥へ勝手に動かす。アクセスが読めない時に向く。</div>
  <div class="nick"><b>未アタッチボリューム/古いスナップショット</b>＝「誰も使っていないのに置き場代だけ払っている荷物」。捨てれば即コスト減。</div>
  <div class="dh">💡 なぜこれが正解か</div>
  「頻度が読めないデータ＋放置リソース」＝自動で棚を最適化(Intelligent-Tiering)＋使っていない荷物を処分(削除)。Standard据え置きは単価が下がらず、最大サイズ常時起動は逆効果。
  <div class="dh">⚠️ つまずきやすい言葉</div>
  <b>「アクセス制限」はセキュリティの話でストレージ単価は下がらない。</b>コスト削減は"安い階層へ移す"か"消す"のどちらか。`
}
);

QUESTIONS.push(
{
  id:85, cat:"セキュリティ", multi:true,
  scenario:"ある企業のセキュリティ監査で『誰がいつどのAPI操作を行ったかの記録』と『リソース構成の変更履歴と基準からの逸脱検出』を残すよう求められた。現在はどちらも有効化されておらず、問題が起きても追跡できない。マネージドな仕組みで監査要件を満たしたい。",
  ask:'操作の監査と構成の監査の要件を満たすものはどれですか。（2 つ選択）',
  options:[
    "CloudTrailを有効化し、全リージョンのAPI操作ログをS3に記録して誰がいつ何をしたかを追跡できるようにする。",
    "CloudWatchダッシュボードでEC2のCPU使用率やメモリ使用率を可視化する。",
    "AWS Configを有効化し、リソース構成の変更履歴を記録して定義したルールからの逸脱を検出する。",
    "VPCフローログを有効にして、ネットワークインターフェイスの通信トラフィックを記録する。",
    "Amazon Macieを有効化し、S3バケット内の個人情報(PII)を検出する。"
  ],
  answer:[0,2],
  keypoint:'2つ選ぶ問題。「誰がいつどのAPI操作を→CloudTrail」「構成変更履歴と基準逸脱→Config」。AとCが監査要件に直結。Bは性能メトリクスの監視、Dは通信ログ、Eは個人情報の検出で、いずれも操作・構成の監査ではない。',
  explain:'A＝CloudTrailはAWSへのAPI操作(誰が・いつ・何を)を記録する操作監査の中核。C＝Configはリソースの構成変更を時系列で記録し、定義したルールからの逸脱(コンプライアンス状態)を検出する。監査要件の2本柱。',
  elim:'B＝CloudWatchダッシュボードはCPU等のパフォーマンス監視であって、操作や構成の監査ではない。D＝VPCフローログはネットワーク通信の記録で、API操作の監査やリソース構成の追跡には使えない。E＝MacieはS3内の個人情報の発見で、操作・構成の監査とは目的が違う。正解はA・C。',
  confusion:'<b>API操作の監査＝CloudTrail／構成変更と基準逸脱＝Config／性能監視＝CloudWatch／通信ログ＝VPCフローログ。</b>「誰が操作したか」はCloudTrail、「構成が基準から外れていないか」はConfig。',
  deep:`
  <div class="dh">🏷 出てきたものの「あだ名」</div>
  <div class="nick"><b>CloudTrail</b>＝「誰が・いつ・何の操作をしたか」を全部書き留める操作記録係。後から追跡できる。</div>
  <div class="nick"><b>Config</b>＝「間取り(構成)の変更履歴と、決めたルールからのズレ」を見張る監査役。</div>
  <div class="dh">💡 なぜこれが正解か</div>
  要件は「操作の記録」と「構成の変更履歴＋逸脱検出」＝そのままCloudTrailとConfig。CloudWatch(性能)やフローログ(通信)は監査の的が違う。
  <div class="dh">⚠️ つまずきやすい言葉</div>
  <b>監査系は守備範囲で割る＝操作(CloudTrail)／構成(Config)／脅威検知(GuardDuty)／性能(CloudWatch)／通信(フローログ)。</b>要件の名詞(操作・構成)に対応させる。`
},
{
  id:86, cat:"サーバーレス", multi:true,
  scenario:"あるサービスで、ユーザーがS3に画像をアップロードすると、サムネイル生成とメタデータ抽出を自動で行いたい。サーバーは常時起動せず、アップロードの度に処理が走る形にしたい。処理が重くなったり一時的に失敗したりしても取りこぼさないようにしたい。",
  ask:'サーバーレスで自動処理を疎結合に組む構成として有効なものはどれですか。（2 つ選択）',
  options:[
    "EC2を常時起動してS3を1分ごとにポーリングし、新しい画像があれば処理する。",
    "S3イベント通知でアップロードをトリガにLambdaを起動し、サムネイル生成とメタデータ抽出を実行する。",
    "アップロードされた画像をCloudFront経由で配信し、表示を高速化する。",
    "S3イベントをSQSに送り、Lambdaがキューから取り出して処理することで、急増やリトライに耐えるようにする。",
    "アップロードのたびにSNSで管理者にメール通知し、担当者が手動でサムネイルを生成する。"
  ],
  answer:[1,3],
  keypoint:'2つ選ぶ問題。「アップロードの度に自動＋サーバー常時起動なし→S3イベント＋Lambda」「取りこぼさない→間にSQSを挟みリトライ/バッファ」。BとDが要件に直結。Aは常時起動でサーバーレスでなく、Cは配信の話、Eは手動処理で自動化にならない。',
  explain:'B＝S3イベント通知でLambdaを起動すれば、アップロードの度にサーバーレスで処理が走る。D＝S3イベントをSQSに入れてLambdaが取り出す形にすると、急増のバッファと失敗時のリトライ(可視性タイムアウト＋DLQ)が効き取りこぼしを防げる。サーバーレス＋疎結合の定石。',
  elim:'A＝EC2を常時起動してポーリングはサーバーレスでなく、アイドル時もコストがかかり即時性も劣る。C＝CloudFrontは配信(ダウンロード)を速くする機能で、アップロード後の処理起動とは無関係。E＝手動処理は自動化の要件に反し、量が増えると破綻する。正解はB・D。',
  confusion:'<b>「◯◯されたら自動＋常時起動したくない」＝S3イベント＋Lambda／「取りこぼさない・急増に耐える」＝間にSQS(バッファ＋リトライ＋DLQ)。</b>イベント駆動とキューはサーバーレス処理の鉄板の組み合わせ。',
  deep:`
  <div class="dh">🏷 出てきたものの「あだ名」</div>
  <div class="nick"><b>S3イベント＋Lambda</b>＝「荷物が届いたら呼び鈴が鳴って、出張スタッフ(Lambda)が来て処理する」。常駐スタッフを雇わなくていい。</div>
  <div class="nick"><b>間にSQS</b>＝呼び鈴と作業の間に「整理券の箱」を置く。一度に大量に届いても溜めておけるし、失敗した分はもう一度呼べる(リトライ)。</div>
  <div class="dh">💡 なぜこれが正解か</div>
  「届いたら自動＋常駐なし＋取りこぼさない」＝呼び鈴(S3イベント)＋出張スタッフ(Lambda)＋整理券の箱(SQS)。常時ポーリングのEC2や配信のCloudFrontは要件に合わない。
  <div class="dh">⚠️ つまずきやすい言葉</div>
  <b>サーバーレスの自動処理＝イベント駆動(S3/EventBridge)で起動。常時ポーリングは"サーバーレスでない"サイン。</b>`
}
);

QUESTIONS.push(
{
  id:87, cat:"配信/CDN", multi:true,
  scenario:"あるグローバルなWebサービスが、世界中のユーザーから『表示が遅い』と指摘されている。静的アセット(画像・JS・CSS)はすべて単一リージョンのサーバーから配信し、アプリのエンドポイントも1つのリージョンに固定されている。世界中のユーザーの体感速度を、なるべく最寄りから応答する形で改善したい。",
  ask:'グローバルな表示速度の改善に有効なものはどれですか。（2 つ選択）',
  options:[
    "静的アセットをS3＋CloudFrontで配信し、世界中のエッジロケーションでキャッシュしてユーザーの近くから返す。",
    "全ユーザーを単一リージョンの大型インスタンスに集約し、サーバー性能を上げて対応する。",
    "クライアント側のリクエストタイムアウトを長くして、遅くてもエラーになりにくくする。",
    "Route 53のレイテンシーベースルーティングで、ユーザーを最も低遅延なリージョンのエンドポイントへ誘導する。",
    "オリジンサーバーのインスタンスタイプを最新世代に変更してCPU性能を引き上げる。"
  ],
  answer:[0,3],
  keypoint:'2つ選ぶ問題。「最寄りから応答」＝CloudFront(静的をエッジキャッシュ)＋Route 53レイテンシールーティング(動的を最寄りリージョンへ)。AとDが地理的な遅延を縮める。Bは単一リージョンのままで遠方が遅い、Cは体感を誤魔化すだけ、Eは性能増だが距離は縮まらない。',
  explain:'A＝CloudFrontは静的アセットを世界中のエッジでキャッシュし、ユーザーに近い場所から配信して遅延を縮める。D＝Route 53のレイテンシーベースルーティングは、各ユーザーを最も低遅延なリージョンのエンドポイントへ振り分ける。静的・動的の両面で最寄り化する2つ。',
  elim:'B＝単一リージョンに集約してインスタンスを大きくしても、遠方ユーザーの物理距離による遅延は縮まらない。C＝タイムアウトを延ばすのは遅さを許容するだけで、表示速度の改善ではない。E＝オリジンの性能を上げても遠方からの距離は変わらず、グローバルの遅延は縮まらない。正解はA・D。',
  confusion:'<b>静的コンテンツを最寄りから＝CloudFront(エッジキャッシュ)／動的リクエストを最寄りリージョンへ＝Route 53レイテンシールーティング。</b>グローバルの遅延は"距離を縮める"の一点。集約や性能増では遠方は速くならない。',
  deep:`
  <div class="dh">🏷 出てきたものの「あだ名」</div>
  <div class="nick"><b>CloudFront</b>＝世界中の支店から「配る」CDN。画像やJSを近所の支店から渡すので速い。</div>
  <div class="nick"><b>Route 53レイテンシールーティング</b>＝「一番早く着く店はどこ?」をDNSで判断し、最寄りリージョンの窓口へ案内する。</div>
  <div class="dh">💡 なぜこれが正解か</div>
  「世界中で遅い＝距離が遠い」が原因。だから支店から配る(CloudFront)＋最寄り窓口へ案内(Route 53)で距離を縮める。1か所に集約して性能を上げても遠方の距離は縮まらない。
  <div class="dh">⚠️ つまずきやすい言葉</div>
  <b>グローバルの遅延対策は「最寄り化」。</b>サーバーを大きくする(垂直スケール)は距離の問題には効かない。`
},
{
  id:88, cat:"セキュリティ", multi:true,
  scenario:"ある企業が、機密性の高い顧客データをS3に保管している。監査から『データが誤って公開されない』ことと『保存データが暗号化され、鍵へのアクセスが制御されている』ことを求められた。誤設定による情報漏洩を防ぎつつ、暗号化と鍵管理をマネージドに行いたい。",
  ask:'機密データの保護に直接寄与するものはどれですか。（2 つ選択）',
  options:[
    "データを公開バケットに置き、URLを知っている人だけがアクセスできる運用にする。",
    "S3のパブリックアクセスブロックを有効にし、バケットポリシーでも公開を禁止して誤公開を防ぐ。",
    "保存データをSSE-KMSで暗号化し、暗号鍵へのアクセスをIAM/キーポリシーで必要な主体だけに制限する。",
    "全てのIAMユーザーにs3:* を許可し、誰でもデータを操作できるようにして運用を簡単にする。",
    "S3 Transfer Accelerationを有効にして、アップロードの速度を向上させる。"
  ],
  answer:[1,2],
  keypoint:'2つ選ぶ問題。「誤公開を防ぐ→パブリックアクセスブロック」「暗号化＋鍵のアクセス制御→SSE-KMS＋鍵ポリシー」。BとCが機密保護に直結。Aは実質公開で危険、Dは過剰権限、Eは速度向上で保護とは無関係。',
  explain:'B＝パブリックアクセスブロックとバケットポリシーの公開禁止で、誤設定による公開を防げる。C＝SSE-KMSで保存データを暗号化し、鍵へのアクセスをIAM/キーポリシーで絞れば、暗号化と鍵管理の両方を満たす。機密データ保護の定石。',
  elim:'A＝「URLを知る人だけ」は実質的に公開状態で、URLが漏れれば誰でもアクセスできる＝危険。D＝全員にs3:*は最小権限の真逆で、1人の漏洩が全データの漏洩につながる。E＝Transfer Accelerationはアップロード速度の機能で、誤公開防止や暗号化といった保護とは無関係。正解はB・C。',
  confusion:'<b>誤公開防止＝パブリックアクセスブロック＋公開禁止ポリシー／暗号化＋鍵管理＝SSE-KMS＋キーポリシー/IAM。</b>「機密データを守る」は"公開させない"と"暗号化して鍵を絞る"の2点セット。',
  deep:`
  <div class="dh">🏷 出てきたものの「あだ名」</div>
  <div class="nick"><b>パブリックアクセスブロック</b>＝「外に出すドアを溶接して塞ぐ」設定。うっかり公開設定にしても外には出ない。</div>
  <div class="nick"><b>SSE-KMS＋キーポリシー</b>＝中身を「金庫(暗号化)」に入れ、その金庫の鍵を「決めた人だけ」が持てるようにする。</div>
  <div class="dh">💡 なぜこれが正解か</div>
  「誤公開させない＋暗号化して鍵を絞る」がそのまま要件。ドアを塞ぎ(パブリックブロック)、金庫に入れて鍵を限定(SSE-KMS)。公開URL運用や全員s3:*は真逆。
  <div class="dh">⚠️ つまずきやすい言葉</div>
  <b>「URLを知る人だけ＝安全」は誤り。</b>URLは漏れる前提で、公開そのものを塞ぎ暗号化＋鍵制御で守る。`
}
);

// ============================================================
// 本番再現スタイルの追加（2026-06-19 saa-realexam）id89〜
// 「必要なコンポーネントを2つ選択」式。5択から2つ。選択肢はサービス名だけのそっけない短文。
// ============================================================
QUESTIONS.push(
{
  id:89, cat:"可用性", multi:true,
  scenario:"ある企業は、Amazon EC2 インスタンスで実行されている本番アプリケーションを運用しています。同社の運用チームは、インスタンスの CPU 使用率が定義したしきい値を一定時間にわたって超過した場合に、担当者へ自動的に通知が届くようにする必要があります。同社は、この通知の仕組みをマネージドなサービスを組み合わせて構成したいと考えています。また、同社は、通知の仕組みに伴う運用上のオーバーヘッドを最小限に抑える必要があります。",
  ask:'この通知の仕組みを構築するために必要なコンポーネントはどれですか。（2 つ選択）',
  options:[
    "Amazon CloudWatch アラーム",
    "Amazon SNS トピック",
    "AWS Config ルール",
    "Amazon Athena",
    "AWS Glue クローラー"
  ],
  answer:[0,1],
  keypoint:'5択から2つ。やりたいのは「メトリクスがしきい値を超えたら通知」。<b>しきい値の監視＝CloudWatchアラーム</b>、<b>通知の送信＝SNSトピック</b>の2つが必要。残りは正しいサービスだが、監視→通知の用途には噛み合わない。',
  explain:'A＝CloudWatchアラームはCPU使用率などのメトリクスを監視し、しきい値超過が一定時間続くとアクションを発火する。B＝そのアラームのアクション先にSNSトピックを指定すれば、メール等で担当者に通知できる。CloudWatchアラーム→SNSが標準的な通知パイプラインで、マネージドのため運用負荷も小さい。',
  elim:'C=Configルールは「リソース構成が基準から逸脱していないか」を評価するもので、CPU使用率などの性能メトリクス監視ではない。D=AthenaはS3上のデータにSQLでクエリする分析サービス。E=Glueクローラーはデータのスキーマを検出するETLの部品。CもDもEも本物のサービスだが、メトリクス監視と通知という用途には使わない。',
  confusion:'<b>メトリクス監視＋しきい値判定＝CloudWatchアラーム／通知の配信＝SNS。</b>「○○を超えたら知らせる」と来たらCloudWatchアラーム→SNSの組み合わせ。Config（構成監査）・Athena/Glue（分析・ETL）と混同しない。',
  deep:`
  <div class="dh">🏷 出てきたものの「あだ名」</div>
  <div class="nick"><b>CloudWatchアラーム</b>＝メーターの見張り番。「針が赤いゾーンにこれだけ入ったら笛を吹く」役。</div>
  <div class="nick"><b>SNSトピック</b>＝拡声器付きの連絡網。笛が鳴ったら登録した宛先（メール等）へ一斉に知らせる。</div>
  <div class="nick"><b>Config</b>＝間取りの監査役（構成のズレを見る）。<b>Athena</b>＝S3に置いたデータへの質問係（SQL分析）。<b>Glueクローラー</b>＝データの中身を見て目録を作る係。いずれも監視通知の部品ではない。</div>
  <div class="dh">💡 なぜA・Bが正解か</div>
  「メトリクスがしきい値超過→通知」は、見張り番(CloudWatchアラーム)が異常を捉え、連絡網(SNS)が知らせる、の2部品でできている。どちらもマネージドなので運用上のオーバーヘッドが小さい。
  <div class="dh">⚠️ つまずきやすい言葉</div>
  <b>本番では選択肢がサービス名だけのそっけない形で並ぶことがある。</b>各サービスが「何をするものか」を一言で言えれば、用途の合う2つを選べる。Config・Athena・Glueはどれも正しいサービスなので「知らないから消す」が効かない。`
}
);


// ============================================================
// 「どのサービス/タイプを使うべきか」型の追加（2026-06-20 saa-v2-serviceselect）id90〜97
// 本番にある「選択肢がサービス名・タイプ名だけ」の知識直球型。シナリオは本番調・選択肢はそっけなく。
// ============================================================
QUESTIONS.push(
{
  id:90, cat:"ストレージ",
  scenario:"ある企業は、ミッションクリティカルなリレーショナルデータベースを Amazon EC2 上で運用しています。このデータベースは、常時にわたって高い IOPS と一貫した一桁ミリ秒のレイテンシーを必要とします。同社は、このワークロードに最も適した Amazon EBS ボリュームタイプを選択する必要があります。",
  ask:'このデータベースに最も適した EBS ボリュームタイプはどれですか。',
  options:[
    "プロビジョンド IOPS SSD (io2)",
    "汎用 SSD (gp3)",
    "スループット最適化 HDD (st1)",
    "Cold HDD (sc1)"
  ],
  answer:0,
  keypoint:'4つとも実在のEBSタイプ。「高IOPS＋一貫した低レイテンシ＋ミッションクリティカル」を満たすのはどれか。SSD系かHDD系か、汎用か高性能保証かで切る。',
  explain:'A＝プロビジョンドIOPS SSD（io2）はIOPSを明示的に指定して保証でき、最も高い性能と一貫した低レイテンシを提供する。ミッションクリティカルな高IOPSデータベース向けの定番。',
  elim:'B=gp3は汎用SSDで多くの用途に十分だが、最高水準のIOPS保証・一貫性ではio2に劣る。C=st1（スループット最適化HDD）は大容量シーケンシャル（ログ/ビッグデータ）向けで、ランダムIOPSが要るDBには不向き。D=sc1（Cold HDD）は低頻度アクセスの最安HDDで性能が最も低い。高IOPS・低レイテンシ保証はio2。',
  confusion:'<b>io2</b>＝高IOPS保証・低レイテンシ（重要DB）／<b>gp3</b>＝汎用SSD（コスパ）／<b>st1</b>＝大容量シーケンシャル（スループット）／<b>sc1</b>＝最安・低頻度。ランダムIOPSの保証が要る＝io2。',
  deep:`
  <div class="dh">🏷 たとえ</div>
  <div class="nick"><b>io2</b>＝速さを契約で保証する高級回線。重要DBはこれ。</div>
  <div class="nick"><b>gp3</b>＝十分速い標準回線（多くはこれで足りる）。</div>
  <div class="nick"><b>st1/sc1</b>＝HDD。大量を流す（st1）・安く寝かせる（sc1）用で、細かい速さは出ない。</div>
  <div class="dh">💡 なぜAが正解か</div>
  「一貫した高IOPS・低レイテンシ・ミッションクリティカル」はIOPSを保証できるio2の領域。HDD（st1/sc1）はランダムIOが弱く、gp3は保証水準でio2に一歩譲る。
  <div class="dh">⚠️ つまずきやすい言葉</div>
  「スループット最適化（st1）」を速そうと誤読しない。st1は<b>大きな塊を連続で流す</b>のが得意で、DBの<b>細かいランダムアクセス（IOPS）</b>とは別物。`
},
{
  id:91, cat:"データベース",
  scenario:"ある企業は、新しいモバイルアプリケーションのバックエンドを設計しています。このアプリケーションは、ユーザーのプロフィールやセッションといったキーと値の形式のデータを扱い、数ミリ秒の応答を必要とします。トラフィックは予測が難しく、急激に増減します。同社は、サーバーの管理を行わず、スケーリングを自動に任せられるデータベースを必要としています。",
  ask:'この要件に最も適したデータベースはどれですか。',
  options:[
    "Amazon RDS for MySQL",
    "Amazon DynamoDB",
    "Amazon Redshift",
    "Amazon Neptune"
  ],
  answer:1,
  keypoint:'4つとも実在のDBサービス。「キーと値」「数ミリ秒」「予測不能な変動」「サーバー管理なし・自動スケール」に最も合うのはどれか。データモデルで切る。',
  explain:'B＝DynamoDBはキーバリュー/ドキュメント型のフルマネージドNoSQLで、数ミリ秒の応答・オンデマンドで予測不能な変動への自動スケール・サーバー管理不要を満たす。まさにこの用途向け。',
  elim:'A=RDS for MySQLはリレーショナルで、インスタンス管理やスケーリングの手間があり予測不能な急変動への自動追従が弱い。C=Redshiftは分析用データウェアハウス（OLAP）で、低レイテンシのキーバリューアクセス用ではない。D=Neptuneはグラフデータベースで、関係をたどる用途向け（キーバリューではない）。要件適合でDynamoDB。',
  confusion:'<b>DynamoDB</b>＝キーバリュー/ドキュメント・低レイテンシ・自動スケール／<b>RDS/Aurora</b>＝リレーショナル／<b>Redshift</b>＝分析(DWH)／<b>Neptune</b>＝グラフ。データの形で選ぶ。',
  deep:`
  <div class="dh">🏷 たとえ</div>
  <div class="nick"><b>DynamoDB</b>＝伸縮自在のロッカー。鍵（キー）を出せば中身が即出る。客が急に増えても勝手に棚が増える。</div>
  <div class="nick"><b>Redshift</b>＝大量データを集計する分析室（即答用ではない）。<b>Neptune</b>＝人脈図をたどる専門。</div>
  <div class="dh">💡 なぜBが正解か</div>
  「キーバリュー＋数ミリ秒＋予測不能な変動＋サーバー管理なし」はDynamoDBの土俵。RDSは管理と急変動追従で負け、Redshift/Neptuneはデータモデルが違う。
  <div class="dh">⚠️ つまずきやすい言葉</div>
  「データベース＝とりあえずRDS」と反射しない。<b>キーバリュー・サーバーレス・自動スケール</b>が出たらDynamoDB。`
},
{
  id:92, cat:"高性能",
  scenario:"ある企業は、毎秒数百万のリクエストを処理する必要のある TCP ベースのアプリケーションを運用しています。このアプリケーションは、極めて低いレイテンシーと、クライアントの許可リストに登録するための静的な IP アドレスを必要とします。同社は、このトラフィックを分散するために最も適したロードバランサーを選択する必要があります。",
  ask:'この要件に最も適したロードバランサーはどれですか。',
  options:[
    "Application Load Balancer (ALB)",
    "Gateway Load Balancer (GWLB)",
    "Network Load Balancer (NLB)",
    "Classic Load Balancer (CLB)"
  ],
  answer:2,
  keypoint:'4つとも実在のロードバランサー。「TCP」「毎秒数百万・超低遅延」「静的IP」を満たすのはどれか。動作レイヤー（L4かL7か）で切る。',
  explain:'C＝NLBはL4（TCP/UDP）で動作し、極めて低いレイテンシで毎秒数百万のリクエストを捌け、静的IP（Elastic IP）を割り当てられる。TCP・超低遅延・静的IPの要件にぴったり。',
  elim:'A=ALBはL7（HTTP/HTTPS）向けで、パスやホストでのルーティングが得意だが静的IPは持たず超低遅延TCPの土俵ではない。B=GWLBはサードパーティ仮想アプライアンス（ファイアウォール等）を挟むためのもので、一般的なアプリ分散ではない。D=CLBは旧世代で新規利用は非推奨。TCP・超低遅延・静的IPはNLB。',
  confusion:'<b>NLB</b>＝L4・TCP/UDP・超低遅延・静的IP／<b>ALB</b>＝L7・HTTP・パス/ホストルーティング／<b>GWLB</b>＝仮想アプライアンス挿入／<b>CLB</b>＝旧世代。静的IP・TCPが出たらNLB。',
  deep:`
  <div class="dh">🏷 たとえ</div>
  <div class="nick"><b>NLB</b>＝住所（静的IP）が変わらない超高速の交通整理。中身（HTTPの内容）は見ず、速くさばく。</div>
  <div class="nick"><b>ALB</b>＝中身（URL）を見て振り分ける案内係。賢いが住所は固定でない。</div>
  <div class="dh">💡 なぜCが正解か</div>
  「TCP＋超低遅延＋静的IP」はL4のNLBの専売。ALBはHTTP向けで静的IPを持たず、GWLBは用途が特殊、CLBは旧世代。
  <div class="dh">⚠️ つまずきやすい言葉</div>
  「とりあえずALB」と反射しない。<b>静的IP・TCP/UDP・極低遅延・超高スループット</b>が出たらNLB。`
}
);

QUESTIONS.push(
{
  id:93, cat:"データベース",
  scenario:"ある企業は、オンプレミスで稼働している Oracle データベースを、Amazon Aurora PostgreSQL へ移行しようとしています。これは異なるデータベースエンジン間の移行であり、テーブル定義やストアドプロシージャなどのスキーマを変換する必要があります。同社は、移行中のダウンタイムを最小限に抑える必要があります。",
  ask:'この移行に最も適したサービスの組み合わせはどれですか。',
  options:[
    "AWS DataSync",
    "AWS Snowball Edge",
    "AWS Storage Gateway",
    "AWS Database Migration Service (DMS) と AWS Schema Conversion Tool (SCT)"
  ],
  answer:3,
  keypoint:'4つとも実在の移行/転送サービス。「異なるDBエンジン間（Oracle→Aurora PostgreSQL）」「スキーマ変換」「ダウンタイム最小」を満たすのはどれか。',
  explain:'D＝DMSはデータベースを継続レプリケーションしながら移行でき（ダウンタイム最小）、SCTは異種エンジン間のスキーマ（テーブル定義・ストアドプロシージャ）を変換する。異種DB移行の標準コンビ。',
  elim:'A=DataSyncはファイル/オブジェクトの転送（NFS/SMB/S3等）で、DBのスキーマ変換や継続レプリはしない。B=Snowball Edgeは物理デバイスでの大容量データ移送で、異種DB移行・スキーマ変換の用途ではない。C=Storage GatewayはオンプレとS3をつなぐハイブリッドストレージで、DB移行ツールではない。異種DB移行はDMS＋SCT。',
  confusion:'<b>DMS＋SCT</b>＝異種DB移行（継続レプリ＋スキーマ変換）／<b>DataSync</b>＝ファイル転送／<b>Snowball</b>＝物理移送／<b>Storage Gateway</b>＝ハイブリッドストレージ。「DBエンジンが変わる移行」はDMS＋SCT。',
  deep:`
  <div class="dh">🏷 たとえ</div>
  <div class="nick"><b>DMS</b>＝引っ越し中も営業を止めない引っ越し業者（継続レプリでダウンタイム最小）。</div>
  <div class="nick"><b>SCT</b>＝Oracle語をPostgreSQL語に翻訳する通訳（スキーマ変換）。</div>
  <div class="dh">💡 なぜDが正解か</div>
  「エンジンが変わる（異種）＋スキーマ変換＋止めたくない」＝翻訳（SCT）＋無停止移送（DMS）の二人組。DataSync/Snowball/Storage GatewayはDBの中身を翻訳・継続レプリしない。
  <div class="dh">⚠️ つまずきやすい言葉</div>
  同種エンジン同士ならSCTは不要だが、<b>Oracle→PostgreSQLのように種類が変わる</b>とスキーマ変換（SCT）が要る。`
},
{
  id:94, cat:"高性能",
  scenario:"ある企業は、大量のログファイルを Amazon S3 に保存しています。同社のアナリストは、これらのログに対して、必要なときに標準的な SQL を使ってアドホックなクエリを実行したいと考えています。クエリの頻度は不定期です。同社は、クエリ用のサーバーやインフラストラクチャを管理することなく、実行したクエリの分だけ支払う方法を必要としています。",
  ask:'この要件に最も適したサービスはどれですか。',
  options:[
    "Amazon Athena",
    "Amazon Redshift",
    "Amazon EMR",
    "Amazon Kinesis Data Streams"
  ],
  answer:0,
  keypoint:'4つとも実在の分析系サービス。「S3のデータにSQL」「アドホック・不定期」「インフラ管理なし・実行分だけ課金」を満たすのはどれか。',
  explain:'A＝AthenaはS3上のデータに直接、標準SQLでクエリできるサーバーレスのサービス。インフラ管理が不要で、スキャンした分だけ課金される。不定期・アドホックなクエリに最適。',
  elim:'B=RedshiftはDWHでクラスタを常時プロビジョニング・管理する必要があり、不定期アドホックには過剰でコスト効率が悪い。C=EMRはHadoop/Sparkのクラスタを立てる分散処理基盤で、管理が必要。D=Kinesis Data Streamsはリアルタイムのストリーミング取り込みで、S3への蓄積済みログへのSQLクエリ用ではない。サーバーレスSQLはAthena。',
  confusion:'<b>Athena</b>＝S3に直接SQL・サーバーレス・従量（アドホック）／<b>Redshift</b>＝常時稼働DWH（定常・大規模分析）／<b>EMR</b>＝Hadoop/Sparkクラスタ／<b>Kinesis</b>＝ストリーミング取り込み。S3にたまにSQL＝Athena。',
  deep:`
  <div class="dh">🏷 あだ名</div>
  <div class="nick"><b>Athena</b>＝S3に置いたデータへ「その場で質問（SQL）」できる窓口。店（サーバー）を構えず、聞いた分だけ払う。</div>
  <div class="nick"><b>Redshift</b>＝常設の分析室（毎日大量に分析するなら得・たまにだと維持費が無駄）。</div>
  <div class="dh">💡 なぜAが正解か</div>
  「S3に・SQLで・たまに・管理なし・従量」はAthenaそのもの。Redshift/EMRはクラスタ管理が要り不定期には過剰、Kinesisは取り込み用で蓄積データのSQLではない。
  <div class="dh">⚠️ つまずきやすい言葉</div>
  「分析＝Redshift」と反射しない。<b>S3に置いたまま・アドホック・サーバー管理なし</b>ならAthena。常時の大規模分析ならRedshift。`
},
{
  id:95, cat:"ストレージ",
  scenario:"ある企業は、医療画像のアーカイブを Amazon S3 に保管しています。これらのデータへのアクセスは四半期に 1 回程度とまれですが、アクセスが必要になった際にはミリ秒単位ですぐに取り出せることが求められます。同社は、この特性のデータについて、保管コストを可能な限り低く抑える必要があります。",
  ask:'この要件に最も適した S3 ストレージクラスはどれですか。',
  options:[
    "S3 Standard-IA",
    "S3 Glacier Instant Retrieval",
    "S3 Glacier Deep Archive",
    "S3 One Zone-IA"
  ],
  answer:1,
  keypoint:'4つとも実在のストレージクラス。「アクセスはまれ（四半期1回）」「でも取り出しは即時（ミリ秒）」「保管コスト最安」を同時に満たすのはどれか。',
  explain:'B＝Glacier Instant Retrievalは、四半期に1回程度のまれなアクセスでありながらミリ秒で即時取り出しが必要なデータ向けに、Standard-IAより安い保管単価を提供する。「即時取り出し＋低頻度＋最安」の組み合わせに最適。',
  elim:'A=Standard-IAは月1回程度のアクセス向けで即時取り出せるが、四半期1回のさらにまれなアクセスではGlacier Instant Retrievalより保管単価が高い。C=Glacier Deep Archiveは最安だが取り出しに数時間かかり「ミリ秒」に反する。D=One Zone-IAは単一AZで耐久性が下がり、医療アーカイブの保管には不適。即時＋低頻度＋最安はGlacier Instant Retrieval。',
  confusion:'<b>Glacier Instant Retrieval</b>＝まれなアクセス＋即時取り出し＋低コスト／<b>Standard-IA</b>＝月1回程度／<b>Glacier Deep Archive</b>＝最安だが取り出し数時間／<b>One Zone-IA</b>＝単一AZで安いが耐久性低。「即時だがめったに使わない」がIRの狙い目。',
  deep:`
  <div class="dh">🏷 たとえ</div>
  <div class="nick"><b>Glacier Instant Retrieval</b>＝めったに開けないが、開けたら即出せる安い金庫。</div>
  <div class="nick"><b>Deep Archive</b>＝もっと安いが、出すのに半日かかる倉庫の奥（即時不可）。</div>
  <div class="dh">💡 なぜBが正解か</div>
  「めったに使わない＋でも即時＋最安」を同時に満たすのがGlacier Instant Retrieval。Deep Archiveは即時取り出しできず、Standard-IAはここまで低頻度だと割高、One Zone-IAは耐久性で不適。
  <div class="dh">⚠️ つまずきやすい言葉</div>
  「即時取り出し」が要るかが分かれ目。<b>即時が要る＋低頻度＝Instant Retrieval</b>／即時不要で最安＝Deep Archive。`
}
);

QUESTIONS.push(
{
  id:96, cat:"セキュリティ",
  scenario:"ある企業は、規制上の要件により、暗号鍵を専用のシングルテナントなハードウェアセキュリティモジュール (HSM) で管理し、その鍵への完全な制御を自社で保持する必要があります。さらに、この HSM は FIPS 140-2 レベル 3 に準拠している必要があります。同社は、この要件を満たす鍵管理の方法を選択する必要があります。",
  ask:'この要件に最も適したサービスはどれですか。',
  options:[
    "AWS Key Management Service (KMS)",
    "AWS Secrets Manager",
    "AWS CloudHSM",
    "AWS Certificate Manager (ACM)"
  ],
  answer:2,
  keypoint:'4つとも実在のセキュリティ/鍵関連サービス。「専用シングルテナントHSM」「鍵の完全な自社制御」「FIPS 140-2 レベル3」を満たすのはどれか。',
  explain:'C＝CloudHSMはAWS上に専有（シングルテナント）のハードウェアセキュリティモジュールを提供し、FIPS 140-2 レベル3準拠で、鍵の生成・管理を顧客が完全に制御できる。専用HSM・完全制御の要件はCloudHSM。',
  elim:'A=KMSはマネージドな鍵管理で便利だが、共有基盤（マルチテナント）で「専用シングルテナントHSM・完全な自社制御」という要件には合わない。B=Secrets Managerは認証情報の保管・ローテーションで、HSMによる鍵管理ではない。D=ACMはTLS証明書の管理で、汎用の暗号鍵HSMではない。専用HSMはCloudHSM。',
  confusion:'<b>CloudHSM</b>＝専有HSM・FIPS 140-2 レベル3・鍵を完全自社制御／<b>KMS</b>＝マネージド鍵管理（共有基盤・手軽）／<b>Secrets Manager</b>＝秘密情報の保管・ローテ／<b>ACM</b>＝TLS証明書。「専用HSM・完全制御・FIPS L3」が出たらCloudHSM。',
  deep:`
  <div class="dh">🏷 たとえ</div>
  <div class="nick"><b>KMS</b>＝銀行の共用貸金庫（手軽で十分安全だが箱は共有設備）。</div>
  <div class="nick"><b>CloudHSM</b>＝自社専用の金庫室を1部屋まるごと借りる（中の鍵は自分しか触れない・規格認証つき）。</div>
  <div class="dh">💡 なぜCが正解か</div>
  「専用（シングルテナント）HSM・鍵の完全な自社制御・FIPS 140-2 レベル3」という強い規制要件を満たすのはCloudHSM。KMSは手軽だが共有基盤でこの要件には届かない。
  <div class="dh">⚠️ つまずきやすい言葉</div>
  普段の暗号化はKMSで十分。<b>「専用HSM」「FIPS 140-2 レベル3」「鍵を完全に自社管理」</b>という言葉が出たらCloudHSMに上げる。`
},
{
  id:97, cat:"配信/CDN",
  scenario:"ある企業は、Amazon Route 53 で管理しているドメインを使って Web アプリケーションを公開しています。同社は、新しいバージョンのアプリケーションをデプロイするにあたり、まずは全体のうち 10 パーセントのトラフィックだけを新バージョンへ送り、問題がないことを確認してから段階的に割合を増やしたいと考えています。同社は、この段階的な移行を実現する Route 53 のルーティングポリシーを選択する必要があります。",
  ask:'この要件に最も適した Route 53 のルーティングポリシーはどれですか。',
  options:[
    "シンプルルーティング",
    "レイテンシーベースルーティング",
    "位置情報ルーティング",
    "加重ルーティング"
  ],
  answer:3,
  keypoint:'4つとも実在のRoute 53ルーティングポリシー。「10%だけ新バージョンへ→段階的に増やす（カナリア）」を実現するのはどれか。何を基準に振り分けるかで切る。',
  explain:'D＝加重ルーティングは、各レコードに重み（割合）を設定してトラフィックを比率で振り分けられる。新バージョンに10%、旧に90%のように配分し、徐々に重みを上げる段階移行（カナリアリリース）に使える。',
  elim:'A=シンプルルーティングは1つの宛先に流すだけで割合配分ができない。B=レイテンシーベースは最も低遅延なリージョンへ振り分けるもので割合制御ではない。C=位置情報ルーティングはユーザーの地理的位置で振り分けるもので、段階移行の割合制御ではない。比率で振り分けるのは加重ルーティング。',
  confusion:'<b>加重ルーティング</b>＝割合で振り分け（カナリア/ABテスト）／<b>レイテンシー</b>＝最速リージョンへ／<b>位置情報</b>＝地理で／<b>フェイルオーバー</b>＝障害時切替／<b>シンプル</b>＝単一宛先。「○%だけ流す」は加重。',
  deep:`
  <div class="dh">🏷 たとえ</div>
  <div class="nick"><b>加重ルーティング</b>＝来客を「新店1割・旧店9割」のように割合で振り分けるダイヤル。少しずつ新店の比率を上げられる。</div>
  <div class="nick"><b>レイテンシー/位置情報</b>＝「近い方/地域で」案内する別の基準（割合では振らない）。</div>
  <div class="dh">💡 なぜDが正解か</div>
  「10%だけ新バージョンへ→徐々に増やす」は割合で配分するカナリアの動き＝加重ルーティング。他のポリシーは振り分けの基準が割合ではない。
  <div class="dh">⚠️ つまずきやすい言葉</div>
  Route 53のポリシーは「何を基準に振るか」で覚える＝<b>割合＝加重／速さ＝レイテンシー／地域＝位置情報／障害＝フェイルオーバー</b>。`
}
);
